def _packaged_acceptance_summary_paths(base_dir: Optional[Path] = None) -> Dict[str, Optional[Path]]:
    base = Path(base_dir or _app_base_dir()).resolve()
    roots = [base.parent.parent, base.parent]

    def _first_existing(paths: list[Path]) -> Optional[Path]:
        for path in paths:
            try:
                if path.exists():
                    return path
            except Exception:
                continue
        return None

    txt_candidates: list[Path] = []
    json_candidates: list[Path] = []
    for root in roots:
        txt_candidates.extend([
            root / "PACKAGED_ACCEPTANCE_SUMMARY.txt",
            root / "_acceptance_artifacts" / "packaged_acceptance_summary.txt",
        ])
        json_candidates.extend([
            root / "PACKAGED_ACCEPTANCE_SUMMARY.json",
            root / "_acceptance_artifacts" / "packaged_acceptance_summary.json",
        ])
    return {
        "text": _first_existing(txt_candidates),
        "json": _first_existing(json_candidates),
    }


def _runtime_package_status_record(
    *,
    base_dir: Optional[Path] = None,
    build_identity: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    acceptance_paths = _packaged_acceptance_summary_paths(base_dir)
    runtime_root = Path(base_dir or _app_base_dir()).resolve().parent
    if evaluate_runtime_package_status is None:
        return {
            "package_status": "UNVERIFIED",
            "package_status_summary": "Package verification helper is unavailable.",
            "package_status_detail": "Package verification helper is unavailable.",
            "package_status_details": ["Package verification helper is unavailable."],
            "packaged_acceptance_status": "",
            "packaged_acceptance_generated_at": "",
            "packaged_acceptance_summary_path": str(acceptance_paths.get("text")) if isinstance(acceptance_paths.get("text"), Path) else "",
            "packaged_acceptance_summary_json_path": str(acceptance_paths.get("json")) if isinstance(acceptance_paths.get("json"), Path) else "",
            "install_root_path": "",
            "install_manifest_path": "",
            "installed_runtime_path": "",
            "installed_bundle_label": "",
            "local_accepted_package_marker_path": "",
            "local_accepted_package_label": "",
            "uninstall_registry_install_location": "",
            "uninstall_registry_display_version": "",
            "uninstall_registry_key": "",
        }
    try:
        result = evaluate_runtime_package_status(
            current_runtime_root=runtime_root,
            current_build_identity=(build_identity or _load_build_identity(base_dir)),
            current_acceptance_summary_path=acceptance_paths.get("json"),
        )
        result["packaged_acceptance_summary_path"] = str(acceptance_paths.get("text")) if isinstance(acceptance_paths.get("text"), Path) else ""
        result["packaged_acceptance_summary_json_path"] = str(acceptance_paths.get("json")) if isinstance(acceptance_paths.get("json"), Path) else ""
        return result
    except Exception:
        return {
            "package_status": "UNVERIFIED",
            "package_status_summary": "Package verification check failed.",
            "package_status_detail": "Package verification check failed.",
            "package_status_details": ["Package verification check failed."],
            "packaged_acceptance_status": "",
            "packaged_acceptance_generated_at": "",
            "packaged_acceptance_summary_path": str(acceptance_paths.get("text")) if isinstance(acceptance_paths.get("text"), Path) else "",
            "packaged_acceptance_summary_json_path": str(acceptance_paths.get("json")) if isinstance(acceptance_paths.get("json"), Path) else "",
            "install_root_path": "",
            "install_manifest_path": "",
            "installed_runtime_path": "",
            "installed_bundle_label": "",
            "local_accepted_package_marker_path": "",
            "local_accepted_package_label": "",
            "uninstall_registry_install_location": "",
            "uninstall_registry_display_version": "",
            "uninstall_registry_key": "",
        }


def _build_status_banner_style(status: Any) -> tuple[str, str]:
    value = str(status or "").strip().upper()
    if value == "CURRENT":
        return ("#15361c", "#c8ffd4")
    if value == "STALE":
        return ("#4a2600", "#ffd7b0")
    if value == "PORTABLE":
        return ("#20374c", "#d2ebff")
    return ("#4a1111", "#ffd3d3")


def _format_build_identity_line(identity: Dict[str, Any]) -> str:
    label = str(identity.get("bundle_label") or "unlabeled")
    built_at = str(identity.get("built_at") or "").strip()
    if built_at:
        built_at = built_at.replace("T", " ").replace("+00:00", "Z")
    commit = str(identity.get("git_commit") or "").strip()
    parts = [label]
    if built_at:
        parts.append(built_at)
    if commit:
        parts.append(commit)
    return "Build: " + " | ".join(parts)


