def _script_runner_command(script: Path) -> list[str]:
    script = Path(script).resolve()
    try:
        if _is_frozen_runtime():
            runner = _app_base_dir() / "MOLE_ScriptRunner.exe"
            if runner.exists():
                return [str(runner), str(script)]
    except Exception:
        pass
    return [sys.executable, str(script)]


def _resolve_app_relative_path(path_value: Any, *, base_dir: Optional[Path] = None) -> Path:
    p = Path(str(path_value or "")).expanduser()
    if p.is_absolute():
        return p
    base = Path(base_dir or _app_base_dir())
    app_root = base.parent
    cand = (app_root / p).resolve()
    if cand.exists():
        return cand
    return cand


