def mole_cfg_path(base_dir: Path) -> Path:
    env = _mole_env_mode()
    name = "mole_config_training.json" if env == "TRAINING" else "mole_config.json"
    return (base_dir.parent / "config" / name).resolve()

def mole_cfg_mirror_paths(base_dir: Path) -> List[Path]:
    """Return non-authoritative runtime mirrors that should track the active config."""
    env = _mole_env_mode()
    name = "mole_config_training.json" if env == "TRAINING" else "mole_config.json"
    targets: List[Path] = [
        (base_dir.parent / name).resolve(),
    ]
    if name == "mole_config.json":
        targets.append((base_dir.parent / "mole_das_data" / "configs" / name).resolve())

    primary = mole_cfg_path(base_dir)
    deduped: List[Path] = []
    seen = {str(primary).lower()}
    for p in targets:
        key = str(p).lower()
        if key in seen:
            continue
        seen.add(key)
        deduped.append(p)
    return deduped

def mole_cfg_write_through(base_dir: Path, cfg: Dict[str, Any]) -> Path:
    """Write the authoritative config and keep runtime mirror copies synchronized."""
    primary = mole_cfg_path(base_dir)
    for p in [primary] + mole_cfg_mirror_paths(base_dir):
        safe_mkdir(p.parent)
        write_json(p, cfg)
    return primary

def mole_cfg_load_or_create(base_dir: Path) -> Dict[str, Any]:
    cfg_p = mole_cfg_path(base_dir)
    safe_mkdir(cfg_p.parent)
    if cfg_p.exists():
        try:
            cfg = read_json(cfg_p)
        except Exception:
            cfg = mole_cfg_default(base_dir)
    else:
        cfg = mole_cfg_default(base_dir)
        try:
            write_json(cfg_p, cfg)
        except Exception:
            pass

    # Ensure required keys exist (non-destructive)
    dflt = mole_cfg_default(base_dir)
    cfg.setdefault("paths", {})
    for k, v in dflt["paths"].items():
        cfg["paths"].setdefault(k, v)
    cfg.setdefault("sqlite", {})
    for k, v in dflt["sqlite"].items():
        cfg["sqlite"].setdefault(k, v)

    cfg.setdefault("ui", {})
    for k, v in (dflt.get("ui") or {}).items():
        cfg["ui"].setdefault(k, v)

    # Optional UI preferences
    cfg.setdefault("ui", {})
    d_ui = dflt.get("ui") or {}
    for k, v in d_ui.items():
        cfg["ui"].setdefault(k, v)
    # Ensure nested keys
    try:
        cfg["ui"].setdefault("date_picker", {})
        for k, v in (d_ui.get("date_picker") or {}).items():
            cfg["ui"]["date_picker"].setdefault(k, v)
        cfg["ui"].setdefault("maps", {})
        for k, v in (d_ui.get("maps") or {}).items():
            cfg["ui"]["maps"].setdefault(k, v)
        cfg["ui"].setdefault("qaqc", {})
        for k, v in (d_ui.get("qaqc") or {}).items():
            cfg["ui"]["qaqc"].setdefault(k, v)
    except Exception:
        pass

    try:
        mole_cfg_write_through(base_dir, cfg)
    except Exception:
        pass

    return cfg

def _find_optional_tool(base_dir: Path, *names: str) -> Optional[Path]:
    for name in names:
        p = (base_dir / name).resolve()
        if p.exists():
            return p
    return None

