def mole_cfg_resolve_paths(cfg: Dict[str, Any], base_dir: Path) -> Dict[str, Path]:
    paths = {}
    p = cfg.get("paths") or {}
    for k, v in p.items():
        try:
            if v is None:
                continue
            sv = str(v).strip()
            if not sv:
                continue
            pv = Path(sv)
            if not pv.is_absolute():
                pv = (base_dir / pv).resolve()
            paths[k] = pv
        except Exception:
            continue
    return paths

def mole_cfg_init_master_db(db_path: Path, base_dir: Path) -> None:
    """Ensure master equipment catalog DB exists and has schema applied."""
    try:
        safe_mkdir(db_path.parent)
        con = sqlite3.connect(str(db_path))
        try:
            con.execute("PRAGMA foreign_keys=ON;")
            # WAL is best for a UI + runner handshake (single writer, many readers)
            try:
                con.execute("PRAGMA journal_mode=WAL;")
                con.execute("PRAGMA synchronous=NORMAL;")
            except Exception:
                pass

            schema_file = base_dir / "mole_db_schema_v1.sql"
            if schema_file.exists():
                con.executescript(schema_file.read_text(encoding="utf-8"))
            else:
                # Minimal fallback schema (keeps app alive even if schema file is missing)
                con.executescript("""
                CREATE TABLE IF NOT EXISTS meta_schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
                CREATE TABLE IF NOT EXISTS catalog_manufacturer(
                  manufacturer_id INTEGER PRIMARY KEY AUTOINCREMENT,
                  name TEXT NOT NULL,
                  name_norm TEXT NOT NULL UNIQUE,
                  created_at TEXT NOT NULL,
                  updated_at TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS catalog_model(
                  model_id INTEGER PRIMARY KEY AUTOINCREMENT,
                  manufacturer_id INTEGER NOT NULL,
                  source_category TEXT NOT NULL,
                  model_number TEXT NOT NULL,
                  model_norm TEXT NOT NULL,
                  usage_count INTEGER NOT NULL DEFAULT 0,
                  created_at TEXT NOT NULL,
                  updated_at TEXT NOT NULL,
                  UNIQUE(manufacturer_id, source_category, model_norm)
                );
                """)
            try:
                con.execute("INSERT OR IGNORE INTO meta_schema_migrations(version, applied_at) VALUES (alpha,alpha)",
                            (3, now_iso()))
            except Exception:
                pass
            con.commit()
        finally:
            con.close()
    except Exception:
        # DB init must never prevent the UI from launching.
        pass

def float_or_none(x: Any) -> Optional[float]:
    """Parse a float from a value; return None if blank/None/invalid.

    Accepts numbers directly to avoid breaking when session defaults store numeric types.
    """
    try:
        if x is None:
            return None
        if isinstance(x, (int, float)):
            return float(x)
        s = str(x).strip()
        if not s:
            return None
        s = s.replace(",", "")
        return float(s)
    except Exception:
        return None


def calibration_target_or_none(x: Any) -> Optional[float]:
    """Extract the first numeric concentration token from a wizard target field."""
    try:
        if x is None:
            return None
        if isinstance(x, (int, float)):
            return float(x)
        s = str(x).strip()
        if not s:
            return None
        m = re.search(r"[-+]alpha\d*\.alpha\d+(alpha:[eE][-+]alpha\d+)alpha", s.replace(",", ""))
        if not m:
            return None
        return float(m.group(0))
    except Exception:
        return None


def normalize_prescription_cal_targets(p: Dict[str, Any]) -> None:
    """Persist authoritative calibration targets from wizard-entered project inputs."""
    if not isinstance(p, dict):
        return

    # In this architecture, zero air is 100% N2, so ZERO is always 0 for all channels.
    p["zero_target"] = 0.0

    span_target = calibration_target_or_none(p.get("span_target"))
    if span_target is None:
        span_target = calibration_target_or_none(p.get("span_cylinder_id"))
    p["span_target"] = float(span_target) if span_target is not None else None

    mid_target = calibration_target_or_none(p.get("mid_target"))
    if mid_target is None:
        mid_target = calibration_target_or_none(p.get("mid_cylinder_id"))
    p["mid_target"] = float(mid_target) if mid_target is not None else None


