def normalize_spike_recovery_cfg(cfg: Any, reference_cfg: Any = None) -> Dict[str, Any]:
    ref_cfg = normalize_reference_audit_cfg(reference_cfg if isinstance(reference_cfg, dict) else {})
    if mole_spike_recovery is not None:
        try:
            return dict(
                mole_spike_recovery.normalize_config(
                    cfg if isinstance(cfg, dict) else {},
                    ftir_enabled=bool(ref_cfg.get("enabled")),
                    ftir_role=str(ref_cfg.get("role") or "AUDIT"),
                    ftir_method=ref_cfg.get("method_standard"),
                )
            )
        except Exception:
            pass
    out = dict(spike_recovery_defaults())
    if isinstance(cfg, dict):
        out.update(cfg)
    if bool(ref_cfg.get("enabled")) and str(ref_cfg.get("role") or "AUDIT").strip().upper() == "AUDIT":
        out["enabled"] = True
        out["mandatory"] = True
        out["applies_to_ftir"] = True
        out["source"] = "FTIR_METHOD"
        out["method_standard"] = str(ref_cfg.get("method_standard") or "")
    return out


def reference_mapping_text_to_dict(text: str) -> Dict[str, str]:
    if mole_ftir_reference is not None:
        try:
            return dict(mole_ftir_reference.parse_overrides_text(text or ""))
        except Exception:
            pass
    out: Dict[str, str] = {}
    for part in re.split(r"[;\n]+", str(text or "").strip()):
        if "=" not in part:
            continue
        left, right = part.split("=", 1)
        left = str(left or "").strip().upper()
        right = str(right or "").strip()
        if left and right:
            out[left] = right
    return out


def reference_mapping_dict_to_text(mapping: Dict[str, Any]) -> str:
    if mole_ftir_reference is not None:
        try:
            return str(mole_ftir_reference.format_overrides_text(mapping or {}))
        except Exception:
            pass
    if not isinstance(mapping, dict):
        return ""
    parts: List[str] = []
    for key in sorted(mapping.keys()):
        val = str(mapping.get(key) or "").strip()
        if key and val:
            parts.append(f"{str(key).strip().upper()}={val}")
    return "; ".join(parts)


def normalize_reference_audit_cfg(cfg: Any) -> Dict[str, Any]:
    out = None
    if mole_ftir_reference is not None:
        try:
            out = dict(mole_ftir_reference.normalize_config(cfg if isinstance(cfg, dict) else {}))
        except Exception:
            out = None
    if not isinstance(out, dict):
        out = dict(reference_audit_defaults())
        if isinstance(cfg, dict):
            out.update(cfg)
    out["enabled"] = bool(out.get("enabled"))
    out["provider"] = str(out.get("provider") or "MG2000_FTIR_PRN").strip() or "MG2000_FTIR_PRN"
    role = str(out.get("role") or "AUDIT").strip().upper()
    out["role"] = role if role in ("AUDIT", "REFERENCE") else "AUDIT"
    out["prn_path"] = str(out.get("prn_path") or "").strip()
    out["file_pattern"] = str(out.get("file_pattern") or "*.prn").strip() or "*.prn"
    out["recursive"] = bool(out.get("recursive"))
    try:
        out["freshness_s"] = max(0.0, float(out.get("freshness_s") or 0.0))
    except Exception:
        out["freshness_s"] = 120.0
    out["column_overrides"] = dict(out.get("column_overrides") or {})
    out["units_overrides"] = dict(out.get("units_overrides") or {})
    if mole_ftir_methods is not None:
        try:
            out["method_standard"] = mole_ftir_methods.normalize_method(out.get("method_standard"))
        except Exception:
            out["method_standard"] = "ASTM_D6348_12"
    else:
        out["method_standard"] = str(out.get("method_standard") or "ASTM_D6348_12").strip() or "ASTM_D6348_12"
    if mole_ftir_offset_recommendations is not None:
        try:
            store = mole_ftir_offset_recommendations.load_store()
            default_use = bool(store.get("auto_apply_future_projects"))
            out["offset_recommendations"] = mole_ftir_offset_recommendations.normalize_project_policy(
                out.get("offset_recommendations"),
                default_use_global=default_use,
            )
        except Exception:
            out["offset_recommendations"] = dict(mole_ftir_offset_recommendations.DEFAULT_PROJECT_POLICY)
    else:
        off = out.get("offset_recommendations") if isinstance(out.get("offset_recommendations"), dict) else {}
        out["offset_recommendations"] = {
            "use_global": bool(off.get("use_global")),
            "promote_latest_for_future_projects": bool(off.get("promote_latest_for_future_projects")),
        }
    return out




# ------------------------- unit normalization -------------------------
# UI uses human-friendly display strings (e.g., 'lb/hr', 'gal/hr', 'MMBtu/hr').
# Session JSON stores canonical tokens for stability ('lb_hr', 'gal_hr', 'mmbtu_hr').
# These helpers keep Save/Load backward-compatible.

_UNIT_DISPLAY_TO_TOKEN = {
    # Mass flow
    'lb/hr': 'lb_hr',
    'lb_hr': 'lb_hr',
    'kg/hr': 'kg_hr',
    'kg_hr': 'kg_hr',
    # Liquid volume
    'gal/hr': 'gal_hr',
    'gal_hr': 'gal_hr',
    'gph': 'gal_hr',
    'bbl/day': 'bbl_day',
    'bbl_day': 'bbl_day',
    'l/hr': 'l_hr',
    'l_hr': 'l_hr',
    # Gas volume
    'scfh': 'scfh',
    'scfm': 'scfm',
    'dscfh': 'dscfh',
    'dscfm': 'dscfm',
    # Energy flow
    'mmbtu/hr': 'mmbtu_hr',
    'mmbtu_hr': 'mmbtu_hr',
}

_UNIT_TOKEN_TO_DISPLAY = {v: k for k, v in _UNIT_DISPLAY_TO_TOKEN.items() if '/' in k or k in ('scfh','scfm','dscfh','dscfm')}


# ------------------------- small parsing helpers -------------------------
def int_or_none(x, default=None):
    """Best-effort parse to int; returns default on failure/blank."""
    try:
        if x is None:
            return default
        if isinstance(x, bool):
            return default
        if isinstance(x, int):
            return int(x)
        s = str(x).strip()
        if s == "":
            return default
        return int(float(s))
    except Exception:
        return default


def _stack_port_angles_from_vars(port_count_s, angle1_s, angle2_s):
    """Return a list of port angles (deg) based on UI vars; defaults to [0, 90]."""
    n = int_or_none(port_count_s, default=2)
    if n is None or n <= 0:
        n = 2
    a1 = float_or_none(angle1_s)
    a2 = float_or_none(angle2_s)
    if a1 is None:
        a1 = 0.0
    if a2 is None:
        a2 = 90.0
    angles = [float(a1)]
    if n >= 2:
        angles.append(float(a2))
    # if n>2, we just repeat in 90-deg increments (operator can document separately)
    while len(angles) < n:
        angles.append((angles[-1] + 90.0) % 360.0)
    return angles[:n]


def unit_display_to_token(u: str) -> str:
    u = (u or '').strip()
    if not u:
        return ''
    key = u.lower().replace(' ', '')
    return _UNIT_DISPLAY_TO_TOKEN.get(key, key)


def unit_token_to_display(u: str) -> str:
    u = (u or '').strip()
    if not u:
        return ''
    key = u.lower().replace(' ', '')
    # already displayalpha
    if key in _UNIT_DISPLAY_TO_TOKEN:
        return key
    return _UNIT_TOKEN_TO_DISPLAY.get(key, u)

def resolve_db_path(base_dir: Path, config_dir: Path, filename: str) -> Path:
    """Resolve DB file location.

    Lookup order:
      1) alongside the .py (base_dir)
      2) mole_das_configs/ (config_dir)
      3) default-create alongside the .py
    """
    p1 = base_dir / filename
    if p1.exists():
        return p1
    p2 = config_dir / filename
    if p2.exists():
        return p2
    return p1



