SUPPORTED_Z_MODELS = ("IDEAL", "FIXED_Z")


def _normalize_z_model(value: Any) -> str:
    """Return a supported site-condition compressibility mode."""
    z_model = str(value or "IDEAL").strip().upper() or "IDEAL"
    return z_model if z_model in SUPPORTED_Z_MODELS else "IDEAL"


def load_or_init_json(path: Path, default_data: Dict[str, Any]) -> Dict[str, Any]:
    """
    Load JSON from path. If missing, create with default_data.
    If corrupted, back it up and recreate.
    """
    try:
        if not path.exists():
            write_json(path, default_data)
            return default_data
        return read_json(path)
    except Exception:
        try:
            backup = path.with_suffix(path.suffix + ".corrupt")
            if path.exists():
                path.replace(backup)
        except Exception:
            pass
        write_json(path, default_data)
        return default_data


def _starter_method_qaqc_criteria(method_id: str) -> Dict[str, Any]:
    """Return starter QA/QC criteria for shipped methods."""
    mid = str(method_id or "").strip().upper()
    if not mid:
        return {}

    drift = 3.0
    if mid in ("EPA_3A_O2", "EPA_7E_NOX"):
        drift = 2.0

    def _track_block() -> Dict[str, Any]:
        return {
            "zero": {"type": "%SPAN", "value": 2.0},
            "span": {"type": "%SPAN", "value": 2.0},
            "cal_error": {"type": "%SPAN", "value": 2.0},
            "drift": {"type": "%SPAN", "value": drift},
        }

    tracks: Dict[str, Any] = {}
    for track_name in ("DEFAULT", "DIAG", "PROJECT", "COMPLIANCE", "PERM"):
        tracks[track_name] = _track_block()

    return {
        "source": "MOLE starter QA/QC criteria catalog",
        "tracks": tracks,
    }


def _backfill_methods_db_defaults(db: Dict[str, Any]) -> Dict[str, Any]:
    """Backfill starter-method defaults into loaded Methods DB data."""
    try:
        for m in db.get("methods", []) or []:
            if not isinstance(m, dict):
                continue
            cg = m.setdefault("calibration_guidance", {})
            tp = cg.setdefault("three_point", {})
            tp.setdefault("mid_fraction_of_span", 0.5)
            tp.setdefault("label", "Midpoint (default 50% of span)")
            if not isinstance(m.get("qaqc_criteria"), dict):
                starter = _starter_method_qaqc_criteria(m.get("method_id"))
                if starter:
                    m["qaqc_criteria"] = starter
    except Exception:
        pass
    return db


