def _index_by_id(records: List[Dict[str, Any]], id_key: str = "id") -> Dict[str, Dict[str, Any]]:
    out: Dict[str, Dict[str, Any]] = {}
    for r in records:
        rid = str(r.get(id_key, "")).strip()
        if rid:
            out[rid] = r
    return out

class MoleDASWizard(tk.Tk):
    BG = "#0b1118"
    FG = "#c7d0d9"
    ACCENT = "#ff9f1a"
    ARCADE_YELLOW = "#ffcc33"  # arcade yellow (high-contrast labels)
    BTN_BG = "#1b2734"
    BTN_BG2 = "#121a24"
    PANEL = "#0e1724"
    BTN_FG = "#e6edf3"
    MUTED = "#9fb0c0"
    FG_DIM = "#9fb0c0"  # alias for muted label text

    # Fonts (kept as class attributes so Tkinter's __getattr__ proxy never misroutes missing
    # attributes to the underlying tkapp object).
    FONT = ("Consolas", 10)
    FONT_MONO = ("Consolas", 10)
    FONT_SMALL = ("Consolas", 9)
    FONT_TINY = ("Consolas", 8)
    FONT_HDR = ("Consolas", 12, "bold")


    # ------------------------- arcade logo -------------------------

    def _build_logo_arcade(self, parent: tk.Widget) -> None:
        """Upper-left pulsing MOLE logo (80's arcade CRT vibe).

       - If Pillow (PIL) is available: renders the animated / CRT-style logo.
       - If Pillow is missing: falls back to Tkinter PhotoImage (static logo)
          so the UI still shows branding without any extra deps.
        """

        base_dir = getattr(self, "base_dir", None) or _app_base_dir()
        base_dir = Path(base_dir).resolve()
        candidates = [
            # Preferred: pre-sized icon (no resize dependency)
            base_dir / "mole_logo_130.png",
            # Fallbacks
            base_dir / "mole_logo.png",
            base_dir / "mole_assets" / "branding" / "mole_logo.png",
            base_dir.parent / "mole_assets" / "branding" / "mole_logo.png",
        ]
        logo_path = next((p for p in candidates if p.exists()), None)

        if not logo_path:
            tk.Label(
                parent,
                text="[MOLE logo missing]",
                bg=self.BG,
                fg="#ff5555",
                font=("Consolas", 9, "bold"),
            ).pack(pady=(10, 4), padx=12, anchor="w")
            return

        # Pillow is optional: use it if present, otherwise fall back.
        try:
            from PIL import Image, ImageTk, ImageEnhance, ImageOps  # type: ignore
        except Exception:
            # Tk 8.6+ supports PNG via PhotoImage on Windows.
            try:
                self._logo_photo = tk.PhotoImage(file=str(logo_path))
                tk.Label(parent, image=self._logo_photo, bg=self.BG).pack(
                    pady=(10, 4), padx=12, anchor="w"
                )
            except Exception:
                tk.Label(
                    parent,
                    text="[Logo load failed]",
                    bg=self.BG,
                    fg="#ff5555",
                    font=("Consolas", 9, "bold"),
                ).pack(pady=(10, 4), padx=12, anchor="w")
            return

        self._logo_base = Image.open(logo_path).convert("RGBA")
        target_h = 130
        if self._logo_base.height != target_h:
            w_px = int(self._logo_base.width * (target_h / self._logo_base.height))
            self._logo_base = self._logo_base.resize((w_px, target_h), Image.LANCZOS)

        self._logo_phase = 0.0
        self._logo_flicker_hold = 0
        self._logo_scan_phase = 0
        self._logo_imgtk = None
        self._logo_canvas_img_id = None

        self._logo_canvas = tk.Canvas(parent, width=self._logo_base.width, height=self._logo_base.height,
                                      highlightthickness=0, bd=0, bg=self.BG)
        self._logo_canvas.pack(pady=(10, 4), padx=12, anchor="w")

        # Command-prompt blink frame (border + cursor block)
        self._logo_border_pad = 7
        self._logo_border_thickness = 3
        self._logo_border_phase = 0
        self._logo_border_on = True
        self._logo_border_rect_id = None

        # Expand canvas so we can draw a border around the image area.
        try:
            self._logo_canvas.configure(
                width=self._logo_base.width + 2 * (self._logo_border_pad + self._logo_border_thickness),
                height=self._logo_base.height + 2 * (self._logo_border_pad + self._logo_border_thickness),
            )
        except Exception:
            pass

        self._render_logo_arcade(first=True)
        self.after(70, self._pulse_logo_arcade)

    def _render_logo_arcade(self, first: bool = False) -> None:
        """Render single frame: green phosphor + breathe + flicker + scanlines."""
        from PIL import Image, ImageTk, ImageEnhance, ImageOps  # type: ignore
        import math, random

        img = self._logo_base
        r, g, b, a = img.split()
        lum = ImageOps.grayscale(Image.merge("RGB", (r, g, b)))

        greenized = ImageOps.colorize(lum, black="#001400", white="#66ff66").convert("RGBA")
        gr, gg, gb, _ = greenized.split()
        greenized = Image.merge("RGBA", (gr, gg, gb, a))

        breath = 1.02 + 0.22 * math.sin(self._logo_phase)
        greenized = ImageEnhance.Brightness(greenized).enhance(max(0.6, breath))

        if getattr(self, "_logo_flicker_hold", 0) > 0:
            jitter = random.uniform(0.82, 1.18)
            greenized = ImageEnhance.Brightness(greenized).enhance(jitter)
            self._logo_flicker_hold -= 1
        else:
            if random.random() < 0.06:
                self._logo_flicker_hold = random.randint(2, 6)

        w_px, h_px = greenized.size
        overlay = Image.new("RGBA", (w_px, h_px), (0, 0, 0, 0))
        pitch = 4
        alpha_base = 38
        offset = int(getattr(self, "_logo_scan_phase", 0)) % pitch

        for y in range(offset, h_px, pitch):
            band_alpha = alpha_base + (5 if (y // pitch) % 2 == 0 else 0)
            row = [(0, 0, 0, band_alpha)] * w_px
            overlay.putdata(row, offset=y * w_px)

        composed = Image.alpha_composite(greenized, overlay)
        composed = ImageEnhance.Contrast(composed).enhance(1.05)

        self._logo_imgtk = ImageTk.PhotoImage(composed)
        if first or self._logo_canvas_img_id is None:
            self._logo_canvas_img_id = self._logo_canvas.create_image(self._logo_border_pad + self._logo_border_thickness, self._logo_border_pad + self._logo_border_thickness, anchor="nw", image=self._logo_imgtk)
        else:
            self._logo_canvas.itemconfigure(self._logo_canvas_img_id, image=self._logo_imgtk)

        # Command-prompt style border blink + cursor block
        try:
            w = int(self._logo_canvas.cget("width"))
            h = int(self._logo_canvas.cget("height"))
            th = int(getattr(self, "_logo_border_thickness", 2))
            pad = int(getattr(self, "_logo_border_pad", 4))

            self._logo_border_phase = int(getattr(self, "_logo_border_phase", 0)) + 1
            if self._logo_border_phase % 6 == 0:
                self._logo_border_on = not bool(getattr(self, "_logo_border_on", True))

            border_color = "#66ff66" if self._logo_border_on else "#123318"

            x0, y0 = th / 2, th / 2
            x1, y1 = w - th / 2, h - th / 2
            if getattr(self, "_logo_border_rect_id", None) is None:
                self._logo_border_rect_id = self._logo_canvas.create_rectangle(
                    x0, y0, x1, y1, outline=border_color, width=th
                )
            else:
                self._logo_canvas.itemconfigure(self._logo_border_rect_id, outline=border_color, width=th)

        except Exception:
            pass


    def _pulse_logo_arcade(self) -> None:
        """Animation tick."""
        if not hasattr(self, "_logo_base"):
            return
        self._logo_phase += 0.14
        self._logo_scan_phase = int(getattr(self, "_logo_scan_phase", 0)) + 1
        self._render_logo_arcade(first=False)
        self.after(70, self._pulse_logo_arcade)

    def __init__(self) -> None:
        super().__init__()
        self.base_dir = _app_base_dir()
        self.build_identity = _load_build_identity(self.base_dir)
        self.title(_format_window_title(APP_TITLE, self.build_identity, training=(_mole_env_mode() == "TRAINING")))
        self.geometry("1360x760")
        self.minsize(1060, 640)
        self.configure(bg=self.BG)

        # TTK arcade styling (ensure ttk.Label text is visible on dark background)
        try:
            _s = ttk.Style(self)
            _s.configure("TLabel", background=self.BG, foreground=self.ARCADE_YELLOW)
            _s.configure("TLabelframe.Label", background=self.BG, foreground=self.ARCADE_YELLOW)
        except Exception:
            pass

        self._init_stable_paths_and_config()


        self._init_option_lists()
        self._load_asset_databases()
        self._init_session_state()
        try:
            self._write_startup_diagnostic()
        except Exception:
            pass
        self._init_source_catalog_db()
        self._build_shell()
        self.bind_all("<MouseWheel>", self._on_global_mousewheel, add="+")
        self.bind_all("<Button-4>", self._on_global_mousewheel, add="+")
        self.bind_all("<Button-5>", self._on_global_mousewheel, add="+")
        self.goto("WELCOME")
        try:
            self._offer_startup_recovery()
        except Exception:
            pass

    # ------------------------- init -------------------------

    def _init_stable_paths_and_config(self) -> None:
        """Initialize shared config + stable folders (DB, sessions, runs, logs, assets)."""
        # Shared config (stored at ../config/mole_config.json relative to MOLE_code)
        self.mole_cfg = mole_cfg_load_or_create(self.base_dir)
        resolved = mole_cfg_resolve_paths(self.mole_cfg, self.base_dir)

        # Canonical roots
        self.mole_home = self.base_dir.parent
        self.data_root = resolved.get("data_root", (self.mole_home / "mole_das_data").resolve())
        self.assets_dir = resolved.get("assets_dir", (self.mole_home / "mole_assets").resolve())
        self.logs_dir = resolved.get("logs_dir", (self.data_root / "logs").resolve())
        self.backups_dir = resolved.get("backups_dir", (self.data_root / "backups").resolve())
        self.sessions_root = resolved.get("sessions_dir", (self.data_root / "sessions").resolve())
        self.daq_runs_root = resolved.get("daq_runs_dir", (self.data_root / "daq_runs").resolve())
        self.rule_packs_dir = resolved.get("rule_packs_dir", (self.data_root / "rule_packs").resolve())
        self.master_db_path = resolved.get("db_path", (self.data_root / "db" / "mole_master.sqlite").resolve())

        # Packages inbox (v10.0.11)
        self.packages_inbox_dir = resolved.get("packages_inbox_dir", (self.data_root / "inbox_packages").resolve())
        self.packages_archive_dir = resolved.get("packages_archive_dir", (self.data_root / "inbox_archive").resolve())
        self.package_index_db_path = resolved.get("package_index_db_path", (self.data_root / "db" / "mole_packages_inbox.sqlite").resolve())

        # Ensure folders exist
        for p in [self.data_root, self.assets_dir, self.logs_dir, self.backups_dir, self.sessions_root, self.daq_runs_root, self.rule_packs_dir, self.packages_inbox_dir, self.packages_archive_dir, self.package_index_db_path.parent, self.master_db_path.parent]:
            try:
                safe_mkdir(Path(p))
            except Exception:
                pass

        # Session config staging (legacy location) moved into data_root for stability
        self.config_dir = self.data_root / "configs"
        safe_mkdir(self.config_dir)

        # UI crash log
        self.ui_log_path = self.logs_dir / "mole_ui_error.log"

        # Ensure master DB exists (schema applied if mole_db_schema_v1.sql is present)
        mole_cfg_init_master_db(self.master_db_path, base_dir=self.base_dir)

        # Stamp into session defaults early (after _init_session_state this will be reinforced)
        try:
            self.session.setdefault("paths", {})
            self.session["paths"].update({
                "data_root": str(self.data_root),
                "assets_dir": str(self.assets_dir),
                "logs_dir": str(self.logs_dir),
                "backups_dir": str(self.backups_dir),
                "sessions_dir": str(self.sessions_root),
                "daq_runs_dir": str(self.daq_runs_root),
                "rule_packs_dir": str(self.rule_packs_dir),
                "db_path": str(self.master_db_path),
                "config_dir": str(self.config_dir),
            })
        except Exception:
            pass

