    def _load_asset_databases(self) -> None:
        """
        Load (or initialize) the lightweight JSON "asset DBs" that drive deterministic
        Pollutants resolution and optional instrument/cylinder selection.
        """
        # Optional config overrides (DB Paths tab). If unset, fall back to default lookup order.
        _resolved = mole_cfg_resolve_paths(getattr(self, "mole_cfg", {}), self.base_dir)

        self.db_methods_path = _resolved.get("methods_db_path") or resolve_db_path(self.base_dir, self.config_dir, METHODS_DB_FILENAME)
        self.db_cylinders_path = _resolved.get("cylinders_db_path") or resolve_db_path(self.base_dir, self.config_dir, CYLINDERS_DB_FILENAME)
        self.db_instruments_path = _resolved.get("instruments_db_path") or resolve_db_path(self.base_dir, self.config_dir, INSTRUMENTS_DB_FILENAME)

        self.methods_db = _backfill_methods_db_defaults(load_or_init_json(self.db_methods_path, _default_methods_db()))
        self.cylinders_db = load_or_init_json(self.db_cylinders_path, _default_cylinders_db())
        self.instruments_db = load_or_init_json(self.db_instruments_path, _default_instruments_db())

        # Indexes for fast lookup
        self._method_by_id = _index_by_id(self.methods_db.get("methods", []), id_key="method_id")
        self._cyl_by_id = _index_by_id(self.cylinders_db.get("cylinders", []), id_key="id")
        self._inst_by_id = _index_by_id(self.instruments_db.get("instruments", []), id_key="id")

        # Canonical analyte list
        self._pollutant_codes = list(self.methods_db.get("catalog", {}).get("analytes", [])) or list(getattr(self, "_pollutant_codes", []))
        if not self._pollutant_codes:
            self._pollutant_codes = ["O2", "CO2", "CO", "NO", "NO2", "NOX", "VOC", "CH4"]

        self._units_by_analyte = dict(self.methods_db.get("catalog", {}).get("units_by_analyte", {}))
        self._span_offerings_by_analyte = dict(self.methods_db.get("catalog", {}).get("span_offerings_by_analyte", {}))

        # Deterministic "track" used by the resolver
        self._track_names = ["DIAG", "PROJECT", "COMPLIANCE", "PERM"]

    def _reload_asset_databases(self) -> None:
        """Reload DB JSON files from disk (useful after external edits)."""
        self.methods_db = _backfill_methods_db_defaults(load_or_init_json(self.db_methods_path, _default_methods_db()))
        self.cylinders_db = load_or_init_json(self.db_cylinders_path, _default_cylinders_db())
        self.instruments_db = load_or_init_json(self.db_instruments_path, _default_instruments_db())

        self._method_by_id = _index_by_id(self.methods_db.get("methods", []), id_key="method_id")
        self._cyl_by_id = _index_by_id(self.cylinders_db.get("cylinders", []), id_key="id")
        self._inst_by_id = _index_by_id(self.instruments_db.get("instruments", []), id_key="id")

        self._pollutant_codes = list(self.methods_db.get("catalog", {}).get("analytes", [])) or self._pollutant_codes
        self._units_by_analyte = dict(self.methods_db.get("catalog", {}).get("units_by_analyte", {}))
        self._span_offerings_by_analyte = dict(self.methods_db.get("catalog", {}).get("span_offerings_by_analyte", {}))

