    def _resolve_form_grid_contract(
        self,
        minspec: Optional[Union[Dict[int, int], str]] = None,
        weighted_cols: Optional[Tuple[int, ...]] = None,
    ) -> Tuple[Dict[int, int], Tuple[int, ...]]:
        contracts = self._form_grid_contracts()
        if isinstance(minspec, str):
            base = contracts.get(minspec) or contracts["wizard_default"]
            spec = dict(base.get("spec") or {})
            weights = tuple(weighted_cols if weighted_cols is not None else tuple(base.get("weighted") or ()))
            return spec, weights
        spec = dict(minspec or contracts["wizard_default"]["spec"])
        weights = tuple(weighted_cols or ())
        return spec, weights

    def _configure_form_grid(
        self,
        frame: tk.Widget,
        minspec: Optional[Union[Dict[int, int], str]] = None,
        weighted_cols: Optional[Tuple[int, ...]] = None,
    ) -> None:
        """Apply persistent column stops to form-heavy sections.

        Primary fields align to shared vertical geometry.
        Long notes/explanatory content may span independently.
        `minspec` may be a named Wizard contract or an explicit column map.
        """
        spec, weights = self._resolve_form_grid_contract(minspec=minspec, weighted_cols=weighted_cols)
        try:
            contract_name = str(minspec) if isinstance(minspec, str) else "EXPLICIT"
            setattr(frame, "_mole_form_grid_contract", contract_name)
            setattr(frame, "_mole_form_grid_spec", dict(spec))
            setattr(frame, "_mole_form_grid_weighted", tuple(weights))
        except Exception:
            pass
        for col, minsize in spec.items():
            try:
                frame.grid_columnconfigure(col, minsize=int(minsize), weight=(1 if col in weights else 0))
            except Exception:
                pass

    def _mark_form_grid_exempt(self, frame: tk.Widget, reason: str) -> None:
        """Mark an intentionally custom grid so the layout audit skips it."""
        try:
            setattr(frame, "_mole_form_grid_exempt", True)
            setattr(
                frame,
                "_mole_form_grid_exempt_reason",
                str(reason or "Intentional custom layout.").strip() or "Intentional custom layout.",
            )
        except Exception:
            pass

    def _alignment_widget_label(self, widget: tk.Widget) -> str:
        try:
            txt = str(widget.cget("text") or "").strip()
        except Exception:
            txt = ""
        cls = str(widget.winfo_class() or widget.__class__.__name__)
        if txt:
            return f"{cls}: {txt}"
        try:
            name = str(widget.winfo_name() or "").strip()
        except Exception:
            name = ""
        return f"{cls}: {name}" if name else cls

    def _alignment_frame_metrics(self, frame: tk.Widget) -> Dict[str, Any]:
        children = []
        try:
            children = [c for c in frame.winfo_children() if str(c.winfo_manager() or "") == "grid"]
        except Exception:
            children = []
        cols: set[int] = set()
        label_count = 0
        input_count = 0
        input_classes = {"Entry", "TEntry", "Combobox", "TCombobox", "Checkbutton", "TCheckbutton", "Radiobutton", "TRadiobutton", "Spinbox"}
        label_classes = {"Label", "TLabel", "Checkbutton", "TCheckbutton", "Radiobutton", "TRadiobutton"}
        for child in children:
            try:
                info = child.grid_info() or {}
                col = int(info.get("column", 0))
                cols.add(col)
            except Exception:
                pass
            try:
                cls = str(child.winfo_class() or "")
            except Exception:
                cls = ""
            if cls in label_classes:
                label_count += 1
            if cls in input_classes:
                input_count += 1
        return {
            "children": children,
            "child_count": len(children),
            "columns": sorted(cols),
            "column_count": len(cols),
            "label_count": label_count,
            "input_count": input_count,
        }

    def _alignment_is_contract_candidate(self, frame: tk.Widget) -> bool:
        metrics = self._alignment_frame_metrics(frame)
        return bool(
            metrics["child_count"] >= 4
            and 2 <= metrics["column_count"] <= 6
            and metrics["label_count"] >= 1
            and metrics["input_count"] >= 1
        )

    def _collect_alignment_audit_findings(self, root: tk.Widget, state: str) -> Dict[str, Any]:
        findings: List[Dict[str, Any]] = []
        contracts: List[Dict[str, Any]] = []
        exemptions: List[Dict[str, Any]] = []
        visited: set[str] = set()

        def _walk(widget: tk.Widget) -> None:
            try:
                wid = str(widget)
            except Exception:
                wid = repr(widget)
            if wid in visited:
                return
            visited.add(wid)

            is_frame = isinstance(widget, (tk.Frame, tk.LabelFrame, ttk.Frame, ttk.LabelFrame))
            if not is_frame:
                for child in list(getattr(widget, "winfo_children", lambda: [])()):
                    _walk(child)
                return

            try:
                if bool(getattr(widget, "_mole_form_grid_exempt", False)):
                    metrics = self._alignment_frame_metrics(widget)
                    exemptions.append(
                        {
                            "state": state,
                            "widget": self._alignment_widget_label(widget),
                            "reason": str(getattr(widget, "_mole_form_grid_exempt_reason", "") or "Intentional custom layout."),
                            "columns": metrics["columns"],
                            "child_count": metrics["child_count"],
                        }
                    )
                    return
            except Exception:
                pass

            for child in list(getattr(widget, "winfo_children", lambda: [])()):
                _walk(child)

            metrics = self._alignment_frame_metrics(widget)
            contract = str(getattr(widget, "_mole_form_grid_contract", "") or "").strip()
            if contract:
                contracts.append(
                    {
                        "state": state,
                        "widget": self._alignment_widget_label(widget),
                        "contract": contract,
                        "columns": metrics["columns"],
                        "child_count": metrics["child_count"],
                    }
                )
                return

            if self._alignment_is_contract_candidate(widget):
                findings.append(
                    {
                        "state": state,
                        "widget": self._alignment_widget_label(widget),
                        "columns": metrics["columns"],
                        "child_count": metrics["child_count"],
                        "label_count": metrics["label_count"],
                        "input_count": metrics["input_count"],
                    }
                )

        _walk(root)
        return {"contracts": contracts, "findings": findings, "exemptions": exemptions}

    def _alignment_audit_states(self) -> List[str]:
        states = ["PROJECT", "INTAKE", "SOURCE", "POLLUTANTS", "QAQC", "TEST_MATRIX", "SITE", "REF_AUDIT", "FUEL", "REG", "HARDWARE", "INVENTORY", "EVENTS"]
        if not self._source_schema_complete():
            gated = {"POLLUTANTS", "QAQC", "TEST_MATRIX", "SITE", "REF_AUDIT", "FUEL", "REG"}
            states = [s for s in states if s not in gated]
        if _find_commissioning_tool(self.base_dir) is not None:
            states.append("COMMISSION")
        return states

    def _run_alignment_audit(self) -> Dict[str, Any]:
        previous_state = str(getattr(self, "current_state", "") or "PROJECT")
        states = self._alignment_audit_states()
        report: Dict[str, Any] = {"states": [], "contracts": [], "findings": [], "exemptions": [], "previous_state": previous_state}
        self._alignment_audit_active = True
        try:
            for state in states:
                try:
                    self.goto(state)
                    self.update_idletasks()
                    actual_state = str(getattr(self, "current_state", state) or state)
                    if actual_state in report["states"]:
                        continue
                    report["states"].append(actual_state)
                    payload = self._collect_alignment_audit_findings(self.center, actual_state)
                    report["contracts"].extend(payload.get("contracts") or [])
                    report["findings"].extend(payload.get("findings") or [])
                    report["exemptions"].extend(payload.get("exemptions") or [])
                except Exception as exc:
                    report["findings"].append(
                        {
                            "state": state,
                            "widget": "BUILD",
                            "columns": [],
                            "child_count": 0,
                            "label_count": 0,
                            "input_count": 0,
                            "error": str(exc),
                        }
                    )
        finally:
            self._alignment_audit_active = False
            try:
                self.goto(previous_state)
                self.update_idletasks()
            except Exception:
                pass
        return report

    def _format_alignment_audit_report(self, report: Dict[str, Any]) -> str:
        states = list(dict.fromkeys([str(s) for s in (report.get("states") or [])]))
        contracts = list(report.get("contracts") or [])
        findings = list(report.get("findings") or [])
        exemptions = list(report.get("exemptions") or [])
        lines = [
            "WIZARD ALIGNMENT AUDIT",
            "",
            f"Screens scanned: {len(states)}",
            f"Registered form-grid contracts: {len(contracts)}",
            f"Explicit custom-grid exemptions: {len(exemptions)}",
            f"Potential contract gaps: {len(findings)}",
            "",
            "Scanned states:",
            "  " + (", ".join(states) if states else "(none)"),
            "",
        ]
        if findings:
            lines.append("Potential gaps:")
            for item in findings:
                err = str(item.get("error") or "").strip()
                if err:
                    lines.append(f"  [{item.get('state')}] {item.get('widget')}: BUILD ERROR - {err}")
                    continue
                lines.append(
                    f"  [{item.get('state')}] {item.get('widget')} | cols={item.get('columns')} | grid_children={item.get('child_count')}"
                )
            lines.append("")
        else:
            lines.extend(["Potential gaps:", "  none", ""])

        lines.append("Explicit exemptions:")
        if exemptions:
            for item in exemptions:
                lines.append(
                    f"  [{item.get('state')}] {item.get('widget')} | cols={item.get('columns')} | reason={item.get('reason')}"
                )
        else:
            lines.append("  none")
        lines.append("")

        lines.append("Registered contracts:")
        if contracts:
            for item in contracts:
                lines.append(
                    f"  [{item.get('state')}] {item.get('widget')} -> {item.get('contract')} | cols={item.get('columns')}"
                )
        else:
            lines.append("  none")
        lines.extend(["", "Note: This audit flags standard grid-based form layouts. Custom geometry, repeaters, tables, and canvas-heavy screens may remain intentionally explicit when marked exempt."])
        return "\n".join(lines)

    def _open_alignment_audit_dialog(self) -> None:
        report = self._run_alignment_audit()
        text = self._format_alignment_audit_report(report)
        dlg = tk.Toplevel(self)
        dlg.title("Wizard Alignment Audit")
        dlg.geometry("980x700")
        dlg.configure(bg=self.BG)
        top = tk.Frame(dlg, bg=self.BG)
        top.pack(fill="x", padx=12, pady=(12, 0))
        tk.Label(top, text="Wizard Alignment Audit", bg=self.BG, fg=self.ARCADE_YELLOW, font=("Consolas", 14, "bold")).pack(anchor="w")
        txt_box = tk.Frame(dlg, bg=self.BG)
        txt_box.pack(fill="both", expand=True, padx=12, pady=12)
        txt = tk.Text(txt_box, bg="#0a0f16", fg="#c7d0d9", insertbackground="#c7d0d9", font=("Consolas", 9), wrap="word")
        txt.pack(side="left", fill="both", expand=True)
        sb = tk.Scrollbar(txt_box, command=txt.yview)
        sb.pack(side="right", fill="y")
        txt.configure(yscrollcommand=sb.set)
        txt.insert("1.0", text)
        txt.configure(state="disabled")
        btns = tk.Frame(dlg, bg=self.BG)
        btns.pack(fill="x", padx=12, pady=(0, 12))
        tk.Button(btns, text="Copy Report", command=lambda: (self.clipboard_clear(), self.clipboard_append(text)), bg=self.BTN_BG2, fg=self.BTN_FG, relief="flat").pack(side="left")
        tk.Button(btns, text="Close", command=dlg.destroy, bg=self.BTN_BG, fg=self.BTN_FG, relief="flat").pack(side="right")

    def _collect_text_audit_entries(self, root: tk.Widget, state: str) -> List[Dict[str, str]]:
        entries: List[Dict[str, str]] = []
        visited: set[str] = set()

        def _add(source: str, text: str) -> None:
            txt = str(text or "").strip()
            if txt:
                entries.append({"surface": state, "source": source, "text": txt})

        def _walk(widget: tk.Widget) -> None:
            try:
                wid = str(widget)
            except Exception:
                wid = repr(widget)
            if wid in visited:
                return
            visited.add(wid)

            source = self._alignment_widget_label(widget)
            try:
                txt = str(widget.cget("text") or "").strip()
            except Exception:
                txt = ""
            if txt:
                _add(source, txt)
            try:
                text_var = str(widget.cget("textvariable") or "").strip()
            except Exception:
                text_var = ""
            if text_var:
                try:
                    var_text = str(widget.getvar(text_var) or "").strip()
                except Exception:
                    var_text = ""
                if var_text:
                    _add(f"{source} [var]", var_text)
            if isinstance(widget, ttk.Treeview):
                try:
                    cols = list(widget["columns"] or [])
                except Exception:
                    cols = []
                for col in cols:
                    try:
                        heading_text = str((widget.heading(col) or {}).get("text") or "").strip()
                    except Exception:
                        heading_text = ""
                    if heading_text:
                        _add(f"{source} [heading:{col}]", heading_text)
            for child in list(getattr(widget, "winfo_children", lambda: [])()):
                _walk(child)

        _walk(root)
        return entries

    def _run_text_audit(self) -> Dict[str, Any]:
        previous_state = str(getattr(self, "current_state", "") or "PROJECT")
        states = self._alignment_audit_states()
        entries: List[Dict[str, str]] = []
        self._alignment_audit_active = True
        try:
            for state in states:
                try:
                    self.goto(state)
                    self.update_idletasks()
                    actual_state = str(getattr(self, "current_state", state) or state)
                    entries.extend(self._collect_text_audit_entries(self.center, actual_state))
                except Exception:
                    continue
        finally:
            self._alignment_audit_active = False
            try:
                self.goto(previous_state)
                self.update_idletasks()
            except Exception:
                pass
        return audit_ui_text_entries(entries, diagnostics_only=False)

