    def _dbpaths_open_path(self, path_str: str) -> None:
        p = (path_str or "").strip().strip('"')
        if not p:
            messagebox.showinfo("Open", "Path is empty.")
            return
        try:
            # Windows
            os.startfile(p)  # type: ignore[attr-defined]
            return
        except Exception:
            pass
        try:
            import subprocess, sys
            if sys.platform.startswith("darwin"):
                subprocess.Popen(["open", p])
            else:
                subprocess.Popen(["xdg-open", p])
        except Exception:
            messagebox.showinfo("Open", f"Open this path manually:\n{p}")

    def _documents_library_entries(self) -> List[Dict[str, str]]:
        root = Path(self.base_dir).parent.resolve()
        docs_dir = (root / "docs").resolve()
        work_docs_dir = (docs_dir / "work_instructions").resolve()

        def _sort_key(path_obj: Path) -> Tuple[int, str, float]:
            stem = path_obj.stem
            m = re.search(r"(\d{8})_(\d{4,6})", stem)
            if m:
                return (3, f"{m.group(1)}{m.group(2).ljust(6, '0')}", path_obj.stat().st_mtime)
            m = re.search(r"(\d{4})_(\d{2})_(\d{2})(?:_(\d{3,6}))?", stem)
            if m:
                tail = (m.group(4) or "").ljust(6, "0")
                return (2, f"{m.group(1)}{m.group(2)}{m.group(3)}{tail}", path_obj.stat().st_mtime)
            m = re.search(r"(\d{8})", stem)
            if m:
                return (1, f"{m.group(1)}000000", path_obj.stat().st_mtime)
            return (0, stem.upper(), path_obj.stat().st_mtime)

        def _pick_latest(paths: List[Path]) -> Optional[Path]:
            existing = []
            for path_obj in paths:
                try:
                    if path_obj.exists() and path_obj.is_file():
                        existing.append(path_obj.resolve())
                except Exception:
                    pass
            if not existing:
                return None
            return sorted(existing, key=_sort_key, reverse=True)[0]

        specs: List[Dict[str, Any]] = [
            {
                "category": "Package",
                "title": "Quick Start",
                "note": "Primary package startup, launcher, and verification reference.",
                "paths": [root / "README_FIRST.txt"],
            },
            {
                "category": "Package",
                "title": "Portable Package Notes",
                "note": "Portable deployment layout and build-standard reference.",
                "paths": [root / "PORTABLE_PACKAGE_NOTES.txt"],
            },
            {
                "category": "Core",
                "title": "Technical and Operating Manual",
                "note": "Primary operator workflow, compliance boundary, and build-standard manual.",
                "globs": ["MOLE_DAS_TECHNICAL_AND_OPERATING_MANUAL_*.md"],
            },
            {
                "category": "Core",
                "title": "Calculations and Methodology Appendix",
                "note": "Implemented formulas, normalization rules, and methodology notes.",
                "globs": ["MOLE_DAS_CALCULATIONS_FORMULAS_AND_METHODOLOGIES_APPENDIX_*.md"],
            },
            {
                "category": "Core",
                "title": "Terms, Definitions, and References",
                "note": "Terminology, references, and current workflow vocabulary.",
                "globs": ["MOLE_DAS_TERMS_DEFINITIONS_AND_REFERENCES_*.md"],
            },
            {
                "category": "Core",
                "title": "Release Bulletin",
                "note": "Current build delta, verification summary, and package boundary notes.",
                "globs": ["MOLE_DAS*_RELEASE_BULLETIN.md"],
            },
            {
                "category": "Operations",
                "title": "Commercial Manual / Architecture Plan",
                "note": "Operator-facing documentation structure and next documentation gaps.",
                "globs": ["MOLE_DAS_COMMERCIAL_MANUAL_ARCHITECTURE_AND_ENHANCEMENT_PLAN_*.md"],
            },
            {
                "category": "Work Instructions",
                "title": "Work Instructions Index",
                "note": "Primary entrypoint for the current operator, diagnostics-only, and admin work-instruction set.",
                "paths": [work_docs_dir / "README.md"],
            },
            {
                "category": "Work Instructions",
                "title": "Operator Workflow",
                "note": "Primary field operator workflow for standard Wizard setup and formal runner use.",
                "work_globs": ["mole_das_operator_workflow_*.txt"],
            },
            {
                "category": "Work Instructions",
                "title": "Admin / Engineering Tabs",
                "note": "Non-routine admin, governance, registry, and engineering-support tab reference.",
                "work_globs": ["mole_das_admin_engineering_tabs_*.txt"],
            },
            {
                "category": "Work Instructions",
                "title": "Diagnostics-only Appendix",
                "note": "Diagnostics-only workflow, verification, export, and boundary reference.",
                "work_globs": ["mole_das_diagnostics_only_appendix_*.txt"],
            },
            {
                "category": "Work Instructions",
                "title": "Expanded All-Tabs Baseline Draft",
                "note": "Comprehensive all-tabs baseline draft covering the full Wizard workflow before audience split.",
                "work_globs": ["mole_das_work_steps_*_expanded.txt"],
            },
            {
                "category": "FTIR",
                "title": "FTIR Side-by-Side Simple Workflow",
                "note": "Step-by-step FTIR side-by-side workflow. Use formal runner only.",
                "globs": ["MOLE_DAS_FTIR_SIDE_BY_SIDE_SIMPLE_WORKFLOW_*.md"],
            },
            {
                "category": "FTIR",
                "title": "FTIR Field Form (Markdown)",
                "note": "One-page field form for operator reference or print preparation.",
                "globs": ["MOLE_DAS_FTIR_SIDE_BY_SIDE_FIELD_FORM_1PAGE_*.md"],
            },
            {
                "category": "FTIR",
                "title": "FTIR Field Data Collection Table",
                "note": "Expanded field table for timestamps, calibration, purge, and drift records.",
                "globs": ["MOLE_DAS_FTIR_SIDE_BY_SIDE_FIELD_DATA_COLLECTION_TABLE_*.md"],
            },
            {
                "category": "FTIR",
                "title": "FTIR Field Data Template (CSV)",
                "note": "CSV companion template for structured FTIR field records.",
                "globs": ["MOLE_DAS_FTIR_SIDE_BY_SIDE_FIELD_DATA_TEMPLATE_*.csv"],
            },
            {
                "category": "FTIR",
                "title": "FTIR One-Page Field Form (DOCX)",
                "note": "Packaged printable DOCX field form for operator use.",
                "globs": ["MOLE DAS FTIR Side-by-Side One-Page Field Form *.docx"],
            },
        ]

        entries: List[Dict[str, str]] = []
        seen: set[str] = set()
        for spec in specs:
            candidates: List[Path] = []
            for path_obj in spec.get("paths") or []:
                if isinstance(path_obj, Path):
                    candidates.append(path_obj)
            for pattern in spec.get("globs") or []:
                try:
                    candidates.extend(list(docs_dir.glob(str(pattern))))
                except Exception:
                    pass
            for pattern in spec.get("work_globs") or []:
                try:
                    candidates.extend(list(work_docs_dir.glob(str(pattern))))
                except Exception:
                    pass
            latest = _pick_latest(candidates)
            if latest is None:
                continue
            seen.add(str(latest))
            try:
                modified = datetime.fromtimestamp(latest.stat().st_mtime).strftime("%Y-%m-%d %H:%M")
            except Exception:
                modified = "(n/a)"
            try:
                rel_path = str(latest.relative_to(root))
            except Exception:
                rel_path = str(latest)
            entries.append({
                "category": str(spec.get("category") or "Document"),
                "title": str(spec.get("title") or latest.stem),
                "filename": latest.name,
                "path": str(latest),
                "relative_path": rel_path,
                "modified": modified,
                "note": str(spec.get("note") or ""),
            })

        try:
            if docs_dir.exists():
                for extra in sorted(docs_dir.iterdir(), key=lambda p: p.name.lower()):
                    if (not extra.is_file()) or (str(extra.resolve()) in seen):
                        continue
                    try:
                        modified = datetime.fromtimestamp(extra.stat().st_mtime).strftime("%Y-%m-%d %H:%M")
                    except Exception:
                        modified = "(n/a)"
                    entries.append({
                        "category": "Additional",
                        "title": extra.stem,
                        "filename": extra.name,
                        "path": str(extra.resolve()),
                        "relative_path": str(extra.relative_to(root)),
                        "modified": modified,
                        "note": "Additional packaged document in docs/.",
                    })
        except Exception:
            pass

        return entries

    def _build_documents_library(self) -> None:
        self._header(
            "Documents Library",
            "Latest companion documents for operator reference. The library resolves the newest file in each packaged document family."
        )

        outer = tk.Frame(self.center, bg=self.BG)
        outer.pack(fill="both", expand=True, padx=20, pady=(0, 16))

        tk.Label(
            outer,
            text=(
                "Use this page to open the current operator manuals, work instructions, release bulletin, "
                "package notes, and FTIR companion documents. Drop updated files into docs/ and click Refresh Library."
            ),
            fg=self.FG,
            bg=self.BG,
            justify="left",
            wraplength=1120,
            font=("Consolas", 9),
        ).pack(anchor="w", pady=(0, 8))

        controls = tk.Frame(outer, bg=self.BG)
        controls.pack(fill="x", pady=(0, 8))

        tree_wrap = tk.Frame(outer, bg=self.BG)
        tree_wrap.pack(fill="both", expand=True)

        cols = ("category", "title", "filename", "modified")
        tree = ttk.Treeview(tree_wrap, columns=cols, show="headings", height=14)
        tree.heading("category", text="Category")
        tree.heading("title", text="Document")
        tree.heading("filename", text="Current File")
        tree.heading("modified", text="Updated")
        tree.column("category", width=110, anchor="w")
        tree.column("title", width=280, anchor="w")
        tree.column("filename", width=520, anchor="w")
        tree.column("modified", width=150, anchor="w")

        ysb = ttk.Scrollbar(tree_wrap, orient="vertical", command=tree.yview)
        tree.configure(yscrollcommand=ysb.set)
        tree.pack(side="left", fill="both", expand=True)
        ysb.pack(side="right", fill="y")

        details_var = tk.StringVar(value="Select a document to see its path and usage note.")
        path_var = tk.StringVar(value="")
        count_var = tk.StringVar(value="")
        row_map: Dict[str, Dict[str, str]] = {}

        def _selected_entry() -> Optional[Dict[str, str]]:
            try:
                sel = tree.selection()
                if not sel:
                    return None
                return row_map.get(str(sel[0]))
            except Exception:
                return None

        def _sync_selection(*_args: Any) -> None:
            entry = _selected_entry()
            if not entry:
                details_var.set("Select a document to see its path and usage note.")
                path_var.set("")
                return
            details_var.set(entry.get("note") or "")
            path_var.set(entry.get("relative_path") or entry.get("path") or "")

        def _open_selected() -> None:
            entry = _selected_entry()
            if not entry:
                messagebox.showinfo("Documents Library", "Select a document first.")
                return
            self._dbpaths_open_path(entry.get("path") or "")

        def _open_selected_folder() -> None:
            entry = _selected_entry()
            if not entry:
                messagebox.showinfo("Documents Library", "Select a document first.")
                return
            try:
                p = Path(entry.get("path") or "")
                self._dbpaths_open_path(str(p.parent))
            except Exception:
                messagebox.showinfo("Documents Library", "Selected document path is not available.")

        def _refresh_docs() -> None:
            row_map.clear()
            for iid in tree.get_children():
                tree.delete(iid)
            entries = self._documents_library_entries()
            for idx, entry in enumerate(entries):
                iid = f"doc_{idx}"
                row_map[iid] = entry
                tree.insert(
                    "",
                    "end",
                    iid=iid,
                    values=(
                        entry.get("category") or "",
                        entry.get("title") or "",
                        entry.get("filename") or "",
                        entry.get("modified") or "",
                    ),
                )
            count_var.set(f"Documents indexed: {len(entries)}")
            if entries:
                try:
                    first = tree.get_children()[0]
                    tree.selection_set(first)
                    tree.focus(first)
                except Exception:
                    pass
            _sync_selection()

        tk.Button(
            controls,
            text="Open Selected Document",
            command=_open_selected,
            bg=self.BTN_BG,
            fg=self.BTN_FG,
            relief="flat",
        ).pack(side="left")
        tk.Button(
            controls,
            text="Open Selected Folder",
            command=_open_selected_folder,
            bg=self.BTN_BG2,
            fg=self.BTN_FG,
            relief="flat",
        ).pack(side="left", padx=(8, 0))
        tk.Button(
            controls,
            text="Open Docs Folder",
            command=lambda: self._dbpaths_open_path(str((Path(self.base_dir).parent / "docs").resolve())),
            bg="#1b2a3a",
            fg=self.BTN_FG,
            relief="flat",
        ).pack(side="left", padx=(8, 0))
        tk.Button(
            controls,
            text="Refresh Library",
            command=_refresh_docs,
            bg="#14202d",
            fg=self.BTN_FG,
            relief="flat",
        ).pack(side="left", padx=(8, 0))
        tk.Label(
            controls,
            textvariable=count_var,
            fg="#9fb0c0",
            bg=self.BG,
            font=("Consolas", 9),
        ).pack(side="right")

        tree.bind("<<TreeviewSelect>>", _sync_selection)
        tree.bind("<Double-1>", lambda _e: _open_selected())

        detail_box = tk.LabelFrame(outer, text="Selected Document", bg=self.BG, fg=self.FG)
        detail_box.pack(fill="x", pady=(10, 0))
        tk.Label(
            detail_box,
            textvariable=details_var,
            fg=self.FG,
            bg=self.BG,
            justify="left",
            wraplength=1100,
            font=("Consolas", 9),
        ).pack(anchor="w", padx=10, pady=(8, 4))
        tk.Label(
            detail_box,
            textvariable=path_var,
            fg="#9fb0c0",
            bg=self.BG,
            justify="left",
            wraplength=1100,
            font=("Consolas", 8),
        ).pack(anchor="w", padx=10, pady=(0, 8))

        _refresh_docs()

    def _dbpaths_validate(self) -> None:
        """Validate configured paths and show a compact PASS/WARN summary."""
        items = [
            ("Data root", self.var_db_data_root.get(), "dir", True),
            ("Configs dir", self.var_db_configs_dir.get(), "dir", True),
            ("Master DB (SQLite)", self.var_db_master_db.get(), "file", False),
            ("Rule packs dir", self.var_db_rule_packs_dir.get(), "dir", True),
            ("Sessions dir", self.var_db_sessions_dir.get(), "dir", True),
            ("DAQ runs dir", self.var_db_daq_runs_dir.get(), "dir", True),
            ("Logs dir", self.var_db_logs_dir.get(), "dir", True),
            ("Backups dir", self.var_db_backups_dir.get(), "dir", True),
            ("Assets dir", self.var_db_assets_dir.get(), "dir", True),
            ("Methods DB (JSON)", self.var_db_methods_path.get(), "file", False),
            ("Cylinders DB (JSON)", self.var_db_cylinders_path.get(), "file", False),
            ("Instruments DB (JSON)", self.var_db_instruments_path.get(), "file", False),
        ]

        lines = []
        warn = 0
        for label, raw, kind, required in items:
            s = (raw or "").strip().strip('"')
            if not s:
                if required:
                    warn += 1
                    lines.append(f"[WARN] {label}: (empty)")
                else:
                    lines.append(f"[OK]   {label}: (unset)")
                continue
            try:
                p = Path(os.path.expandvars(os.path.expanduser(s)))
                if not p.is_absolute():
                    p = (self.base_dir / p).resolve()
                ok = p.exists()
                if kind == "dir" and ok and p.is_dir():
                    lines.append(f"[OK]   {label}: {p}")
                elif kind == "file" and ok and p.is_file():
                    lines.append(f"[OK]   {label}: {p}")
                else:
                    warn += 1
                    lines.append(f"[WARN] {label}: {p} (missing)")
            except Exception:
                warn += 1
                lines.append(f"[WARN] {label}: {s} (invalid)")

        title = "DB Paths Validation"
        summary = "PASS" if warn == 0 else f"WARN ({warn})"
        messagebox.showinfo(title, summary + "\n\n" + "\n".join(lines))

    def _dbpaths_reset_defaults(self) -> None:
        """Reset UI fields to the recommended portable defaults (resolved to absolute for readability)."""
        dflt = mole_cfg_default(self.base_dir)
        resolved = mole_cfg_resolve_paths(dflt, self.base_dir)

        self.var_db_data_root.set(str(resolved.get("data_root", "")))
        # configs dir is always derived from data_root for stability
        try:
            self.var_db_configs_dir.set(str((resolved.get("data_root") / "configs") if resolved.get("data_root") else (self.base_dir / "../mole_das_data/configs").resolve()))
        except Exception:
            self.var_db_configs_dir.set("")
        self.var_db_master_db.set(str(resolved.get("db_path", "")))
        self.var_db_rule_packs_dir.set(str(resolved.get("rule_packs_dir", "")))
        self.var_db_sessions_dir.set(str(resolved.get("sessions_dir", "")))
        self.var_db_daq_runs_dir.set(str(resolved.get("daq_runs_dir", "")))
        self.var_db_logs_dir.set(str(resolved.get("logs_dir", "")))
        self.var_db_backups_dir.set(str(resolved.get("backups_dir", "")))
        self.var_db_assets_dir.set(str(resolved.get("assets_dir", "")))

        # Optional overrides: blank = use default lookup order
        self.var_db_methods_path.set("")
        self.var_db_cylinders_path.set("")
        self.var_db_instruments_path.set("")

    def _dbpaths_apply(self) -> None:
        """Persist DB path settings to mole_config.json and reload runtime paths."""
        cfg_p = mole_cfg_path(self.base_dir)
        cfg = mole_cfg_load_or_create(self.base_dir)

        def _clean(s: str) -> str:
            return (s or "").strip().strip('"')

        def _set_path(key: str, raw: str) -> None:
            raw2 = _clean(raw)
            if not raw2:
                cfg["paths"][key] = None
            else:
                cfg["paths"][key] = raw2

        cfg.setdefault("paths", {})
        _set_path("data_root", self.var_db_data_root.get())
        _set_path("db_path", self.var_db_master_db.get())
        _set_path("rule_packs_dir", self.var_db_rule_packs_dir.get())
        _set_path("sessions_dir", self.var_db_sessions_dir.get())
        _set_path("daq_runs_dir", self.var_db_daq_runs_dir.get())
        _set_path("logs_dir", self.var_db_logs_dir.get())
        _set_path("backups_dir", self.var_db_backups_dir.get())
        _set_path("assets_dir", self.var_db_assets_dir.get())

        # Asset DB overrides (optional)
        _set_path("methods_db_path", self.var_db_methods_path.get())
        _set_path("cylinders_db_path", self.var_db_cylinders_path.get())
        _set_path("instruments_db_path", self.var_db_instruments_path.get())

        try:
            mole_cfg_write_through(self.base_dir, cfg)
        except Exception as e:
            messagebox.showerror("DB Paths", f"Failed to write config:\n{cfg_p}\n\n{e}")
            return

        # Reload runtime paths from persisted config
        try:
            self._master_repo = None
        except Exception:
            pass
        try:
            self.mole_cfg = cfg
        except Exception:
            pass

        try:
            self._init_stable_paths_and_config()
            self._load_asset_databases()
            # Refresh UI fields to the resolved runtime state
            self._dbpaths_sync_vars_from_runtime()
            self._refresh_nav()
        except Exception as e:
            messagebox.showerror("DB Paths", f"Applied config, but reload failed:\n\n{e}")
            return

        messagebox.showinfo(
            "DB Paths",
            "Paths saved + applied.\n\n"
            "Tip: Save + Apply Config will embed these resolved paths into the Runner handoff."
        )

    def _build_db_paths(self) -> None:
        self._header("DB Paths", "Paste absolute paths (or Browse) to point MOLE at the correct databases/artifacts.")
        outer = tk.Frame(self.center, bg=self.BG)
        outer.pack(fill="both", expand=True, padx=20, pady=10)

        tk.Label(
            outer,
            text="Operator Panel: map DB locations once, then run the wizard normally.\n"
                 "Settings persist to ../config/mole_config.json and are used by MOLE DAS + DAQ Runner.",
            fg=self.FG,
            bg=self.BG,
            font=("Consolas", 9),
            justify="left"
        ).pack(anchor="w", pady=(0, 10))

        # Scrollable container (multiple path fields)
        wrap = tk.Frame(outer, bg=self.BG)
        wrap.pack(fill="both", expand=True)

        canvas = tk.Canvas(wrap, bg=self.BG, highlightthickness=0)
        vbar = tk.Scrollbar(wrap, orient="vertical", command=canvas.yview)
        canvas.configure(yscrollcommand=vbar.set)
        vbar.pack(side="right", fill="y")
        canvas.pack(side="left", fill="both", expand=True)

        inner = tk.Frame(canvas, bg=self.BG)
        win = canvas.create_window((0, 0), window=inner, anchor="nw")

        def _on_inner(_event=None):
            try:
                canvas.configure(scrollregion=canvas.bbox("all"))
            except Exception:
                pass

        def _on_canvas(event=None):
            try:
                w = int(getattr(event, "width", canvas.winfo_width()))
                canvas.itemconfigure(win, width=w)
            except Exception:
                pass

        inner.bind("<Configure>", _on_inner)
        canvas.bind("<Configure>", _on_canvas)

        def _on_mousewheel(event):
            try:
                d = int(-1 * (event.delta / 120)) if getattr(event, "delta", 0) else 0
                if d:
                    canvas.yview_scroll(d, "units")
            except Exception:
                pass

        def _bind_wheel(_event=None):
            try:
                canvas.bind_all("<MouseWheel>", _on_mousewheel)
                canvas.bind_all("<Button-4>", lambda e: canvas.yview_scroll(-3, "units"))
                canvas.bind_all("<Button-5>", lambda e: canvas.yview_scroll(3, "units"))
            except Exception:
                pass

        def _unbind_wheel(_event=None):
            try:
                canvas.unbind_all("<MouseWheel>")
                canvas.unbind_all("<Button-4>")
                canvas.unbind_all("<Button-5>")
            except Exception:
                pass

        canvas.bind("<Enter>", _bind_wheel)
        canvas.bind("<Leave>", _unbind_wheel)

        def white_entry(parent, var, width=96, readonly=False):
            st = "readonly" if readonly else "normal"
            e = tk.Entry(parent, textvariable=var, width=width, bg="white", fg="black",
                         insertbackground="black", state=st)
            return e

        def _browse_dir(var: tk.StringVar):
            try:
                init = var.get() or str(self.base_dir)
                d = filedialog.askdirectory(initialdir=init, title="Select folder")
                if d:
                    var.set(d)
            except Exception as e:
                messagebox.showerror("Browse", str(e))

        def _browse_file(var: tk.StringVar, title: str, filetypes):
            try:
                init = var.get() or str(self.base_dir)
                f = filedialog.askopenfilename(initialdir=init, title=title, filetypes=filetypes)
                if f:
                    var.set(f)
            except Exception as e:
                messagebox.showerror("Browse", str(e))

        def row(parent, label: str, var: tk.StringVar, kind: str = "dir", required: bool = True, filetypes=None):
            r = tk.Frame(parent, bg=self.BG)
            r.pack(fill="x", padx=12, pady=6)

            tk.Label(r, text=label, fg=self.FG, bg=self.BG, font=("Consolas", 10)).pack(anchor="w")

            e = white_entry(r, var, width=92, readonly=False)
            e.pack(side="left", fill="x", expand=True, padx=(0, 8))

            if kind == "dir":
                tk.Button(r, text="Browse", command=lambda v=var: _browse_dir(v),
                          bg=self.BTN_BG2, fg=self.BTN_FG, relief="flat", padx=10).pack(side="left", padx=4)
            else:
                ft = filetypes or [("All files", "*.*")]
                tk.Button(r, text="Browse", command=lambda v=var: _browse_file(v, f"Select {label}", ft),
                          bg=self.BTN_BG2, fg=self.BTN_FG, relief="flat", padx=10).pack(side="left", padx=4)

            tk.Button(r, text="Open", command=lambda v=var: self._dbpaths_open_path(v.get()),
                      bg=self.BTN_BG2, fg=self.BTN_FG, relief="flat", padx=10).pack(side="left", padx=4)

            if required:
                tk.Label(r, text="required", fg="#c0c0c0", bg=self.BG, font=("Consolas", 8)).pack(side="left", padx=8)
            else:
                tk.Label(r, text="optional", fg="#c0c0c0", bg=self.BG, font=("Consolas", 8)).pack(side="left", padx=8)

        # Ensure vars are current
        try:
            self._dbpaths_sync_vars_from_runtime()
        except Exception:
            pass

        cfg_box = tk.LabelFrame(inner, text="Global Config", bg=self.BG, fg=self.FG)
        cfg_box.pack(fill="x", pady=(0, 10))
        row(cfg_box, "mole_config.json (read-only)", self.var_db_cfg_file, kind="file", required=False, filetypes=[("JSON", "*.json"), ("All files", "*.*")])
        try:
            # lock the config-file entry to avoid accidental edits
            for child in cfg_box.winfo_children():
                if isinstance(child, tk.Frame):
                    for sub in child.winfo_children():
                        if isinstance(sub, tk.Entry) and getattr(sub, "cget", lambda *_: "")("textvariable") == str(self.var_db_cfg_file):
                            sub.configure(state="readonly")
        except Exception:
            pass

        core_box = tk.LabelFrame(inner, text="Core Folders (portable, can be remapped)", bg=self.BG, fg=self.FG)
        core_box.pack(fill="x", pady=(0, 10))
        row(core_box, "Data root folder", self.var_db_data_root, kind="dir", required=True)
        row(core_box, "Configs folder (derived; informational)", self.var_db_configs_dir, kind="dir", required=False)
        try:
            # lock configs dir entry (derived)
            for child in core_box.winfo_children():
                if isinstance(child, tk.Frame):
                    for sub in child.winfo_children():
                        if isinstance(sub, tk.Entry) and getattr(sub, "cget", lambda *_: "")("textvariable") == str(self.var_db_configs_dir):
                            sub.configure(state="readonly")
        except Exception:
            pass
        row(core_box, "Assets folder", self.var_db_assets_dir, kind="dir", required=True)
        row(core_box, "Rule packs folder", self.var_db_rule_packs_dir, kind="dir", required=True)
        row(core_box, "Sessions folder", self.var_db_sessions_dir, kind="dir", required=True)
        row(core_box, "DAQ runs folder", self.var_db_daq_runs_dir, kind="dir", required=True)
        row(core_box, "Logs folder", self.var_db_logs_dir, kind="dir", required=True)
        row(core_box, "Backups folder", self.var_db_backups_dir, kind="dir", required=True)

        db_box = tk.LabelFrame(inner, text="Databases", bg=self.BG, fg=self.FG)
        db_box.pack(fill="x", pady=(0, 10))
        row(db_box, "Master DB (SQLite)", self.var_db_master_db, kind="file", required=True, filetypes=[("SQLite", "*.sqlite *.db"), ("All files", "*.*")])

        json_box = tk.LabelFrame(inner, text="Asset DBs (JSON)", bg=self.BG, fg=self.FG)
        json_box.pack(fill="x", pady=(0, 10))
        row(json_box, "Methods DB (JSON) - optional override", self.var_db_methods_path, kind="file", required=False, filetypes=[("JSON", "*.json"), ("All files", "*.*")])
        row(json_box, "Cylinders DB (JSON) - optional override", self.var_db_cylinders_path, kind="file", required=False, filetypes=[("JSON", "*.json"), ("All files", "*.*")])
        row(json_box, "Instruments DB (JSON) - optional override", self.var_db_instruments_path, kind="file", required=False, filetypes=[("JSON", "*.json"), ("All files", "*.*")])

        btns = tk.Frame(inner, bg=self.BG)
        btns.pack(fill="x", padx=12, pady=(10, 16))

        tk.Button(btns, text="Validate", command=self._dbpaths_validate,
                  bg=self.BTN_BG2, fg=self.BTN_FG, relief="flat", padx=14, pady=8).pack(side="left")
        tk.Button(btns, text="Reset Defaults", command=self._dbpaths_reset_defaults,
                  bg=self.BTN_BG2, fg=self.BTN_FG, relief="flat", padx=14, pady=8).pack(side="left", padx=8)
        tk.Button(btns, text="Apply Paths", command=self._dbpaths_apply,
                  bg=self.ACCENT, fg="black", relief="flat", padx=18, pady=8).pack(side="right")

        tk.Label(inner, text="Note: Apply creates folders as needed. If Master DB is missing, MOLE will initialize it on next launch.",
                 fg="#c0c0c0", bg=self.BG, font=("Consolas", 8)).pack(anchor="w", padx=12, pady=(0, 10))


    def _build_source(self) -> None:
        self._header("Source Details", "Define the emission source for normalization (power/heat/flow basis).")
                # Scrollable container (Source Details can exceed vertical space)
        _outer_wrap = tk.Frame(self.center, bg=self.BG)
        _outer_wrap.pack(fill="both", expand=True, padx=20, pady=10)
        help_mgr = get_ui_help_tooltip_manager(self) if get_ui_help_tooltip_manager is not None else None
        if help_mgr is None:
            class _NullHelpManager:
                @staticmethod
                def bind(*_args, **_kwargs):
                    return None
            help_mgr = _NullHelpManager()

        _canvas = tk.Canvas(_outer_wrap, bg=self.BG, highlightthickness=0)
        _vbar = tk.Scrollbar(_outer_wrap, orient="vertical", command=_canvas.yview)
        _canvas.configure(yscrollcommand=_vbar.set)
        _vbar.pack(side="right", fill="y")

        MARGIN_X = 16  # scroll-area padding (prevents LabelFrame title clipping)
        _canvas.pack(side="left", fill="both", expand=True)

        outer = tk.Frame(_canvas, bg=self.BG)
        _win = _canvas.create_window((MARGIN_X, 0), window=outer, anchor="nw")

        def _src_on_inner_config(event=None):
            try:
                _canvas.configure(scrollregion=_canvas.bbox("all"))
            except Exception:
                pass

        def _src_on_canvas_config(event=None):
            try:
                cw = int(getattr(event, "width", _canvas.winfo_width()))
                w = max(1, cw - (2 * int(MARGIN_X)))
                _canvas.itemconfigure(_win, width=w)
                try:
                    _canvas.coords(_win, int(MARGIN_X), 0)
                except Exception:
                    pass
            except Exception:
                pass

        outer.bind("<Configure>", _src_on_inner_config)
        _canvas.bind("<Configure>", _src_on_canvas_config)

        def _src_on_mousewheel(event):
            try:
                d = int(-1 * (event.delta / 120)) if getattr(event, "delta", 0) else 0
                if d:
                    _canvas.yview_scroll(d, "units")
            except Exception:
                pass

        def _src_bind_wheel(_event=None):
            try:
                _canvas.bind_all("<MouseWheel>", _src_on_mousewheel)
                _canvas.bind_all("<Button-4>", lambda e: _canvas.yview_scroll(-3, "units"))
                _canvas.bind_all("<Button-5>", lambda e: _canvas.yview_scroll(3, "units"))
            except Exception:
                pass

        def _src_unbind_wheel(_event=None):
            try:
                _canvas.unbind_all("<MouseWheel>")
                _canvas.unbind_all("<Button-4>")
                _canvas.unbind_all("<Button-5>")
            except Exception:
                pass

        _canvas.bind("<Enter>", _src_bind_wheel)
        _canvas.bind("<Leave>", _src_unbind_wheel)


        def white_entry(parent, var, width=16):
            return tk.Entry(parent, textvariable=var, width=width, bg="white", fg="black", insertbackground="black")

        def white_combo(parent, values, var, width=16, readonly=True):
            """Readable combobox helper (white field, black text) consistent with white_entry()."""
            state = "readonly" if readonly else "normal"
            try:
                # Dedicated ttk style so the white field renders consistently on Windows.
                style = ttk.Style(parent)
                style_name = "White.TCombobox"
                try:
                    style.configure(style_name,
                                    fieldbackground="white",
                                    background="white",
                                    foreground="black")
                    style.map(style_name,
                              fieldbackground=[("readonly", "white")],
                              foreground=[("readonly", "black")])
                except Exception:
                    pass

                cb = ttk.Combobox(parent, values=list(values), textvariable=var, width=width, state=state)
                try:
                    cb.configure(style=style_name)
                except Exception:
                    pass
                return cb
            except Exception:
                # Fallback: OptionMenu (keeps UI functional even if ttk styling fails).
                try:
                    vals = [str(v) for v in (values or [])]
                    if vals and not (var.get() or "").strip():
                        var.set(vals[0])
                    om = tk.OptionMenu(parent, var, *vals)
                    om.configure(bg="white", fg="black", relief="flat", highlightthickness=0)
                    return om
                except Exception:
                    # Last resort: plain Entry for manual typing
                    return white_entry(parent, var, width=width)

        # --- dynamic application options ---
        def app_options_for(cat: str) -> List[str]:
            cat = (cat or "").strip()
            m = {
                "Engine": ["Stationary Generator", "Gas Compression", "Mechanical Pump", "Transmission/Drive", "Other"],
                "Turbine": ["Generator", "Compressor Drive", "Pump Drive", "Other"],
                "Heater": ["Line Heater", "Process Heater", "Reboiler", "Other"],
                "Boiler": ["Steam Boiler", "Hot Water Boiler", "Other"],
                "Flare": ["Ground Flare", "Elevated Flare", "Enclosed Flare", "Other"],
                "Tank Vent": ["Fixed Roof Tank", "Internal Floating Roof", "External Floating Roof", "Thief Hatch", "Other"],
                "Process Vent": ["Stack Vent", "PSV/PRV", "Blowdown", "Other"],
                "Fugitive / Component": ["Valve", "Pump Seal", "Compressor Seal", "Connector", "Other"],
                "Other": ["Other"],
            }
            return m.get(cat, ["Other"])

        def refresh_application_values():
            vals = app_options_for(self.var_source_category.get())
            try:
                self.cb_source_application.configure(values=vals)
            except Exception:
                try:
                    self.cb_source_application["values"] = vals
                except Exception:
                    pass
            cur = (self.var_source_application.get() or "").strip()
            if cur and cur in vals:
                return
            self.var_source_application.set("" if not vals else vals[0])

        # --- section: identity / schema ---
        box = tk.LabelFrame(outer, text="Source Schema", bg=self.BG, fg=self.FG)
        box.pack(fill="x", padx=10, anchor="nw", pady=(0, 10))
        self._configure_form_grid(box, minspec="two_pair_form")

        ttk.Label(box, text="Source Category:").grid(row=0, column=0, sticky="w", padx=10, pady=8)
        cb_cat = ttk.Combobox(
            box, textvariable=self.var_source_category,
            values=self._source_category_options, state="disabled", width=28
        )
        cb_cat.grid(row=0, column=1, sticky="ew", padx=(0, 10), pady=8)
        help_mgr.bind(cb_cat, "wizard.source.category")

        ttk.Label(box, text="Application:").grid(row=1, column=0, sticky="w", padx=10, pady=8)
        self.cb_source_application = ttk.Combobox(
            box, textvariable=self.var_source_application,
            values=app_options_for(self.var_source_category.get()), state="disabled", width=28
        )
        self.cb_source_application.grid(row=1, column=1, sticky="ew", padx=(0, 10), pady=8)
        help_mgr.bind(self.cb_source_application, "wizard.source.application")


        ttk.Label(box, text="Service Class:").grid(row=2, column=0, sticky="w", padx=10, pady=8)
        cb_sc = ttk.Combobox(
            box, textvariable=self.var_service_class,
            values=["Stationary", "Portable", "Mobile", "Offshore", "Unknown"], state="readonly", width=28
        )
        cb_sc.grid(row=2, column=1, sticky="ew", padx=(0, 10), pady=8)
        help_mgr.bind(cb_sc, "wizard.source.service_class")

        ttk.Label(box, text="Output Type:").grid(row=3, column=0, sticky="w", padx=10, pady=8)
        cb_ot = ttk.Combobox(
            box, textvariable=self.var_output_type,
            values=["Mechanical", "Electrical", "Thermal", "Unknown"], state="readonly", width=28
        )
        cb_ot.grid(row=3, column=1, sticky="ew", padx=(0, 10), pady=8)
        help_mgr.bind(cb_ot, "wizard.source.output_type")

        # Engine cycle classification (2-cycle / 4-cycle) - used downstream for regulatory applicability
        ttk.Label(box, text="Engine Cycle:").grid(row=4, column=0, sticky="w", padx=10, pady=8)
        self.cb_engine_cycle = ttk.Combobox(
            box, textvariable=self.var_engine_cycle,
            values=getattr(self, "_engine_cycle_options", ["UNKNOWN", "2_CYL", "4_CYL"]), state="readonly", width=28
        )
        self.cb_engine_cycle.grid(row=4, column=1, sticky="ew", padx=(0, 10), pady=8)
        help_mgr.bind(self.cb_engine_cycle, "wizard.source.engine_cycle")

        def _refresh_engine_cycle_state(*_args):
            cat_v = (self.var_source_category.get() or "").strip()
            st = "readonly" if cat_v == "Engine" else "disabled"
            try:
                self.cb_engine_cycle.configure(state=st)
            except Exception:
                pass

        try:
            self.var_source_category.trace_add("write", lambda *_: _refresh_engine_cycle_state())
        except Exception:
            pass
        _refresh_engine_cycle_state()

        # Engine cylinder count - stored for regulatory applicability and equipment cataloging
        ttk.Label(box, text="Cyl Count:").grid(row=5, column=0, sticky="w", padx=10, pady=8)
        self.ent_engine_cyl_count = white_entry(box, self.var_engine_cyl_count, width=10)
        self.ent_engine_cyl_count.grid(row=5, column=1, sticky="w", padx=(0, 10), pady=8)
        help_mgr.bind(self.ent_engine_cyl_count, "wizard.source.engine_cyl_count")

        def _refresh_engine_cyl_state(*_args):
            cat_v = (self.var_source_category.get() or "").strip()
            st = "normal" if cat_v == "Engine" else "disabled"
            try:
                self.ent_engine_cyl_count.configure(state=st)
            except Exception:
                pass

        try:
            self.var_source_category.trace_add("write", lambda *_: _refresh_engine_cyl_state())
        except Exception:
            pass
        _refresh_engine_cyl_state()

        ttk.Label(box, text="Notes:").grid(row=6, column=0, sticky="nw", padx=10, pady=8)
        ent_notes = white_entry(box, self.var_source_notes, width=64)
        ent_notes.grid(row=6, column=1, columnspan=3, sticky="ew", padx=(0, 10), pady=8)

        # Inventory binding (optional) - v10.0.9
        inv_row = tk.Frame(box, bg=self.BG)
        inv_row.grid(row=7, column=0, columnspan=4, sticky="w", padx=10, pady=(0, 8))
        bound_iid = (self.session.get("source") or {}).get("instance_id")
        ttk.Label(inv_row, text=f"Inventory Instance: {bound_iid if bound_iid else '(none)'}").pack(side="left")
        tk.Button(
            inv_row,
            text="Open Inventory Registry",
            command=lambda: self.goto("INVENTORY"),
            bg=self.BTN_BG2,
            fg=self.BTN_FG,
            relief="flat",
        ).pack(side="left", padx=(12, 0))


        # --- section: equipment identification ---
        id_box = tk.LabelFrame(outer, text="Equipment Identification", bg=self.BG, fg=self.FG)
        id_box.pack(fill="x", padx=10, anchor="nw", pady=(0, 10))
        self._configure_form_grid(id_box, minspec="two_pair_form")

        ttk.Label(id_box, text="Manufacturer:").grid(row=0, column=0, sticky="w", padx=10, pady=8)
        self.cb_mfr = ttk.Combobox(id_box, textvariable=self.var_manufacturer, values=[], state="normal", width=28)
        self.cb_mfr.grid(row=0, column=1, sticky="ew", padx=(0, 10), pady=8)
        help_mgr.bind(self.cb_mfr, "wizard.source.manufacturer")

        ttk.Label(id_box, text="Model Number:").grid(row=0, column=2, sticky="w", padx=(18, 6), pady=8)
        self.cb_model = ttk.Combobox(id_box, textvariable=self.var_model_number, values=[], state="normal", width=28)
        self.cb_model.grid(row=0, column=3, sticky="ew", padx=(0, 10), pady=8)
        help_mgr.bind(self.cb_model, "wizard.source.model_number")


        try:
            btn_pending = ttk.Button(id_box, text="Review Pending", command=self._open_catalog_pending_review)
            btn_pending.grid(row=0, column=4, sticky="w", padx=(18, 6), pady=8)
        except Exception:
            pass
        ttk.Label(id_box, text="Serial Number:").grid(row=1, column=0, sticky="w", padx=10, pady=8)
        ent_ser = white_entry(id_box, self.var_serial_number, width=30)
        ent_ser.grid(row=1, column=1, sticky="ew", padx=(0, 10), pady=8)
        help_mgr.bind(ent_ser, "wizard.source.serial_number")

        ttk.Label(id_box, text="Asset Tag:").grid(row=1, column=2, sticky="w", padx=(18, 6), pady=8)
        ent_tag = white_entry(id_box, self.var_asset_tag, width=30)
        ent_tag.grid(row=1, column=3, sticky="ew", padx=(0, 10), pady=8)
        help_mgr.bind(ent_tag, "wizard.source.asset_tag")

        def _refresh_catalog_picklists(*_args):
            try:
                cat = (self.var_source_category.get() or "").strip() or "Other"
                mfr_vals = self._catalog_list_manufacturers(cat)
                try:
                    self.cb_mfr.configure(values=mfr_vals)
                except Exception:
                    pass

                mfr = (self.var_manufacturer.get() or "").strip()
                mdl_vals = self._catalog_list_models(cat, mfr)
                try:
                    self.cb_model.configure(values=mdl_vals)
                except Exception:
                    pass
            except Exception:
                pass

        try:
            self.var_source_category.trace_add("write", lambda *_: _refresh_catalog_picklists())
        except Exception:
            pass
        try:
            self.var_manufacturer.trace_add("write", lambda *_: _refresh_catalog_picklists())
        except Exception:
            pass
        try:
            self.var_model_number.trace_add(
                "write",
                lambda *_: self._catalog_apply_source_model_defaults(
                    (self.var_source_category.get() or "").strip() or "Other",
                    (self.var_manufacturer.get() or "").strip(),
                    (self.var_model_number.get() or "").strip(),
                ),
            )
        except Exception:
            pass
        _refresh_catalog_picklists()
        try:
            self._catalog_apply_source_model_defaults(
                (self.var_source_category.get() or "").strip() or "Other",
                (self.var_manufacturer.get() or "").strip(),
                (self.var_model_number.get() or "").strip(),
            )
        except Exception:
            pass

        # --- section: rating / capacity ---
        box2 = tk.LabelFrame(outer, text="Rating / Capacity (for normalization outputs)", bg=self.BG, fg=self.FG)
        box2.pack(fill="x", padx=10, anchor="nw", pady=(0, 10))
        self._configure_form_grid(box2, minspec="two_pair_form")

        ttk.Label(box2, text="Units:").grid(row=0, column=0, sticky="w", padx=10, pady=8)
        cb_units = ttk.Combobox(
            box2, textvariable=self.var_power_units,
            values=["hp", "kW", "MMBtu/hr"], state="readonly", width=12
        )
        cb_units.grid(row=0, column=1, sticky="ew", padx=(0, 10), pady=8)
        help_mgr.bind(cb_units, "wizard.source.power_units")

        ttk.Label(box2, text="Nameplate / Max:").grid(row=0, column=2, sticky="w", padx=10, pady=8)
        ent_max_power = white_entry(box2, self.var_max_power, width=12)
        ent_max_power.grid(row=0, column=3, sticky="ew", padx=(0, 10), pady=8)
        help_mgr.bind(ent_max_power, "wizard.source.max_power")

        ttk.Label(box2, text="Site Rated:").grid(row=1, column=0, sticky="w", padx=10, pady=8)
        ent_site_rated = white_entry(box2, self.var_site_rated_power, width=12)
        ent_site_rated.grid(row=1, column=1, sticky="ew", padx=(0, 10), pady=8)
        help_mgr.bind(ent_site_rated, "wizard.source.site_rated_power")

        ttk.Label(box2, text="Estimated Operating:").grid(row=1, column=2, sticky="w", padx=10, pady=8)
        ent_estimated_power = white_entry(box2, self.var_estimated_power, width=12)
        ent_estimated_power.grid(row=1, column=3, sticky="ew", padx=(0, 10), pady=8)
        help_mgr.bind(ent_estimated_power, "wizard.source.estimated_power")

        ttk.Label(box2, text="Load Basis:").grid(row=2, column=0, sticky="w", padx=10, pady=8)
        cb_basis = ttk.Combobox(
            box2, textvariable=self.var_load_basis,
            values=["NAMEPLATE", "SITE_RATED", "ESTIMATED"], state="readonly", width=14
        )
        cb_basis.grid(row=2, column=1, sticky="ew", padx=(0, 10), pady=8)
        help_mgr.bind(cb_basis, "wizard.source.load_basis")

        # --- section: fuel flow note / basis (optional) ---
        box3 = tk.LabelFrame(outer, text="Fuel Flow (optional; run-to-run variation acknowledged)", bg=self.BG, fg=self.FG)
        box3.pack(fill="x", padx=10, anchor="nw", pady=(0, 10))
        self._configure_form_grid(box3, minspec="two_pair_form")

        ttk.Label(box3, text="Fuel Flow Basis:").grid(row=0, column=0, sticky="w", padx=10, pady=8)
        cb_ff = ttk.Combobox(
            box3, textvariable=self.var_fuel_flow_basis,
            values=["UNSET", "METERED", "MANUAL", "ESTIMATED"], state="readonly", width=14
        )
        cb_ff.grid(row=0, column=1, sticky="ew", padx=(0, 10), pady=8)
        help_mgr.bind(cb_ff, "wizard.source.fuel_flow_basis")
        ttk.Label(box3, text="Units:").grid(row=0, column=2, sticky="w", padx=10, pady=8)

        # Units list is driven by fuel family (gas vs liquid vs dual).
        try:
            self._ensure_fuel_analysis_state()
        except Exception:
            pass
        fam = str((((self.session.get("fuel") or {}).get("analysis") or {}).get("family")) or "GAS").upper()
        if fam not in ("GAS", "LIQUID", "DUAL"):
            fam = "GAS"

        unit_opts_map = {
            "GAS": ["scfh", "scfm", "dscfh", "dscfm", "lb/hr", "kg/hr", "MMBtu/hr"],
            "LIQUID": ["gal/hr", "bbl/day", "L/hr", "lb/hr", "kg/hr", "MMBtu/hr"],
            "DUAL": ["scfh", "scfm", "dscfh", "dscfm", "gal/hr", "bbl/day", "L/hr", "lb/hr", "kg/hr", "MMBtu/hr"],
        }
        unit_opts = unit_opts_map.get(fam, unit_opts_map["GAS"])

        # Normalize the in-memory value to a display string.
        cur_u = (self.var_fuel_flow_units.get() or "").strip()
        cur_disp = unit_token_to_display(cur_u)
        if not cur_disp or (cur_disp not in unit_opts):
            # Heuristic default: gas -> scfh, liquid -> gal/hr
            default_disp = "gal/hr" if fam == "LIQUID" else "scfh"
            if default_disp not in unit_opts:
                default_disp = unit_opts[0]
            self.var_fuel_flow_units.set(default_disp)
        else:
            self.var_fuel_flow_units.set(cur_disp)

