        btn_probe_matrix = tk.Button(r3, text="Probe Matrix", command=_run_probe_matrix,
                  bg=self.BTN_BG2, fg=self.BTN_FG, relief="flat", padx=10, pady=6)
        btn_probe_matrix.pack(side="left", padx=(6, 0))
        probe_matrix_refs["button"] = btn_probe_matrix

        tk.Label(ch_edit, textvariable=var_poll_result, fg=self.MUTED, bg=self.BG, font=("Consolas", 9)).pack(anchor="w", pady=(6, 0))

        diag_box = tk.LabelFrame(ch_edit, text="Raw RTU Diagnostics", bg=self.BG, fg=self.FG)
        diag_box.pack(fill="x", pady=(8, 0))
