    def _build_commissioning(self) -> None:
        """Connectivity gate: reachability + Modbus probe (calls commissioning tool script)."""
        if _find_commissioning_tool(self.base_dir) is None:
            self._header(
                "Connectivity / Commissioning",
                "This runtime package does not include the commissioning tool.",
            )
            pane = tk.Frame(self.center, bg=self.BG)
            pane.pack(fill="both", expand=True, padx=20, pady=14)
            tk.Label(
                pane,
                text="Connectivity / commissioning has been hidden in this runtime package because the shipped helper was only a placeholder stub.",
                bg=self.BG,
                fg=self.MUTED,
                justify="left",
                wraplength=700,
                font=("Consolas", 10),
            ).pack(anchor="w")
            tk.Button(
                pane,
                text="Back to Hardware Profiles",
                command=lambda: self.goto("HARDWARE"),
                bg=self.BTN_BG,
                fg=self.BTN_FG,
                relief="flat",
                padx=12,
                pady=8,
            ).pack(anchor="w", pady=(14, 0))
            return

        self._header(
            "Connectivity / Commissioning",
            "Verify LAN + gateway + Modbus chain before starting a session. This does not modify RAW; it only checks connectivity.",
        )

        outer = tk.Frame(self.center, bg=self.BG)
        outer.pack(fill="both", expand=True, padx=20, pady=10)

        # Lazy-init vars
        try:
            cfg = getattr(self, "mole_cfg", {})
        except Exception:
            cfg = {}

        hw = cfg.get("hardware") if isinstance(cfg.get("hardware"), dict) else {}
        profiles_list = cfg.get("hardware_profiles") if isinstance(cfg.get("hardware_profiles"), list) else []
        profiles: Dict[str, Dict[str, Any]] = {}
        for p in profiles_list:
            if isinstance(p, dict) and p.get("profile_key"):
                profiles[str(p.get("profile_key"))] = p

        default_profile = str(hw.get("profile_id") or "").strip()
        if not default_profile:
            default_profile = next(iter(profiles.keys())) if profiles else ""

        if not hasattr(self, "var_comm_profile"):
            self.var_comm_profile = tk.StringVar(value=default_profile)
        if not hasattr(self, "var_comm_timeout"):
            self.var_comm_timeout = tk.StringVar(value="1.5")
        if not hasattr(self, "var_comm_no_modbus"):
            self.var_comm_no_modbus = tk.BooleanVar(value=False)
        if not hasattr(self, "var_comm_status"):
            self.var_comm_status = tk.StringVar(value="")
        if not hasattr(self, "var_comm_last_report"):
            self.var_comm_last_report = tk.StringVar(value="")

        # Summary
        sum_box = tk.LabelFrame(outer, text="Hardware Summary", bg=self.BG, fg=self.FG)
        sum_box.pack(fill="x", anchor="nw")

        # NOTE: Config supports two shapes:
        # (A) legacy: hardware.p8 + hardware.modbus + lan.gateways as strings
        # (B) current: hardware.lan + hardware.rs485 + hardware.register_map + lan.gateways as dicts
        lan = hw.get("lan") if isinstance(hw.get("lan"), dict) else {}
        rs485 = hw.get("rs485") if isinstance(hw.get("rs485"), dict) else {}
        regm = hw.get("register_map") if isinstance(hw.get("register_map"), dict) else {}
        p8 = hw.get("p8") if isinstance(hw.get("p8"), dict) else {}
        mod = hw.get("modbus") if isinstance(hw.get("modbus"), dict) else {}

        gateways: List[Any] = []
        try:
            gateways = list(lan.get("gateways") or [])
        except Exception:
            gateways = []

        def _fmt_gateways(gws: List[Any]) -> str:
            out: List[str] = []
            for g in gws:
                if isinstance(g, dict):
                    host = str(g.get("host") or g.get("ip") or "").strip()
                    port = g.get("port") or 502
                    name = str(g.get("name") or "").strip()
                    try:
                        port_i = int(str(port).strip())
                    except Exception:
                        port_i = 502
                    if name:
                        out.append(f"{name}@{host}:{port_i}".strip("@"))
                    else:
                        out.append(f"{host}:{port_i}".strip(":"))
                else:
                    out.append(str(g))
            out = [x for x in out if x]
            return ", ".join(out) if out else "(unset)"

        gw_disp = _fmt_gateways(gateways)

        # P8 host resolution
        p8_host = str(p8.get("host") or lan.get("p8_host") or lan.get("p8") or "").strip()

        # Modbus TCP port resolution
        tcp_port_val: Any = mod.get("tcp_port")
        if not tcp_port_val and gateways and isinstance(gateways[0], dict):
            tcp_port_val = gateways[0].get("port")
        if not tcp_port_val:
            tcp_port_val = 502

        # Unit IDs resolution
        unit_ids_any: Any = mod.get("unit_ids")
        if not unit_ids_any:
            unit_ids_any = rs485.get("unit_ids")

        if isinstance(unit_ids_any, dict):
            try:
                uid_disp = ", ".join(f"{k}={v}" for k, v in unit_ids_any.items())
            except Exception:
                uid_disp = str(unit_ids_any)
        elif isinstance(unit_ids_any, list):
            uid_disp = ", ".join(str(x) for x in unit_ids_any) if unit_ids_any else "(unset)"
        else:
            uid_disp = "(unset)"

        reg_disp = ""
        try:
            if regm:
                reg_disp = f"S01->{regm.get('sensor1')} | S02->{regm.get('sensor2')} ({regm.get('register_type','')})"
        except Exception:
            reg_disp = ""

        row = 0

        def _kv(k: str, v: str) -> None:
            nonlocal row
            tk.Label(sum_box, text=k, bg=self.BG, fg=self.FG, font=("Consolas", 10, "bold"), width=22, anchor="w").grid(
                row=row, column=0, sticky="w", padx=10, pady=4
            )
            tk.Label(sum_box, text=v, bg=self.BG, fg=self.MUTED, font=("Consolas", 10), anchor="w", justify="left").grid(
                row=row, column=1, sticky="w", padx=10, pady=4
            )
            row += 1

        _kv("LAN Subnet:", str(lan.get("subnet") or ""))
        _kv("P8 Host:", p8_host)
        _kv("Gateway(s):", gw_disp)
        _kv("Modbus TCP Port:", str(tcp_port_val))
        _kv("Unit IDs:", uid_disp)
        if reg_disp:
            _kv("Register map:", reg_disp)

        # Quick-open buttons
        btns = tk.Frame(outer, bg=self.BG)
        btns.pack(fill="x", pady=(10, 0))

        tk.Button(
            btns,
            text="Open Logs Folder",
            command=lambda: self._dbpaths_open_path(str(getattr(self, "logs_dir", ""))),
            bg=self.BTN_BG,
            fg=self.BTN_FG,
            relief="flat",
        ).pack(side="left")
        tk.Button(
            btns,
            text="Open Sessions Folder",
            command=lambda: self._dbpaths_open_path(str(getattr(self, "sessions_root", ""))),
            bg=self.BTN_BG,
            fg=self.BTN_FG,
            relief="flat",
        ).pack(side="left", padx=(8, 0))
        tk.Button(
            btns,
            text="Open Config",
            command=lambda: self._dbpaths_open_path(str(mole_cfg_path(self.base_dir))),
            bg=self.BTN_BG2,
            fg=self.BTN_FG,
            relief="flat",
        ).pack(side="left", padx=(8, 0))

        # Controls
        ctl = tk.LabelFrame(outer, text="Connectivity Check", bg=self.BG, fg=self.FG)
        ctl.pack(fill="x", anchor="nw", pady=(12, 0))
        self._configure_form_grid(ctl, minspec="hardware_probe_grid")

        tk.Label(ctl, text="Hardware profile:", bg=self.BG, fg=self.FG).grid(row=0, column=0, sticky="w", padx=10, pady=8)
        vals = list(profiles.keys()) if profiles else ([default_profile] if default_profile else [])
        ttk.Combobox(ctl, textvariable=self.var_comm_profile, values=vals, state="readonly", width=28).grid(row=0, column=1, sticky="ew", pady=8)

        tk.Label(ctl, text="Timeout (s):", bg=self.BG, fg=self.FG).grid(row=0, column=2, sticky="w", padx=(18, 10), pady=8)
        ttk.Entry(ctl, textvariable=self.var_comm_timeout, width=10).grid(row=0, column=3, sticky="ew", pady=8)

        tk.Checkbutton(
            ctl,
            text="Skip Modbus probe (TCP only)",
            variable=self.var_comm_no_modbus,
            bg=self.BG,
            fg=self.BTN_FG,
            selectcolor=self.BG,
        ).grid(row=0, column=4, sticky="w", padx=(18, 0), pady=8)

        tk.Label(ctl, textvariable=self.var_comm_status, bg=self.BG, fg=self.ARCADE_YELLOW, font=("Consolas", 10, "bold")).grid(
            row=1, column=0, columnspan=6, sticky="w", padx=10, pady=(0, 8)
        )
        tk.Label(ctl, text="Last report:", bg=self.BG, fg=self.FG).grid(row=2, column=0, sticky="w", padx=10, pady=(0, 10))
        tk.Label(ctl, textvariable=self.var_comm_last_report, bg=self.BG, fg=self.MUTED).grid(row=2, column=1, columnspan=5, sticky="w", padx=10, pady=(0, 10))

        # Output pane
        out_box = tk.LabelFrame(outer, text="Console Output", bg=self.BG, fg=self.FG)
        out_box.pack(fill="both", expand=True, pady=(12, 0))

        txt = tk.Text(out_box, height=14, bg="#0a0f16", fg="#c7d0d9", insertbackground="#c7d0d9", font=("Consolas", 9))
        txt.pack(side="left", fill="both", expand=True)
        sb = tk.Scrollbar(out_box, command=txt.yview)
        sb.pack(side="right", fill="y")
        txt.configure(yscrollcommand=sb.set)

        def _append(s: str) -> None:
            try:
                txt.insert("end", s + "\n")
                txt.see("end")
            except Exception:
                pass

        def _run_check() -> None:
            # Resolve commissioning script
            script = _find_commissioning_tool(self.base_dir)
            if script is None or not script.exists():
                messagebox.showerror("Commissioning", f"Commissioning tool script not found:\n{script}")
                return

            cfg_path = Path(mole_cfg_path(self.base_dir)).resolve()
            profile_sel = (self.var_comm_profile.get() or "").strip()
            timeout_s = (self.var_comm_timeout.get() or "1.5").strip()

            # Default report path in logs dir
            try:
                logs_dir = Path(getattr(self, "logs_dir", self.base_dir)).resolve()
            except Exception:
                logs_dir = self.base_dir
            ts = datetime.now().strftime("%Y%m%d_%H%M%S")
            report_path = logs_dir / f"commissioning_report_{ts}.json"

            cmd = _script_runner_command(script) + [
                "--config",
                str(cfg_path),
                "--profile",
                profile_sel,
                "--report",
                str(report_path),
                "--timeout",
                str(timeout_s),
            ]
            if bool(self.var_comm_no_modbus.get()):
                cmd.append("--no-modbus")

            _append("$")
            _append(" ".join(cmd))

            try:
                p = subprocess.run(cmd, capture_output=True, text=True)
                if p.stdout:
                    _append(p.stdout.strip())
                if p.stderr:
                    _append("[stderr]")
                    _append(p.stderr.strip())

                rc = int(p.returncode)
                if rc == 0:
                    self.var_comm_status.set("PASS: connectivity check succeeded")
                else:
                    self.var_comm_status.set(f"FAIL: connectivity check returned code {rc}")

                self.var_comm_last_report.set(str(report_path))
            except Exception as e:
                self.var_comm_status.set("FAIL: unable to execute commissioning tool")
                _append(f"Exception: {e}")

        tk.Button(
            ctl,
            text="Run Connectivity Check",
            command=_run_check,
            bg=self.ACCENT,
            fg="black",
            relief="flat",
            padx=12,
            pady=6,
        ).grid(row=0, column=5, sticky="e", padx=10, pady=6)

        # Quick guidance (engine)
        guide_text = (
            "Headless Engine command (P8):\n"
            "  python mole_engine_p8_2026_01_18_v10_0_8_ARCADE_RELEASE.py --config ..\\config\\mole_config.json\n"
            "Engine writes: mole_das_data\\sessions\\YYYY-MM-DD\\<session_id>\\raw\\raw_samples.jsonl\n"
        )
        if engine_script is None:
            guide_text = "Headless P8 engine helper is not included in this runtime package.\n"
        tk.Label(outer, text=guide_text, bg=self.BG, fg=self.MUTED, justify="left", font=("Consolas", 9)).pack(anchor="w", pady=(10, 0))




