        # --- Builder controls ---
        row = 0

        ttk.Label(builder, text="instance_id").grid(row=row, column=0, sticky="w", padx=10, pady=(10, 4))
        lbl_iid = ttk.Label(builder, textvariable=self.var_inv_instance_id)
        lbl_iid.grid(row=row, column=1, sticky="w", padx=10, pady=(10, 4))

        ttk.Label(builder, text="Site ID").grid(row=row, column=2, sticky="w", padx=10, pady=(10, 4))
