        def _session_browser_review_text(session_dir: str) -> str:
            try:
                sdir = Path(str(session_dir)).resolve()
            except Exception:
                return "Approval: (invalid session path)\nDeliverable: (unavailable)"
            summary_path = sdir / "exports" / "report_pack_v1" / "summary.json"
            if not summary_path.exists():
                return "Approval: no report-pack review summary found for this session.\nDeliverable: review/export state unavailable."
            try:
                summary = json.loads(summary_path.read_text(encoding="utf-8-sig"))
            except Exception as e:
                return f"Approval: report-pack summary unreadable ({type(e).__name__}).\nDeliverable: review/export state unavailable."
            if not isinstance(summary, dict):
                return "Approval: report-pack summary invalid.\nDeliverable: review/export state unavailable."
            review = summary.get("session_review") if isinstance(summary.get("session_review"), dict) else {}
            signoff = review.get("signoff") if isinstance(review.get("signoff"), dict) else {}
            decision = str(signoff.get("decision") or "UNSIGNED").strip().upper() or "UNSIGNED"
            scope = str(review.get("scope") or "PROJECT_REVIEW").strip().upper() or "PROJECT_REVIEW"
            locked = "LOCKED" if bool(review.get("review_locked")) else "DRAFT"
            reviewer = str(review.get("reviewer_name") or "").strip() or "(unassigned)"
            approver = str(signoff.get("by") or review.get("default_approver") or "").strip() or "(unassigned)"
            basis = str(signoff.get("basis") or "").strip().upper()
            parts = [
                f"Approval: {decision}",
                f"scope={scope}",
                f"state={locked}",
                f"reviewer={reviewer}",
                f"approver={approver}",
            ]
            if basis:
                parts.append(f"basis={basis}")
            final_blk = summary.get("final_report") if isinstance(summary.get("final_report"), dict) else {}
            pack_exists = bool(summary_path.exists())
            final_exists = False
            if final_blk:
                for key in ("markdown_path", "docx_path", "pdf_path"):
                    val = str(final_blk.get(key) or "").strip()
                    if val and Path(val).exists():
                        final_exists = True
                        break
            if decision == "APPROVED":
                deliverable = "Deliverable: READY TO BUILD" if not (pack_exists or final_exists) else "Deliverable: APPROVED"
            elif decision == "CONDITIONAL":
                deliverable = "Deliverable: READY WITH CONDITIONS"
            elif decision == "REJECTED":
                deliverable = "Deliverable: NOT APPROVED"
            elif bool(review.get("review_locked")):
                deliverable = "Deliverable: REVIEW LOCKED - awaiting signoff"
            else:
                deliverable = "Deliverable: DRAFT - lock and sign before export"
            if basis and decision != "UNSIGNED":
                deliverable += f" | basis={basis}"
            if pack_exists or final_exists:
                deliverable += f" | report_pack={'YES' if pack_exists else 'NO'} | final_report={'YES' if final_exists else 'NO'}"
            return " | ".join(parts) + "\n" + deliverable

        def _scan_sessions() -> list[dict[str, Any]]:
            out: list[dict[str, Any]] = []
            try:
                root = Path(getattr(self, "sessions_root", "")).resolve()
            except Exception:
                root = (self.base_dir.parent / "mole_das_data" / "sessions").resolve()

            if not root.exists():
                return out

            for sj in root.rglob("meta/session.json"):
                try:
                    session_dir = sj.parent.parent
                    meta = json.loads(sj.read_text(encoding="utf-8")) if sj.exists() else {}
                    if not isinstance(meta, dict):
                        meta = {}

                    session_id = str(meta.get("session_id") or session_dir.name)
                    run_id = str(meta.get("run_id") or "")
                    created = str(meta.get("created_utc") or "")
                    profile = str(meta.get("profile_key") or "")

                    # day folder is usually parent name
                    day = session_dir.parent.name

                    # processed flag
                    processed_summary = session_dir / "processed" / "summary.json"
                    processed_flag = "YES" if processed_summary.exists() else "NO"

                    out.append(
                        {
                            "date": day,
                            "session_id": session_id,
                            "run_id": run_id,
                            "profile": profile,
                            "created_utc": created,
                            "processed": processed_flag,
                            "session_dir": str(session_dir),
                        }
                    )
                except Exception:
                    continue

            # newest first
            try:
                out.sort(key=lambda r: (r.get("created_utc") or ""), reverse=True)
            except Exception:
                pass

            return out

        def _refresh() -> None:
            try:
                for iid in tree.get_children():
                    tree.delete(iid)
            except Exception:
                pass
            row_map.clear()

            filt = (self.var_sessions_filter.get() or "").strip().lower()
            rows = _scan_sessions()
            shown = 0

            for r in rows:
                if filt:
                    blob = f"{r.get('date','')} {r.get('session_id','')} {r.get('run_id','')} {r.get('profile','')}".lower()
                    if filt not in blob:
                        continue
                iid = tree.insert("", "end", values=(r.get("date"), r.get("session_id"), r.get("run_id"), r.get("profile"), r.get("created_utc"), r.get("processed")))
                row_map[str(iid)] = str(r.get("session_dir"))
                shown += 1

            self.var_sessions_status.set(f"{shown} session(s)")

        def _on_select(_evt: object = None) -> None:
            sel = tree.selection()
            if not sel:
                return
            sid = str(sel[0])
            sdir = row_map.get(sid) or ""
            if sdir:
                self.var_active_session_dir.set(sdir)
                self.var_selected_session_review.set(_session_browser_review_text(sdir))

        tree.bind("<<TreeviewSelect>>", _on_select)

        def _run_processor() -> None:
            sdir = (self.var_active_session_dir.get() or "").strip()
            if not sdir:
                messagebox.showwarning("Process Session", "Select a session first.")
                return

            script = _find_session_processor_tool(self.base_dir)
            if script is None or not script.exists():
                messagebox.showinfo("Process Session", "The RAW->Processed helper is not included in this runtime package.")
                return

            cmd = _script_runner_command(script) + ["--session", sdir]
            _append("$")
            _append(" ".join(cmd))
            try:
                p = subprocess.run(cmd, capture_output=True, text=True)
                if p.stdout:
                    _append(p.stdout.strip())
                if p.stderr:
                    _append("[stderr]")
                    _append(p.stderr.strip())
                if int(p.returncode) == 0:
                    _append("OK: processed outputs written.")
                else:
                    _append(f"FAIL: processor exit code {p.returncode}")
                _refresh()
            except Exception as e:
                _append(f"Exception: {e}")



        def _export_session_zip() -> None:
            sdir = (self.var_active_session_dir.get() or "").strip()
            if not sdir:
                messagebox.showwarning("Export Session", "Select a session first.")
                return

            sname = Path(sdir).name
            default_name = f"MOLE_session_{sname}.zip"
            out_path = filedialog.asksaveasfilename(
                title="Export Session ZIP",
                defaultextension=".zip",
                initialfile=default_name,
                filetypes=[("ZIP files", "*.zip"), ("All files", "*")],
            )
            if not out_path:
                return

            script = _find_session_packager_tool(self.base_dir)
            if script is None or not script.exists():
                messagebox.showerror("Export Session", f"Packager script not found:\n{script}")
                return

            cmd = _script_runner_command(script) + ["export", "--session", sdir, "--out", out_path]
            _append("$")
            _append(" ".join(cmd))
            try:
                p2 = subprocess.run(cmd, capture_output=True, text=True)
                if p2.stdout:
                    _append(p2.stdout.strip())
                if p2.stderr:
                    _append("[stderr]")
                    _append(p2.stderr.strip())
                if int(p2.returncode) == 0:
                    _append(f"OK: exported session zip -> {out_path}")
                else:
                    _append(f"FAIL: exporter exit code {p2.returncode}")
            except Exception as e:
                _append(f"Exception: {e}")

        def _sync_session_to() -> None:
            sdir = (self.var_active_session_dir.get() or "").strip()
            if not sdir:
                messagebox.showwarning("Sync Session", "Select a session first.")
                return

            dest_root = filedialog.askdirectory(title="Select destination sessions root (or USB folder)")
            if not dest_root:
                return

            script = _find_session_sync_tool(self.base_dir)
            if script is None or not script.exists():
                messagebox.showinfo("Sync Session", "The session sync helper is not included in this runtime package.")
                return

            cmd = _script_runner_command(script) + ["--source", sdir, "--dest-root", dest_root, "--verify"]
            _append("$")
            _append(" ".join(cmd))
            try:
                p2 = subprocess.run(cmd, capture_output=True, text=True)
                if p2.stdout:
                    _append(p2.stdout.strip())
                if p2.stderr:
                    _append("[stderr]")
                    _append(p2.stderr.strip())
                if int(p2.returncode) == 0:
                    _append("OK: sync complete")
                else:
                    _append(f"FAIL: sync exit code {p2.returncode}")
            except Exception as e:
                _append(f"Exception: {e}")

        def _import_session_zip() -> None:
            zip_path = filedialog.askopenfilename(
                title="Import Session ZIP",
                filetypes=[("ZIP files", "*.zip"), ("All files", "*")],
            )
            if not zip_path:
                return

            sessions_root = str(getattr(self, "sessions_root", "") or "")
