        def _refresh() -> None:
            try:
                for iid in tree.get_children():
                    tree.delete(iid)
            except Exception:
                pass

            filt = (self.var_inbox_filter.get() or "").strip()
            st = (self.var_inbox_status_filter.get() or "ALL").strip().upper()

            try:
                rows = inboxdb.query_packages(index_db, filter_text=filt, status=st, limit=500, busy_timeout_ms=busy_ms)
            except Exception as e:
                self.var_inbox_status.set("DB ERROR")
                _append(f"DB error: {e}")
                return

            shown = 0
            row_map.clear()
            row_data.clear()

            for r in rows:
                iid = tree.insert(
                    "",
                    "end",
                    values=(
                        r.get("status") or "",
                        r.get("day") or "",
                        r.get("session_id") or "",
                        r.get("run_id") or "",
                        r.get("instance_id") or "",
                        r.get("serial_number") or "",
                        r.get("asset_tag") or "",
                        r.get("manufacturer") or "",
                        r.get("model_number") or "",
                        (r.get("site_id") or "") if r.get("site_id") else "",
                        r.get("created_utc") or "",
                        r.get("package_name") or "",
                    ),
                )
                row_map[str(iid)] = str(r.get("package_path") or "")
                row_data[str(iid)] = dict(r)
                shown += 1

            self.var_inbox_status.set(f"{shown} package(s)")

        def _scan_rescan() -> None:
            _append("$")
            _append(f"Scan inbox -> {inbox_dir}")
            try:
                summ = inboxdb.index_inbox_dir(inbox_dir, index_db, recursive=True, compute_sha=True, busy_timeout_ms=busy_ms)
                _append(f"OK: found={summ.get('found')} indexed={summ.get('indexed')} updated={summ.get('updated')} errors={summ.get('errors')}")
            except Exception as e:
                _append(f"FAIL: {e}")
            _refresh()

        def _export_csv() -> None:
            try:
                import csv
            except Exception:
                messagebox.showerror("Export", "csv module unavailable (unexpected).")
                return

            filt = (self.var_inbox_filter.get() or "").strip()
            st = (self.var_inbox_status_filter.get() or "ALL").strip().upper()
            try:
                rows = inboxdb.query_packages(index_db, filter_text=filt, status=st, limit=5000, busy_timeout_ms=busy_ms)
            except Exception as e:
                messagebox.showerror("Export", f"DB query failed:\n\n{e}")
                return

            out_path = filedialog.asksaveasfilename(
                title="Export Package Index (CSV)",
                defaultextension=".csv",
                initialfile="mole_packages_inbox_export.csv",
                filetypes=[("CSV", "*.csv"), ("All files", "*.*")],
            )
            if not out_path:
                return

            cols = [
                "status",
                "indexed_utc",
                "day",
                "session_id",
                "run_id",
                "instance_id",
                "serial_number",
                "asset_tag",
                "manufacturer",
                "model_number",
                "site_id",
                "location_id",
                "created_utc",
                "package_name",
                "package_sha256",
                "package_path",
                "extracted_session_path",
                "error",
            ]

            try:
                with open(out_path, "w", newline="", encoding="utf-8") as f:
                    w = csv.writer(f)
                    w.writerow(cols)
                    for r in rows:
                        w.writerow([str(r.get(c) or "") for c in cols])
                _append(f"OK: exported CSV -> {out_path}")
            except Exception as e:
                messagebox.showerror("Export", f"Write failed:\n\n{e}")

        def _on_select(_evt: object = None) -> None:
            sel = tree.selection()
            if not sel:
                return
            sid = str(sel[0])
            pkg = row_map.get(sid) or ""
            self.var_inbox_selected_pkg.set(pkg)
            r = row_data.get(sid) or {}
            det = []
            if r.get("instance_id"):
                det.append(f"instance_id: {r.get('instance_id')}")
            if r.get("serial_number"):
                det.append(f"serial: {r.get('serial_number')}")
            if r.get("asset_tag"):
                det.append(f"asset_tag: {r.get('asset_tag')}")
            if r.get("manufacturer") or r.get("model_number"):
                det.append(f"model: {(r.get('manufacturer') or '').strip()} {(r.get('model_number') or '').strip()}")
            if r.get("extracted_session_path"):
                det.append(f"ingested: {r.get('extracted_session_path')}")
            if r.get("error"):
                det.append(f"note: {r.get('error')}")
            self.var_inbox_selected_details.set(" | ".join(det))

        tree.bind("<<TreeviewSelect>>", _on_select)

        def _open_pkg() -> None:
            pth = (self.var_inbox_selected_pkg.get() or "").strip()
            if not pth:
                messagebox.showwarning("Open", "Select a package first.")
                return
            self._dbpaths_open_path(pth)

        def _open_pkg_folder() -> None:
            pth = (self.var_inbox_selected_pkg.get() or "").strip()
            if not pth:
                messagebox.showwarning("Open", "Select a package first.")
                return
            try:
                self._dbpaths_open_path(str(Path(pth).parent))
            except Exception:
                self._dbpaths_open_path(pth)

        def _open_ingested_session() -> None:
            pth = (self.var_inbox_selected_pkg.get() or "").strip()
            if not pth:
                messagebox.showwarning("Open", "Select a package first.")
                return
            try:
                row = inboxdb.get_by_path(index_db, Path(pth), busy_timeout_ms=busy_ms) or {}
                sdir = str(row.get("extracted_session_path") or "").strip()
                if not sdir:
                    messagebox.showinfo("Open", "This package has not been ingested (no extracted session path recorded).")
                    return
                self._dbpaths_open_path(sdir)
            except Exception as e:
                messagebox.showerror("Open", f"Lookup failed:\n\n{e}")

        def _ingest_selected() -> None:
            pth = (self.var_inbox_selected_pkg.get() or "").strip()
            if not pth:
                messagebox.showwarning("Ingest", "Select a package first.")
                return

            script = self.base_dir / "mole_session_package_2026_01_19_v10_0_10_ARCADE_RELEASE.py"
            if not script.exists():
                messagebox.showerror("Ingest", f"Packager ingest script not found:\n{script}")
                return

            cmd = _script_runner_command(script) + ["ingest", "--package", pth, "--sessions-root", str(getattr(self, "sessions_root", ""))]
            _append("$")
            _append(" ".join(cmd))
            try:
                p2 = subprocess.run(cmd, capture_output=True, text=True)
                if p2.stdout:
                    _append(p2.stdout.strip())
                if p2.stderr:
                    _append("[stderr]")
                    _append(p2.stderr.strip())

                if int(p2.returncode) != 0:
                    _append(f"FAIL: exit code {p2.returncode}")
                    return

                # Parse dest from stdout (packager prints: dest: <path>)
                dest = ""
                for line in (p2.stdout or "").splitlines():
                    if line.lower().startswith("dest:"):
                        dest = line.split(":", 1)[1].strip()
                        break

                if dest:
                    try:
                        inboxdb.mark_ingested(index_db, Path(pth), dest, busy_timeout_ms=busy_ms)
                    except Exception:
                        pass
                    _append(f"OK: recorded ingest dest -> {dest}")
                else:
                    _append("OK: ingest complete (dest path not detected from stdout)")

                _refresh()
            except Exception as e:
                _append(f"Exception: {e}")

        # Buttons
        tk.Button(
            btn_row,
            text="Scan / Rescan",
            command=_scan_rescan,
            bg=self.BTN_BG,
            fg=self.BTN_FG,
            relief="flat",
        ).pack(side="left")

        tk.Button(
            btn_row,
            text="Refresh",
            command=_refresh,
            bg=self.BTN_BG2,
            fg=self.BTN_FG,
            relief="flat",
        ).pack(side="left", padx=(8, 0))

        tk.Button(
            btn_row,
            text="Export CSV",
            command=_export_csv,
            bg=self.BTN_BG2,
            fg=self.BTN_FG,
            relief="flat",
        ).pack(side="left", padx=(8, 0))

        tk.Button(
            btn_row,
            text="Open ZIP",
            command=_open_pkg,
            bg=self.BTN_BG2,
            fg=self.BTN_FG,
            relief="flat",
        ).pack(side="left", padx=(18, 0))

        tk.Button(
            btn_row,
            text="Open Folder",
            command=_open_pkg_folder,
            bg=self.BTN_BG2,
            fg=self.BTN_FG,
            relief="flat",
        ).pack(side="left", padx=(8, 0))

        tk.Button(
            btn_row,
            text="Ingest to Sessions",
            command=_ingest_selected,
            bg=self.BTN_BG,
            fg=self.BTN_FG,
            relief="flat",
        ).pack(side="left", padx=(18, 0))

        tk.Button(
            btn_row,
            text="Open Ingested Session",
            command=_open_ingested_session,
            bg=self.BTN_BG2,
            fg=self.BTN_FG,
            relief="flat",
        ).pack(side="left", padx=(8, 0))

        tk.Button(
            btn_row,
            text="Go to Session Browser",
            command=lambda: self.goto("SESSIONS"),
            bg=self.BTN_BG2,
            fg=self.BTN_FG,
            relief="flat",
        ).pack(side="right")

        # initial load
        try:
            _scan_rescan()
        except Exception:
            _refresh()


