        dd_md.grid(row=1, column=6, sticky="ew", padx=(0, 10), pady=6)

        if src_cat == "Heater":
            ttk.Label(ctx_box, text="Heat Input (MMBtu/hr):").grid(row=1, column=3, sticky="w", padx=(18, 6), pady=6)
            tk.Entry(ctx_box, textvariable=self.var_reg_heater_heat_input_mmbtu_hr, width=22, bg="white", fg="black", insertbackground="black").grid(row=1, column=4, sticky="ew", padx=(0, 10), pady=6)
        elif src_cat == "Boiler":
            ttk.Label(ctx_box, text="Heat Input (MMBtu/hr):").grid(row=1, column=3, sticky="w", padx=(18, 6), pady=6)
            tk.Entry(ctx_box, textvariable=self.var_reg_boiler_heat_input_mmbtu_hr, width=22, bg="white", fg="black", insertbackground="black").grid(row=1, column=4, sticky="ew", padx=(0, 10), pady=6)
