    def _build_run(self, mode: str = "TEST") -> None:
        mode_u = str(mode or "TEST").strip().upper()
        diag_selected = bool((self.session.get("session_mode") or {}).get("diagnostic_only"))
        explicit_diag = mode_u in ("DIAG", "DIAGNOSTIC", "DIAGNOSTICS", "DIAG_TEST")
        explicit_diag_sim = mode_u in ("DIAG_SIM", "DIAG_TRAINING", "DIAGNOSTICS_SIM", "DIAGNOSTICS_TRAINING")
        is_sim = mode_u in ("SIM", "TRAINING", "SIM_TRAINING", "SIMTRAINING") or explicit_diag_sim
        is_diag = explicit_diag or (diag_selected and not is_sim)
        is_diag_sim = explicit_diag_sim or (diag_selected and is_sim)

        if is_diag_sim:
            self._header(
                f"DAQ Runner - SIM / TRAINING ({TEXT_DIAGNOSTICS_ONLY})",
                "Launch the simulator-backed diagnostics shell. This path is sandboxed, excludes compliance support, and is intended for diagnostic calculations only.",
            )
        elif is_diag:
            self._header(
                f"DAQ Runner - TEST ({TEXT_DIAGNOSTICS_ONLY})",
                "Launch the production diagnostics shell. This path is operator-facing, excludes compliance support, and is intended for diagnostic calculations only.",
            )
        elif is_sim:
            self._header("DAQ Runner - SIM / TRAINING", "Launch sandboxed DAQ Runner (SIM_TRAINING). Hardware drivers disabled; outputs go to mole_das_data/training.")
        else:
            self._header("DAQ Runner - TEST", "Launch DAQ Runner with the applied session config (production/test).")

        # Status line
        self.lbl_run_status = tk.Label(self.center, text="DAQ Runner: not running", bg=self.BG, fg=self.FG_DIM)
        self.lbl_run_status.pack(anchor="w", padx=10, pady=(0, 8))

        # Launch button (explicit)
        def _launch_now():
            try:
                cfg_p = self._ensure_applied_config_silent()
                if cfg_p is None:
                    return
                launch_mode = "TEST"
                if is_diag_sim:
                    launch_mode = "DIAG_SIM"
                elif is_diag:
                    launch_mode = "DIAG"
                elif is_sim:
                    launch_mode = "SIM"
                self._launch_daq_runner(cfg_p, launch_mode=launch_mode)
            except Exception as e:
                try:
                    messagebox.showerror("DAQ Runner", f"Failed to launch runner:\n\n{e}")
                except Exception:
                    pass

        action_scope = "COMPLIANCE"
        action_label = "DAQ Runner production/test launch"
        if is_diag_sim:
            action_scope = "DIAGNOSTICS"
            action_label = "DAQ Runner diagnostics training launch"
        elif is_diag:
            action_scope = "DIAGNOSTICS"
            action_label = "DAQ Runner diagnostics launch"
        elif is_sim:
            action_scope = "TRAINING"
            action_label = "DAQ Runner training launch"
        policy = self._runtime_action_policy_record(action_label=action_label, action_scope=action_scope)
        policy_decision = str(policy.get("decision") or "ALLOW").strip().upper() or "ALLOW"
        policy_message = str(policy.get("message") or "").strip()
        launch_enabled = policy_decision in ("ALLOW", "WARN")
        if is_diag_sim:
            btn_label = wizard_runner_launch_button_label("SIM", True)
        elif is_diag:
            btn_label = wizard_runner_launch_button_label("TEST", True)
        elif is_sim:
            btn_label = "Launch DAQ Runner (SIM / TRAINING)"
        else:
            btn_label = "Launch DAQ Runner (TEST)"
        launch_btn = tk.Button(
            self.center,
            text=btn_label,
            command=_launch_now,
            bg=self.BTN_BG,
            fg=self.BTN_FG,
            relief="flat",
            padx=10,
            pady=8,
            state=("normal" if launch_enabled else "disabled"),
        )
        launch_btn.pack(anchor="w", padx=10, pady=(0, 10))
        if not launch_enabled:
            tk.Label(
                self.center,
                text=policy_message,
                bg=self.BG,
                fg=self.FG_WARN,
                justify="left",
                wraplength=760,
                font=("Consolas", 9, "bold"),
            ).pack(anchor="w", padx=10, pady=(0, 8))
            if policy_decision == "ACK":
                tk.Button(
                    self.center,
                    text="Acknowledge Stale Package For This Session",
                    command=self._acknowledge_stale_package_status,
                    bg=self.BTN_BG2,
                    fg=self.BTN_FG,
                    relief="flat",
                    padx=10,
                    pady=6,
                ).pack(anchor="w", padx=10, pady=(0, 10))

        # Notes / guardrails
        if is_diag_sim:
            tk.Label(
                self.center,
                text=(
                    f"{TEXT_DIAGNOSTICS_ONLY.upper()} SIM MODE: uses SIM_TRAINING with the diagnostics shell.\n"
                    "This mode is sandboxed and NOT for compliance use."
                ),
                bg=self.BG,
                fg=self.FG_DIM,
                justify="left",
            ).pack(anchor="w", padx=10, pady=(0, 6))
        elif is_diag:
            tk.Label(
                self.center,
                text=(
                    f"{TEXT_DIAGNOSTICS_ONLY.upper()} TEST MODE: launches the diagnostics shell using the applied Wizard session.\n"
                    "Compliance support, report-pack use, and QA/QC trending are disabled for this launch."
                ),
                bg=self.BG,
                fg=self.FG_DIM,
                justify="left",
            ).pack(anchor="w", padx=10, pady=(0, 6))
        elif is_sim:
            tk.Label(self.center,
                     text="TRAINING MODE: simulator follows selected pollutants + QA/QC worksteps.\nTraining data is sandboxed and NOT for compliance use.",
                     bg=self.BG, fg=self.FG_DIM, justify="left").pack(anchor="w", padx=10, pady=(0, 6))
        else:
            tk.Label(self.center,
                     text="TEST MODE: uses configured acquisition driver (hardware/plugin allowed).",
                     bg=self.BG, fg=self.FG_DIM, justify="left").pack(anchor="w", padx=10, pady=(0, 6))

        # One-click: open config folder
        def _open_cfg_dir():
            try:
                p = str(self.config_dir)
                if os.name == "nt":
                    os.startfile(p)  # type: ignore
                else:
                    subprocess.Popen(["xdg-open", p])
            except Exception:
                pass

        tk.Button(self.center, text="Open Config Folder", command=_open_cfg_dir,
                  bg=self.BTN_BG2, fg=self.BTN_FG, relief="flat", padx=10, pady=6).pack(anchor="w", padx=10, pady=(0, 4))

    # ------------------------- Fuel helpers -------------------------

    def _set_fuel_by_button(self, code: str) -> None:
        if code not in self._fuel_button_map:
            return
        cat = self._fuel_button_map[code]
        self.session["fuel"]["fuel_button_code"] = code
        self.session["fuel"]["fuel_category"] = cat
        self.var_fuel_category.set(cat)
        self._refresh_fuel_button_styles()
        self._refresh_nav()

    def _set_fuel_by_dropdown(self) -> None:
        cat = self.var_fuel_category.get().strip()
        self.session["fuel"]["fuel_category"] = cat
        code = ""
        for k, v in self._fuel_button_map.items():
            if v == cat:
                code = k
                break
        self.session["fuel"]["fuel_button_code"] = code
        self._refresh_fuel_button_styles()
        self._refresh_nav()

    def _refresh_fuel_button_styles(self) -> None:
        selected = self.session["fuel"].get("fuel_button_code", "")
        for code, b in self._fuel_buttons.items():
            if code == selected and selected:
                b.configure(bg="#1f6f43", fg="#ffffff")
            else:
                b.configure(bg=self.BTN_BG2, fg=self.BTN_FG)


    # ------------------------- Fuel analysis helpers -------------------------

    def _fuel_get_allowed_profiles(self, fuel_category: str) -> List[str]:
        fuel_category = (fuel_category or "").strip()
        return list(self._fuel_profiles_by_fuel_category.get(fuel_category, []))

    def _ensure_fuel_analysis_state(self, profile_changed: bool = False) -> None:
        """Ensure self.session['fuel']['analysis'] exists and is consistent with fuel category and capture policy."""
        fuel = self.session.get("fuel")
        if not isinstance(fuel, dict):
            self.session["fuel"] = fuel = {}
        fuel_cat = str(fuel.get("fuel_category") or "").strip()
        cap = bool(fuel.get("capture_fuel_analysis", True))

        analysis = fuel.get("analysis")
        if not isinstance(analysis, dict):
            analysis = {"basis": "MOL_PCT", "components": [], "notes": ""}
            fuel["analysis"] = analysis

        allowed = self._fuel_get_allowed_profiles(fuel_cat)
        if not allowed:
            allowed = ["OT_GAS_GENERIC"]

        pid = str(analysis.get("profile_id") or "").strip()
        if (not pid) or (pid not in allowed) or profile_changed:
            pid = allowed[0]
            analysis["profile_id"] = pid

        prof = self._fuel_analysis_profiles.get(pid) or self._fuel_analysis_profiles[allowed[0]]
        fam = str(prof.get("family") or "GAS")
        analysis["family"] = fam
        analysis.setdefault("basis", "MOL_PCT")
        analysis.setdefault("f_factor_basis", "HHV")
        method_code = str(analysis.get("methodology_basis") or "ASTM_D3588_2017").strip() or "ASTM_D3588_2017"
        if method_code not in self._fuel_methodology_label_by_code:
            method_code = "ASTM_D3588_2017"
        analysis["methodology_basis"] = method_code
        analysis["methodology_label"] = self._fuel_methodology_label_by_code.get(method_code, "ASTM D3588-98 (Reapproved 2017)")

        def apply_gas_defaults(force: bool):
            if force or (not (analysis.get("components") or [])):
                comps = []
                for cid, name, pct in prof.get("components", []):
                    try:
                        pct_f = float(pct)
                    except Exception:
                        pct_f = 0.0
                    comps.append({"id": cid, "name": name, "mol_pct": pct_f, "mol_frac": pct_f / 100.0})
                analysis["components"] = comps

        def apply_liquid_defaults(force: bool):
            if "liquid_props" not in analysis or not isinstance(analysis.get("liquid_props"), dict):
                analysis["liquid_props"] = {}
            if force or (not analysis.get("liquid_props")):
                lp = dict(prof.get("liquid_props", {}) or {})
                analysis["liquid_props"] = lp

        # Apply default vs seed logic
        if not cap:
            # Hard-default policy
            if fam in ("GAS", "DUAL"):
                apply_gas_defaults(force=True)
            if fam in ("LIQUID", "DUAL"):
                apply_liquid_defaults(force=True)

            analysis["source"] = "DEFAULT"
            analysis["captured"] = False
            analysis["captured_by"] = None
            analysis["captured_iso"] = None
        else:
            # Capture mode: seed if empty, but do not overwrite user values
            if fam in ("GAS", "DUAL"):
                apply_gas_defaults(force=False)
            if fam in ("LIQUID", "DUAL"):
                apply_liquid_defaults(force=False)

            analysis.setdefault("source", "SEED")
            analysis.setdefault("captured", False)

        # Dual-fuel dg defaults
        if fam == "DUAL":
            dg = fuel.get("dg")
            if not isinstance(dg, dict):
                dg = {}
                fuel["dg"] = dg
            dg_def = prof.get("dg_defaults") or {}
            dg.setdefault("liquid_fuel_label", dg_def.get("liquid_fuel_label", "Diesel"))
            if dg.get("liquid_fraction_volpct") is None:
                dg["liquid_fraction_volpct"] = dg_def.get("liquid_fraction_volpct")

    def _fuel_commit_ui_to_session(self) -> None:
        """Commit current Fuel Analysis UI vars into session (no-op if Fuel tab has not been built yet)."""
        fuel = self.session.get("fuel") or {}
        analysis = fuel.get("analysis") or {}
        fuel["analysis"] = analysis

        method_code = str(self.var_fuel_methodology_basis.get() or "").strip()
        if hasattr(self, "var_fuel_methodology_label"):
            method_code = self._fuel_methodology_code_by_label.get(str(self.var_fuel_methodology_label.get() or "").strip(), method_code)
        method_code = method_code or "ASTM_D3588_2017"
        analysis["methodology_basis"] = method_code
        analysis["methodology_label"] = self._fuel_methodology_label_by_code.get(method_code, "ASTM D3588-98 (Reapproved 2017)")
        analysis["f_factor_basis"] = str(self.var_fuel_f_factor_basis.get() or "HHV")
        # Profile
        if hasattr(self, "var_fuel_profile_id"):
            pid = str(self.var_fuel_profile_id.get() or "").strip()
            if pid:
                analysis["profile_id"] = pid

        # Notes + confirm
        if hasattr(self, "var_fuel_analysis_notes"):
            analysis["notes"] = str(self.var_fuel_analysis_notes.get() or "").strip()
        if hasattr(self, "var_fuel_analysis_confirm"):
            analysis["captured"] = bool(self.var_fuel_analysis_confirm.get())

        # Gas components
        if isinstance(getattr(self, "_fuel_comp_vars", None), dict) and self._fuel_comp_vars:
            comps = []
            for cid, svar in self._fuel_comp_vars.items():
                try:
                    pct = float(str(svar.get()).strip() or 0.0)
                except Exception:
                    pct = 0.0
                name = None
                # prefer existing name
                for c in (analysis.get("components") or []):
                    if c.get("id") == cid:
                        name = c.get("name")
                        break
                name = name or cid
                comps.append({"id": cid, "name": name, "mol_pct": pct, "mol_frac": pct / 100.0})
            analysis["components"] = comps

        # Liquid props
        if isinstance(getattr(self, "_fuel_liquid_vars", None), dict) and self._fuel_liquid_vars:
            lp = analysis.get("liquid_props")
            if not isinstance(lp, dict):
                lp = {}
                analysis["liquid_props"] = lp
            for k, svar in self._fuel_liquid_vars.items():
                lp[k] = float_or_none(str(svar.get()).strip())

        self.session["fuel"] = fuel

    def _build_fuel_gas_editor(self, parent: tk.Widget, editable: bool) -> None:
        fuel = self.session.get("fuel") or {}
        analysis = (fuel.get("analysis") or {})
        comps = list(analysis.get("components") or [])

        # component schema: from profile if available, otherwise current components
        pid = str(analysis.get("profile_id") or "")
        prof = self._fuel_analysis_profiles.get(pid) or {}
        schema = prof.get("components")
        if schema:
            current_total = 0.0
            for c in comps:
                try:
                    current_total += float(c.get("mol_pct", 0.0) or 0.0)
                except Exception:
                    pass
            use_profile_defaults = current_total <= 0.0
            comp_ids = [cid for cid, _nm, _pct in schema]
            # Ensure all schema components exist
            by_id = {c.get("id"): c for c in comps if c.get("id")}
            ordered = []
            for cid, nm, pct_default in schema:
                c = dict(by_id.get(cid) or {})
                if not c:
                    c = {"id": cid, "name": nm, "mol_pct": pct_default}
                c.setdefault("name", nm)
                if use_profile_defaults or c.get("mol_pct") is None:
                    c["mol_pct"] = pct_default
                ordered.append(c)
            comps = ordered
        else:
            comp_ids = [c.get("id") for c in comps if c.get("id")]

        box = tk.Frame(parent, bg=self.BG)
        box.pack(fill="x", anchor="nw", padx=10, pady=10)

        tk.Label(box, text="Gaseous Composition (Mole %)", fg=self.FG, bg=self.BG, font=("Consolas", 10, "bold")).grid(row=0, column=0, sticky="w", pady=(0, 6))

        grid = tk.Frame(box, bg=self.BG)
        grid.grid(row=1, column=0, sticky="w")

        # reset vars
        self._fuel_comp_vars = {}

        def mk_entry(var):
            e = tk.Entry(grid, textvariable=var, width=10,
                         bg=("white" if editable else "#e6e6e6"), fg="black", insertbackground="black")
            if not editable:
                e.configure(state="disabled")
            return e

        r = 0
        for c in comps:
            cid = c.get("id")
            nm = c.get("name") or cid
            sval = tk.StringVar(value=("" if c.get("mol_pct") is None else str(c.get("mol_pct"))))
            self._fuel_comp_vars[cid] = sval
            tk.Label(grid, text=nm, fg=self.FG, bg=self.BG, font=("Consolas", 10)).grid(row=r, column=0, sticky="w", padx=(0, 12), pady=4)
            mk_entry(sval).grid(row=r, column=1, sticky="w", pady=4)
            r += 1

        sum_var = tk.StringVar(value="")

        def update_sum(*_a):
            s = 0.0
            for _cid, v in self._fuel_comp_vars.items():
                try:
                    s += float(str(v.get()).strip() or 0.0)
                except Exception:
                    pass
            sum_var.set(f"Sum: {format_sig(s)} %")
        def _fuel_on_comp_change(*_):
            update_sum()
            try:
                if getattr(self, "_fuel_recompute_after_id", None):
                    self.after_cancel(self._fuel_recompute_after_id)
            except Exception:
                pass
            try:
                # Call directly to avoid any dependency on late-bound methods
                self._fuel_recompute_after_id = self.after(200, lambda: _fuel_recompute_now(self))
            except Exception:
                pass

        for v in self._fuel_comp_vars.values():
            try:
                v.trace_add("write", _fuel_on_comp_change)
            except Exception:
                pass
        _fuel_on_comp_change()

        btn_row = tk.Frame(box, bg=self.BG)
        btn_row.grid(row=2, column=0, sticky="w", pady=(8, 0))

        tk.Label(btn_row, textvariable=sum_var, fg="#9fb0c0", bg=self.BG, font=("Consolas", 9)).pack(side="left")

        def normalize():
            vals = {}
            s = 0.0
            for cid, v in self._fuel_comp_vars.items():
                try:
                   x = float(str(v.get()).strip() or 0.0)
                except Exception:
                   x = 0.0
                vals[cid] = x
                s += x
            if s <= 0:
                return
            for cid, x in vals.items():
                    self._fuel_comp_vars[cid].set(format_sig((x / s) * 100.0))

        if editable:
            tk.Button(btn_row, text="Normalize to 100", command=normalize,
                      bg=self.BTN_BG2, fg=self.BTN_FG, relief="flat").pack(side="left", padx=(16, 0))

    def _build_fuel_liquid_editor(self, parent: tk.Widget, editable: bool) -> None:
        fuel = self.session.get("fuel") or {}
        analysis = (fuel.get("analysis") or {})
        lp = dict((analysis.get("liquid_props") or {}))
        pid = str(analysis.get("profile_id") or "")
        prof = self._fuel_analysis_profiles.get(pid) or {}
        prof_lp = dict(prof.get("liquid_props") or {})
        has_liquid_values = any(v is not None for v in lp.values())
        if prof_lp and (not has_liquid_values):
            lp = dict(prof_lp)
        elif prof_lp:
            for key, val in prof_lp.items():
                if lp.get(key) is None:
                    lp[key] = val

        box = tk.Frame(parent, bg=self.BG)
        box.pack(fill="x", anchor="nw", padx=10, pady=(0, 10))

        tk.Label(box, text="Liquid Fuel Properties (defaults based on ISO/EPA/API-style typical values)",
                 fg=self.FG, bg=self.BG, font=("Consolas", 10, "bold")).grid(row=0, column=0, sticky="w", pady=(0, 6), columnspan=4)

        grid = tk.Frame(box, bg=self.BG)
        grid.grid(row=1, column=0, sticky="w")

        self._fuel_liquid_vars = {}

        def mk(label, key, r, c, width=12):
            tk.Label(grid, text=label, fg=self.FG, bg=self.BG, font=("Consolas", 10)).grid(row=r, column=c, sticky="w", padx=(0, 10), pady=4)
            var = tk.StringVar(value=("" if lp.get(key) is None else str(lp.get(key))))
            self._fuel_liquid_vars[key] = var
            ent = tk.Entry(grid, textvariable=var, width=width,
                           bg=("white" if editable else "#e6e6e6"), fg="black", insertbackground="black")
            if not editable:
                ent.configure(state="disabled")
            ent.grid(row=r, column=c+1, sticky="w", pady=4)

        mk("Density (lb/gal):", "density_lb_per_gal", 0, 0)
        mk("HHV (Btu/lb):", "HHV_Btu_per_lb", 0, 2)
        mk("LHV (Btu/lb):", "LHV_Btu_per_lb", 0, 4)
        mk("C (wt%):", "C_wt_pct", 1, 0)
        mk("H (wt%):", "H_wt_pct", 1, 2)
        mk("S (wt%):", "S_wt_pct", 2, 0)
        mk("O (wt%):", "O_wt_pct", 2, 2)
        mk("N (wt%):", "N_wt_pct", 3, 0)

        # Dual-fuel liquid fraction
        fam = str(analysis.get("family") or "")
        if fam == "DUAL":
            dg = (fuel.get("dg") or {})
            if not isinstance(dg, dict):
                dg = {}
                fuel["dg"] = dg
            tk.Label(grid, text=with_colon(TEXT_DG_LIQUID_SHARE_SELECTED_HEAT_INPUT), fg=self.FG, bg=self.BG, font=("Consolas", 10)).grid(row=4, column=0, sticky="w", padx=(0, 10), pady=4)
            v = tk.StringVar(value=("" if dg.get("liquid_fraction_volpct") is None else str(dg.get("liquid_fraction_volpct"))))
            self._fuel_liquid_vars["dg_liquid_fraction_volpct"] = v
            ent = tk.Entry(grid, textvariable=v, width=22,
                           bg=("white" if editable else "#e6e6e6"), fg="black", insertbackground="black")
            if not editable:
                ent.configure(state="disabled")
            ent.grid(row=4, column=1, sticky="w", pady=4)

            tk.Label(grid, text="DG liquid label:", fg=self.FG, bg=self.BG, font=("Consolas", 10)).grid(row=4, column=2, sticky="w", padx=(0, 10), pady=4)
            v2 = tk.StringVar(value=str(dg.get("liquid_fuel_label") or "Diesel"))
            self._fuel_liquid_vars["dg_liquid_fuel_label"] = v2
            ent2 = tk.Entry(grid, textvariable=v2, width=20,
                            bg=("white" if editable else "#e6e6e6"), fg="black", insertbackground="black")
            if not editable:
                ent2.configure(state="disabled")
            ent2.grid(row=4, column=3, sticky="w", pady=4)


        # Auto-recompute when liquid properties change
        def _fuel_on_liquid_change(*_):
            try:
                if getattr(self, "_fuel_recompute_after_id", None):
                    self.after_cancel(self._fuel_recompute_after_id)
            except Exception:
                pass
            try:
                self._fuel_recompute_after_id = self.after(200, lambda: _fuel_recompute_now(self))
            except Exception:
                pass

        for v in self._fuel_liquid_vars.values():
            try:
                v.trace_add("write", _fuel_on_liquid_change)
            except Exception:
                pass

