    def _validate_before_apply(self) -> Optional[str]:
        """
        Hard gate for Save + Apply.

        Current policy (single source of truth = wizard config):
       - At least one pollutant must be selected.
       - For EVERY selected pollutant, the pollutant prescription MUST be complete:
            * method resolved (AUTO -> resolved)
            * expected max + expected units
            * analyzer/instrument ID + channel ID
            * zero cylinder + span cylinder
       - If QA/QC is REQUIRED by policy (Record=Y & Token=Y & NOT DIAG),
          OR if DIAG opted-in to Cal/Linearity capture:
            * QA/QC binding must be present
            * Test Matrix must exist and include all required tests (CAL/LIN/CYLINDER_META + method-specific tests)
            * CAL/LIN points must meet minimums
       - If AUTO_WEATHER / Auto-compile weather is enabled, either Station ID OR (lat/lon) must be provided.
       - Compressibility mode is limited to IDEAL or FIXED_Z in this build.
        """
        self._sync_session_from_vars()

        # Ensure deterministic binding before validation
        try:
            self._pollutants_resolve_and_bind()
        except Exception as e:
            return f"Pollutant resolver error: {e}"

        proj = self.session.get("project", {}) or {}
        if not proj.get("job_id"):
            return "Job ID is required."
        if not (self.session.get("fuel", {}) or {}).get("fuel_category"):
            return "Fuel category is required."
        if not (self.session.get("source", {}) or {}).get("source_category"):
            return "Source category is required (Source Details)."


        if not (self.session.get("source", {}) or {}).get("application"):
            return "Source application is required (Source Details)."

        # Job Intake Checklist (QA Routing Sheet) gate (only when compliance may be supported)
        smode = self.session.get("session_mode") or {}
        if bool(smode.get("may_support_compliance", False)):
            ok, missing = self._intake_check_complete()
            if not ok:
                head = ", ".join(missing[:10])
                tail = " ..." if len(missing) > 10 else ""
                return f"Job Intake Checklist incomplete (QA Routing Sheet). Missing: {head}{tail}"

        # Exhaust flow determination requirements (Source Details)
        ex = ((self.session.get("source") or {}).get("exhaust_flow") or {})
        method = str(ex.get("method") or "").strip()
        if method not in ("STOICH_FUEL", "STACK_MEASURED", "MANUFACTURER"):
            return "Exhaust flow determination method is required (Source Details)."

        if method == "STOICH_FUEL":
            sf = ex.get("stoich_fuel") or {}
            if (not bool(sf.get("deferred", False))) and (sf.get("fuel_flow_value") in (None, "", 0)):
                return "Exhaust flow: Stoichiometric via Fuel Input requires fuel flow (value) unless deferred to DAQ Runner."
        elif method == "STACK_MEASURED":
            sm = ex.get("stack_measured") or {}
            if not str(sm.get("epa_method") or "").strip():
                return "Exhaust flow: Measured at Stack requires selecting the EPA Method."
        elif method == "MANUFACTURER":
            mf = ex.get("manufacturer") or {}
            basis = str(mf.get("basis") or "").strip()
            if basis == "HEAT_INPUT":
                if mf.get("heat_input_mmbtu_hr") in (None, "", 0):
                    return "Exhaust flow: Manufacturer Inputs (Heat Input) requires heat input (MMBtu/hr)."
            elif basis == "HEAT_RATE":
                if mf.get("rated_power_hp") in (None, "", 0):
                    return "Exhaust flow: Manufacturer Inputs (Heat Rate) requires rated power (hp)."
                if mf.get("load_fraction") in (None, ""):
                    return "Exhaust flow: Manufacturer Inputs (Heat Rate) requires load fraction (0-1)."
                if mf.get("heat_rate_btu_hp_hr") in (None, "", 0):
                    return "Exhaust flow: Manufacturer Inputs (Heat Rate) requires heat rate (Btu/hp-hr)."
            elif basis == "BSFC":
                if mf.get("rated_power_hp") in (None, "", 0):
                    return "Exhaust flow: Manufacturer Inputs (BSFC) requires rated power (hp)."
                if mf.get("load_fraction") in (None, ""):
                    return "Exhaust flow: Manufacturer Inputs (BSFC) requires load fraction (0-1)."
                if mf.get("bsfc_lb_hp_hr") in (None, "", 0):
                    return "Exhaust flow: Manufacturer Inputs (BSFC) requires BSFC (lb/hp-hr)."
            else:
                return "Exhaust flow: Manufacturer Inputs requires selecting a basis (Heat Input / Heat Rate / BSFC)."


        poll = self.session.get("pollutants") or {}
        selected = poll.get("selected") or []
        if not selected:
            return "Select at least one pollutant (Pollutants panel)."

        pres = poll.get("prescriptions") or {}
        qaqc = self.session.get("qa_qc") or {}
        method_map = qaqc.get("method_map") or {}

        missing: List[str] = []
        for code in selected:
            p = pres.get(code) or {}

            eff_method = method_map.get(code) or p.get("method") or p.get("method_selected")
            if not eff_method or str(eff_method).strip() in ("", "AUTO"):
                missing.append(f"{code}: method")

            if p.get("expected_max") in (None, "", 0):
                missing.append(f"{code}: expected max")

            if not str(p.get("expected_units") or "").strip():
                missing.append(f"{code}: expected units")

            if p.get("instrument_id") in (None, "", "(unset)"):
                missing.append(f"{code}: analyzer/instrument")

            ch = (p.get("channel_id") or p.get("instrument_channel") or "").strip()
            if ch in (None, "", "(unset)"):
                missing.append(f"{code}: channel")

            if p.get("zero_cylinder_id") in (None, "", "(unset)"):
                missing.append(f"{code}: zero cylinder")

            if p.get("span_cylinder_id") in (None, "", "(unset)"):
                missing.append(f"{code}: span cylinder")

        if missing:
            head = ", ".join(missing[:10])
            tail = " ..." if len(missing) > 10 else ""
            return f"Pollutants panel incomplete. Missing: {head}{tail}"

        if not qaqc.get("profile_effective"):
            return "QA/QC profile is not resolved (Pollutants -> QA/QC binding)."

        # Weather requirements
        sc = self.session.get("site_conditions") or {}
        wc = sc.get("weather_compile") or {}
        if wc.get("enabled") or sc.get("mode") == "AUTO_WEATHER":
            station_id = str(wc.get("station_id") or "").strip()
            loc = sc.get("location") or {}
            lat_ok = loc.get("lat") is not None
            lon_ok = loc.get("lon") is not None
            if not station_id and not (lat_ok and lon_ok):
                return "AUTO_WEATHER / Auto-compile weather requires Station ID or coordinates (lat/lon) (Site Conditions)."

        # QA/QC + Test Matrix requirements (policy-driven)
        required_by_policy = self._qaqc_required_by_policy()
        diag_optin = self._diag_cal_lin_prompt_needed() and bool((self.session.get("qa_qc") or {}).get("diag_optin_cal_lin"))

        if required_by_policy or diag_optin:
            tm = self.session.get("test_matrix")
            if not tm:
                return "Test Matrix is required (QA/QC -> Test Matrix)."

            tests = tm.get("tests") or []
            if not tests:
                return "Test Matrix is empty (Test Matrix)."

            present_ids = {t.get("id") for t in tests if t.get("id")}
            required_ids = {"CYLINDER_META", "CAL", "LIN"}
            for tid in (qaqc.get("secondary_required_tests") or []):
                if tid:
                    required_ids.add(str(tid))

            missing_tests = sorted([tid for tid in required_ids if tid not in present_ids])
            if missing_tests:
                return "Test Matrix missing required tests: " + ", ".join(missing_tests)

            unresolved_tol: List[str] = []
            for s in (tm.get("steps") or []):
                stype = str(s.get("type") or "").strip().upper()
                if stype not in {"ZERO", "SPAN", "CAL_ERROR", "DRIFT"}:
                    continue
                if str(s.get("tol_default") or "").strip():
                    continue
                if str(s.get("tol_override") or "").strip():
                    continue
                label = str(s.get("label") or "").strip() or stype
                method_id = str(s.get("method_id") or "").strip()
                if method_id:
                    label = f"{label} [{method_id}]"
                unresolved_tol.append(label)
            if unresolved_tol:
                head = ", ".join(unresolved_tol[:6])
                tail = " ..." if len(unresolved_tol) > 6 else ""
                return (
                    "Test Matrix has uncodified method tolerances with no acknowledged override: "
                    + head
                    + tail
                )

            # Points + waive governance for required tests
            for t in tests:
                tid = t.get("id")
                if tid in ("CAL", "LIN"):
                    try:
                        pts = int(t.get("points", 0))
                        minp = int(t.get("min_points", 0))
                    except Exception:
                        return f"Invalid points configuration for {tid} (Test Matrix)."
                    if pts < minp:
                        return f"{tid} points below minimum (have {pts}, need {minp})."

                if bool(t.get("required")) and bool(t.get("waived")):
                    if not str(t.get("waive_reason") or "").strip():
                        return f"{tid} is waived but no waiver reason provided (Test Matrix)."


        # Fuel Analysis capture requirements
        fuel = self.session.get("fuel") or {}
        fa = (fuel.get("analysis") or {})
        fam = str(fa.get("family") or "").strip() or "GAS"
        if bool(fuel.get("capture_fuel_analysis", True)):
            if not bool(fa.get("captured", False)):
                return "Fuel Analysis capture is enabled but not confirmed (Fuel Analysis)."
            if fam in ("GAS", "DUAL"):
                comps = list(fa.get("components") or [])
                if not comps:
                    return "Fuel Analysis capture is enabled but gaseous components are empty (Fuel Analysis)."
                s = 0.0
                for c in comps:
                    try:
                        s += float(c.get("mol_pct", 0.0) or 0.0)
                    except Exception:
                        pass
                if s < 95.0 or s > 105.0:
                    return f"Fuel Analysis composition does not sum to ~100% (sum={format_sig(s)}%)."
            if fam in ("LIQUID", "DUAL"):
                lp = fa.get("liquid_props") or {}
                if (lp.get("density_lb_per_gal") is None) or (lp.get("LHV_Btu_per_lb") is None):
                    return "Fuel Analysis capture is enabled but liquid properties are incomplete (need density + LHV)."

        sc = self.session.get("site_conditions") or {}
        z_model = _normalize_z_model(sc.get("z_model"))
        if z_model == "FIXED_Z" and float_or_none(sc.get("fixed_z")) is None:
            return "FIXED_Z compressibility mode selected, but Fixed Z is empty (Site Conditions)."

        return None

    # ------------------------- DAQ Runner auto-launch -------------------------

    def _ensure_run_artifacts(self, session_cfg_path: Path) -> None:
        """Create deterministic session artifacts for DAQ runner handoff.

        v10.0.12 unifies the DAQ Runner evidence contract with the Headless Engine:

          mole_das_data/sessions/YYYY-MM-DD/<session_id>/
            runner_config.json
            session_profile.json
            meta/{session.json,build.json,manifest.json}
            raw/{raw_samples.jsonl,raw_events.jsonl,comm_health.jsonl}
            processed/
            exports/

        Notes
        -----
        * We keep paths.daq_run_dir as a backward-compatible alias that points to the
          session directory (older runner builds used a separate daq_runs tree).
        * The DAQ Runner is responsible for writing RAW evidence into raw/*.jsonl.
        """
        day = datetime.now().astimezone().strftime("%Y-%m-%d")
        day_dir = Path(self.sessions_root) / day
        safe_mkdir(day_dir)
        try:
            base_session_id = _project_session_folder_slug(self.session.get("project") or {}, "job")
        except Exception:
            base_session_id = "job"
        session_id = _unique_child_name(day_dir, base_session_id)
        sess_dir = day_dir / session_id
        safe_mkdir(sess_dir)
        for sub in ("meta", "raw", "processed", "exports"):
            safe_mkdir(sess_dir / sub)

        # Runner config = full session config with deterministic paths embedded
        runner_cfg = json.loads(json.dumps(self.session))  # safe deep copy

        paths = (runner_cfg.get("paths") or {})
        paths.update({
            "data_root": str(self.data_root),
            "assets_dir": str(self.assets_dir),
            "logs_dir": str(self.logs_dir),
            "backups_dir": str(self.backups_dir),
            "sessions_dir": str(self.sessions_root),
            "daq_runs_dir": str(self.daq_runs_root),
            "rule_packs_dir": str(self.rule_packs_dir),
            "db_path": str(self.master_db_path),
            "session_config_path": str(session_cfg_path),
            "session_dir": str(sess_dir),
            # Back-compat alias (old contract used a separate daq_runs tree)
            "daq_run_dir": str(sess_dir),
        })
        runner_cfg["paths"] = paths
        runner_cfg["session_id"] = session_id
        runner_cfg["run_id"] = session_id
        runner_cfg["run_day"] = day

        runner_cfg_path = sess_dir / "runner_config.json"
        write_json(runner_cfg_path, runner_cfg)

        # Session profile (smaller contract)
        src = runner_cfg.get("source") or {}
        reg = runner_cfg.get("regulatory") or {}
        ctx = (reg.get("context") or {})
        profile = {
            "session_id": session_id,
            "run_id": session_id,
            "created_at": now_iso(),
            "site_id": (runner_cfg.get("project") or {}).get("job_id") or None,
            "location_id": (runner_cfg.get("project") or {}).get("asset_unit_id") or None,
            "source_category": src.get("source_category"),
            "manufacturer": src.get("manufacturer"),
            "model_number": src.get("model_number"),
            "serial_number": src.get("serial_number"),
            "asset_tag": src.get("asset_tag"),
            "instance_id": src.get("instance_id"),
            "manufacture_date": src.get("manufacture_date"),
            "install_date": src.get("install_date"),
            "engine_cycle": ctx.get("engine_cycle"),
            "engine_cyl_count": src.get("engine_cyl_count"),
            "duty_value": src.get("duty_value"),
            "duty_unit": src.get("duty_unit"),
            "paths": {
                "runner_config_path": str(runner_cfg_path),
                "session_config_path": str(session_cfg_path),
                "session_dir": str(sess_dir),
                "daq_run_dir": str(sess_dir),
                "db_path": str(self.master_db_path),
                "logs_dir": str(self.logs_dir),
            },
        }
        session_profile_path = sess_dir / "session_profile.json"
        write_json(session_profile_path, profile)

        # Create a minimal meta/session.json so session tooling has a consistent target.
        try:
            meta_session = {
                "session_id": session_id,
                "run_id": session_id,
                "created_utc": datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ'),
                "source": {
                    "source_category": src.get("source_category"),
                    "manufacturer": src.get("manufacturer"),
                    "model_number": src.get("model_number"),
                    "serial_number": src.get("serial_number"),
                    "asset_tag": src.get("asset_tag"),
                    "instance_id": src.get("instance_id"),
                },
                "instance_id": src.get("instance_id"),
            }
            write_json(sess_dir / "meta" / "session.json", meta_session)
        except Exception:
            pass

        # Reflect into in-memory session for downstream launch logic
        self.session.setdefault("paths", {})
        self.session["paths"].update({
            "runner_config_path": str(runner_cfg_path),
            "session_profile_path": str(session_profile_path),
            "session_dir": str(sess_dir),
            "daq_run_dir": str(sess_dir),
            "session_config_path": str(session_cfg_path),
            "db_path": str(self.master_db_path),
            "logs_dir": str(self.logs_dir),
        })

    def _ensure_applied_config_silent(self) -> Optional[Path]:
        """Write session config JSON (without popups) if it validates.

        Returns the config path on success, else None.
        """
        self._sync_session_from_vars()
        # Ensure deterministic binding before validation
        try:
            self._pollutants_resolve_and_bind()
        except Exception:
            pass

        try:
            self._ensure_test_matrix()
        except Exception:
            pass

        err = None
        try:
            err = self._validate_before_apply()
        except Exception as e:
            err = str(e)

        if err:
            try:
                messagebox.showerror("DAQ Runner", f"Cannot launch until config is valid:\n\n{err}")
            except Exception:
                pass
            return None

        try:
            job = self.session["project"]["job_id"]
        except Exception:
            job = "UNSET"

        out_path = self.config_dir / f"mole_session_{job}.json"
        try:
            self.session.setdefault("meta", {})["applied_iso"] = now_iso()
            self.session.setdefault("paths", {})["session_config_path"] = str(out_path)
        except Exception:
            pass

        try:
            write_json(out_path, self.session)
        except Exception as e:
            try:
                messagebox.showerror("DAQ Runner", f"Failed to write config:\n{out_path}\n\n{e}")
            except Exception:
                pass
            return None

        # Enable navigation once applied (silent)
        try:
            self.nav_enabled = True
            self._refresh_nav()
        except Exception:
            pass

        # Create stable artifacts for DAQ Runner handoff
        try:
            self._ensure_run_artifacts(out_path)
        except Exception:
            pass

        return out_path

    def _find_daq_runner_script(self) -> Optional[Path]:
        """Locate the DAQ runner script.

        Priority:
        1) session.paths.daq_runner_script
        2) self.var_daq_runner_script (if present)
        3) newest mole_daq_runner_*.py in same folder as this wizard
        """
        try:
            if _is_frozen_runtime():
                exe = self.base_dir / "MOLE_DAQ_Runner.exe"
                if exe.exists():
                    return exe
        except Exception:
            pass

        try:
            p = ((self.session.get("paths") or {}).get("daq_runner_script") or "").strip()
            if p:
                pp = _resolve_app_relative_path(p, base_dir=self.base_dir)
                if pp.exists():
                    return pp
        except Exception:
            pass

        try:
            v = getattr(self, "var_daq_runner_script", None)
            if v is not None:
                p = str(v.get() or "").strip()
                if p:
                    pp = _resolve_app_relative_path(p, base_dir=self.base_dir)
                    if pp.exists():
                        return pp
        except Exception:
            pass

        # Prefer a runner matching this wizard's version tag (avoid mismatched flag sets)
        try:
            here = self.base_dir
            m = re.search(r"(v\d+_\d+_\d+)", str(VERSION))
            vtag = m.group(1) if m else ""
            if vtag:
                cands = sorted(here.glob(f"mole_daq_runner_*{vtag}*.py"), key=lambda x: x.stat().st_mtime, reverse=True)
                if cands:
                    return cands[0]
        except Exception:
            pass

        try:
            here = self.base_dir
            cands = sorted(here.glob("mole_daq_runner_*.py"), key=lambda x: x.stat().st_mtime, reverse=True)
            if cands:
                return cands[0]
        except Exception:
            pass

        return None

    def _daq_runner_is_running(self) -> bool:
        p = getattr(self, "_daq_runner_proc", None)
        if p is None:
            return False
        try:
            return (p.poll() is None)
        except Exception:
            return False

    def _launch_daq_runner(self, cfg_path: Path, *, launch_mode: Optional[str] = None) -> None:
        """Launch DAQ Runner as a separate process (non-blocking).

        This uses the stable handoff artifacts:
         - session_profile.json
         - runner_config.json
         - deterministic daq_run_dir
        """
        if self._daq_runner_is_running():
            return

        # Ensure we have an applied session config to hand off
        cfg_p: Optional[Path] = None
        try:
            if cfg_path and Path(cfg_path).exists():
                cfg_p = Path(cfg_path)
        except Exception:
            cfg_p = None
        if cfg_p is None:
            cfg_p = self._ensure_applied_config_silent()
        if cfg_p is None:
            return

        action_scope = self._runner_launch_policy_scope(launch_mode)
        if action_scope == "DIAGNOSTICS":
            action_label = "DAQ Runner diagnostics launch"
        elif action_scope == "TRAINING":
            action_label = "DAQ Runner training launch"
        else:
            action_label = "DAQ Runner production/test launch"
        if not self._enforce_runtime_action_policy(action_label=action_label, action_scope=action_scope):
            return

        # Ensure deterministic artifacts exist
        try:
            self._ensure_run_artifacts(cfg_p)
        except Exception:
            pass

        runner = self._find_daq_runner_script()
        if not runner:
            try:
                messagebox.showerror(
                    "DAQ Runner",
                    "DAQ Runner script not found.\n\nPlace mole_daq_runner_*.py in this folder or set paths.daq_runner_script."
                )
            except Exception:
                pass
            return

        # Prefer runner_config/session_profile written into sessions/...
        pths = (self.session.get("paths") or {})
        runner_cfg_p = _resolve_app_relative_path(pths.get("runner_config_path"), base_dir=self.base_dir) if pths.get("runner_config_path") else cfg_p
        session_profile_p = _resolve_app_relative_path(pths.get("session_profile_path"), base_dir=self.base_dir) if pths.get("session_profile_path") else None
        outdir_p = _resolve_app_relative_path(pths.get("daq_run_dir"), base_dir=self.base_dir) if pths.get("daq_run_dir") else None
        launch_cfg_p = runner_cfg_p

        def _is_sim_driver_spec(spec: Any) -> bool:
            try:
                if isinstance(spec, str):
                    return spec.strip().upper().startswith("SIM")
                if isinstance(spec, dict):
                    for key in ("type", "name", "driver", "id"):
                        value = str(spec.get(key) or "").strip().upper()
                        if value.startswith("SIM") or value == "TRAINING":
                            return True
            except Exception:
                return False
            return False

        def _clear_diagnostics_launch_flags(doc: Dict[str, Any]) -> None:
            try:
                daq_runner_cfg = doc.get("daq_runner")
                if not isinstance(daq_runner_cfg, dict):
                    return
                daq_runner_cfg.pop("ui_mode", None)
                if daq_runner_cfg.get("report_pack_enabled") is False:
                    daq_runner_cfg.pop("report_pack_enabled", None)
            except Exception:
                pass

        try:
            lm = str(launch_mode or "").strip().upper()
            if lm in ("TEST", "PROD", "PRODUCTION") and runner_cfg_p and runner_cfg_p.exists():
                launch_cfg = json.loads(runner_cfg_p.read_text(encoding="utf-8"))
                _clear_diagnostics_launch_flags(launch_cfg)
                launch_cfg["environment"] = "PRODUCTION"
                if _is_sim_driver_spec(launch_cfg.get("daq_driver")):
                    launch_cfg.pop("daq_driver", None)
                daq = launch_cfg.get("daq")
                if isinstance(daq, dict) and _is_sim_driver_spec(daq.get("driver")):
                    daq.pop("driver", None)
                launch_cfg_p = runner_cfg_p.with_name(f"{runner_cfg_p.stem}_test_launch.json")
                write_json(launch_cfg_p, launch_cfg)
            elif lm in ("SIM", "TRAINING", "SIM_TRAINING", "SIMTRAINING") and runner_cfg_p and runner_cfg_p.exists():
                launch_cfg = json.loads(runner_cfg_p.read_text(encoding="utf-8"))
                _clear_diagnostics_launch_flags(launch_cfg)
                launch_cfg["environment"] = "TRAINING"
                launch_cfg_p = runner_cfg_p.with_name(f"{runner_cfg_p.stem}_sim_launch.json")
                write_json(launch_cfg_p, launch_cfg)
            elif lm in ("DIAG", "DIAGNOSTIC", "DIAGNOSTICS", "DIAG_TEST", "DIAG_SIM", "DIAG_TRAINING", "DIAGNOSTICS_SIM", "DIAGNOSTICS_TRAINING") and runner_cfg_p and runner_cfg_p.exists():
                launch_cfg = json.loads(runner_cfg_p.read_text(encoding="utf-8"))
                sm = launch_cfg.get("session_mode")
                if not isinstance(sm, dict):
                    sm = {}
                    launch_cfg["session_mode"] = sm
                sm["diagnostic_only"] = True
                sm["may_support_compliance"] = False
                sm["mode"] = "DIAGNOSTICS_SESSION"
                qa = launch_cfg.get("qa_qc")
                if not isinstance(qa, dict):
                    qa = {}
                    launch_cfg["qa_qc"] = qa
                qa["persist_cal_to_master_db"] = False
                daq = launch_cfg.get("daq_runner")
                if not isinstance(daq, dict):
                    daq = {}
                    launch_cfg["daq_runner"] = daq
                daq["ui_mode"] = "DIAGNOSTICS"
                daq["report_pack_enabled"] = False
                if lm in ("DIAG_SIM", "DIAG_TRAINING", "DIAGNOSTICS_SIM", "DIAGNOSTICS_TRAINING"):
                    launch_cfg["environment"] = "TRAINING"
                    sm["mode"] = "DIAGNOSTICS_TRAINING_SESSION"
                    launch_cfg_p = runner_cfg_p.with_name(f"{runner_cfg_p.stem}_diag_training_launch.json")
                else:
                    launch_cfg["environment"] = "PRODUCTION"
                    launch_cfg_p = runner_cfg_p.with_name(f"{runner_cfg_p.stem}_diag_launch.json")
                write_json(launch_cfg_p, launch_cfg)
        except Exception:
            launch_cfg_p = runner_cfg_p

        if str(runner).lower().endswith(".exe"):
            cmd = [str(runner), "--config", str(launch_cfg_p), "--ui"]
        else:
            cmd = [_python_gui_executable(), str(runner), "--config", str(launch_cfg_p), "--ui"]
        try:
            if session_profile_p and session_profile_p.exists():
                cmd += ["--session", str(session_profile_p)]
        except Exception:
            pass
        try:
            if outdir_p and outdir_p.exists():
                cmd += ["--outdir", str(outdir_p)]
        except Exception:
            pass

        # Log file
        try:
            safe_mkdir(self.logs_dir)
        except Exception:
            pass
        try:
            ts = datetime.now().astimezone().strftime("%Y%m%d_%H%M%S")
        except Exception:
            ts = "time"
        try:
            log_path = Path(self.logs_dir) / f"mole_daq_runner_{runner_cfg_p.stem}_{ts}.log"
        except Exception:
            log_path = self.base_dir / f"mole_daq_runner_{ts}.log"

        try:
            self._daq_runner_log_path = log_path
            lf = open(log_path, "w", encoding="utf-8")
        except Exception:
            lf = subprocess.DEVNULL  # type: ignore


        # TRAINING/TEST launch mode (functional separation)
        popen_env = None
        try:
            eff_env = None
            lm = str(launch_mode or "").strip().upper()
            if lm in ("SIM", "TRAINING", "SIM_TRAINING", "SIMTRAINING", "DIAG_SIM", "DIAG_TRAINING", "DIAGNOSTICS_SIM", "DIAGNOSTICS_TRAINING"):
                eff_env = "TRAINING"
            elif lm in ("TEST", "PROD", "PRODUCTION", "DIAG", "DIAGNOSTIC", "DIAGNOSTICS", "DIAG_TEST"):
                eff_env = "PRODUCTION"
            if eff_env is None:
                eff_env = _mole_env_mode()

            if eff_env == "TRAINING":
                popen_env = dict(os.environ)
                popen_env["MOLE_ENV"] = "TRAINING"
                # Make intent explicit (runner also enforces SIM_TRAINING in TRAINING env)
                if "--driver" not in cmd:
                    cmd += ["--driver", "SIM_TRAINING"]
            elif launch_mode is not None:
                # Explicit production launch (override any inherited TRAINING env)
                popen_env = dict(os.environ)
                popen_env["MOLE_ENV"] = "PRODUCTION"
        except Exception:
            popen_env = None

        try:
            self._daq_runner_proc = subprocess.Popen(
                cmd,
                cwd=str(self.base_dir),
                stdout=lf,
                stderr=subprocess.STDOUT,
                env=popen_env,
            )
        except Exception as e:
            try:
                messagebox.showerror("DAQ Runner", f"Failed to launch runner:\n\n{e}")
            except Exception:
                pass
            self._daq_runner_proc = None
            return

        try:
            self.lbl_run_status.configure(text=f"DAQ Runner: running (PID {self._daq_runner_proc.pid})", fg=self.FG)
        except Exception:
            pass

        try:
            self._update_run_status()
        except Exception:
            pass

        # Optional startup check dialog
        try:
            self.after(1500, self._check_daq_runner_startup)
        except Exception:
            pass

    def _maybe_autolaunch_daq_runner(self, launch_mode: Optional[str] = None) -> None:
        """Called when entering RUN tab to ensure runner is up."""
        try:
            auto = (self.session.get("run") or {}).get("auto_launch", True)
            if auto is False:
                return
        except Exception:
            pass

        cfg_p = None
        try:
            p = ((self.session.get("paths") or {}).get("session_config_path") or "").strip()
            if p:
                pp = Path(p)
                if pp.exists():
                    cfg_p = pp
        except Exception:
            pass

        if cfg_p is None:
            cfg_p = self._ensure_applied_config_silent()

        if cfg_p is None:
            return

        action_scope = self._runner_launch_policy_scope(launch_mode)
        action_label = "DAQ Runner production/test launch"
        if action_scope == "DIAGNOSTICS":
            action_label = "DAQ Runner diagnostics launch"
        elif action_scope == "TRAINING":
            action_label = "DAQ Runner training launch"
        policy = self._runtime_action_policy_record(action_label=action_label, action_scope=action_scope)
        if str(policy.get("decision") or "ALLOW").strip().upper() != "ALLOW":
            return

        self._launch_daq_runner(cfg_p, launch_mode=launch_mode)

    def _update_run_status(self) -> None:
        """Refresh the RUN tab status line if it exists."""
        lbl = getattr(self, "lbl_run_status", None)
        if lbl is None:
            return
        try:
            if self._daq_runner_is_running():
                pid = getattr(self._daq_runner_proc, "pid", None)
                lbl.config(text=f"DAQ Runner: RUNNING (PID {pid})")
            else:
                lbl.config(text="DAQ Runner: not running")
        except Exception:
            pass

    def _check_daq_runner_startup(self) -> None:
        """If the DAQ runner process exited immediately, show a useful error + log path."""
        p = getattr(self, "_daq_runner_proc", None)
        if p is None:
            return
        try:
            rc = p.poll()
        except Exception:
            return
        if rc is None:
            return

        log_p = str(getattr(self, "_daq_runner_log_path", "") or "").strip()
        msg = f"DAQ Runner exited during startup (exit code {rc})."
        if log_p:
            msg += f"\n\nStartup log:\n{log_p}"
        try:
            messagebox.showerror("DAQ Runner", msg)
        except Exception:
            pass


    def save_and_apply(self) -> None:
        self._sync_session_from_vars()
        try:
            self._tm_commit_plan_from_vars()
        except Exception:
            pass
        # Ensure deterministic binding before validation
        try:
            self._pollutants_resolve_and_bind()
        except Exception:
            pass

        self._ensure_test_matrix()
        err = self._validate_before_apply()
        if err:
            s = str(err)
            if s.startswith("Job Intake Checklist incomplete"):
                proceed = False
                try:
                    proceed = messagebox.askyesno(
                        "Job Intake Incomplete",
                        "Job Intake Checklist is incomplete.\n\n"
                        "To proceed with Simulation/Testing setup, you can save the config in NON-COMPLIANCE mode.\n\n"
                        "YES = disable 'May Support Compliance' for this session and save anyway.\n"
                        "NO  = return and complete the intake checklist.",
                    )
                except Exception:
                    proceed = False

                if not proceed:
                    messagebox.showerror("Save + Apply", err)
                    return

                try:
                    self.var_may_support_compliance.set(False)
                except Exception:
                    try:
                        sm = self.session.get("session_mode") or {}
                        sm["may_support_compliance"] = False
                        self.session["session_mode"] = sm
                    except Exception:
                        pass

                try:
                    self._sync_session_from_vars()
                except Exception:
                    pass

                err = self._validate_before_apply()
                if err:
                    messagebox.showerror("Save + Apply", err)
                    return
            elif s.startswith("AUTO_WEATHER"):
                messagebox.showerror("Save + Apply", err)
                try:
                    if messagebox.askyesno("Site Conditions", "Open Site Conditions now?"):
                        self.goto("SITE")
                except Exception:
                    pass
                return
            else:
                messagebox.showerror("Save + Apply", err)
                return

        job = self.session["project"]["job_id"]
        out_path = self.config_dir / f"mole_session_{job}.json"
        # --- equipment catalog auto-learn (master DB) ---
        try:
            self._catalog_learn_from_session()
        except Exception:
            pass

        self.session["meta"]["applied_iso"] = now_iso()
        self.session["meta"]["wizard_version"] = VERSION
        self.session = ensure_session_schema(self.session, actor="wizard_save_apply")
        self.session["paths"]["session_config_path"] = str(out_path)
        write_json(out_path, self.session)
        try:
            if write_recovery_snapshot is not None:
                write_recovery_snapshot(
                    self.session,
                    Path(self.backups_dir) / "session_recovery",
                    label=f"wizard_session_{job}",
                    keep=20,
                )
        except Exception:
            pass
        try:
            if backup_sqlite_database is not None:
                backup_sqlite_database(
                    Path(self.master_db_path),
                    Path(self.backups_dir) / "sqlite_master",
                    label="mole_master",
                    keep=10,
                )
        except Exception:
            pass
        try:
            self._record_wizard_health_event("SAVE_APPLY")
        except Exception:
            pass

        self.nav_enabled = True
        self._refresh_nav()
        messagebox.showinfo("Save + Apply", f"Config written:\n{out_path}")

    def _offer_startup_recovery(self) -> None:
        if latest_matching_path is None:
            return
        snap = latest_matching_path(Path(self.backups_dir) / "session_recovery", "wizard_session_*.json")
        if snap is None or (not snap.exists()):
            return
        try:
            created = datetime.fromtimestamp(snap.stat().st_mtime).astimezone().strftime("%Y-%m-%d %H:%M:%S")
        except Exception:
            created = snap.name
        live_cfg = mole_cfg_path(self.base_dir)
        try:
            live_updated = datetime.fromtimestamp(live_cfg.stat().st_mtime).astimezone().strftime("%Y-%m-%d %H:%M:%S") if live_cfg.exists() else "(none)"
        except Exception:
            live_updated = "(time unavailable)"
        latest_event = ""
        try:
            if load_latest_health_summary is not None:
                health = load_latest_health_summary(Path(self.logs_dir) / "health_journal", label="wizard_health")
                if health:
                    latest_event = (
                        f"Last journal event: {str(health.get('last_event') or '(n/a)')}"
                        f" @ {str(health.get('updated_utc') or '(time unavailable)')}"
                    )
        except Exception:
            latest_event = ""
        restore_choice = None
        try:
            restore_choice = messagebox.askyesnocancel(
                "Session Recovery",
                (
                    "A Wizard recovery snapshot is available.\n\n"
                    f"Current live config: {live_cfg.name}\n"
                    f"Current live updated: {live_updated}\n\n"
                    f"Snapshot: {snap.name}\n"
                    f"Updated: {created}\n\n"
                    + (latest_event + "\n\n" if latest_event else "")
                    + "YES = restore and open a pre-restore support bundle.\n"
                    + "NO = restore only.\n"
                    + "CANCEL = skip recovery."
                ),
                default="no",
            )
        except Exception:
            restore_choice = None
        restore_meta = None
        if restore_choice is True:
            try:
                bundle = self._create_wizard_support_bundle()
                self._dbpaths_open_path(str(bundle))
                restore_meta = {"bundle_created": True, "bundle_path": str(bundle)}
            except Exception:
                restore_meta = {"bundle_created": False, "bundle_path": ""}
            self.load_existing(str(snap), restore_meta=restore_meta)
        elif restore_choice is False:
            self.load_existing(str(snap), restore_meta={"bundle_created": False, "bundle_path": ""})

    def load_existing(self, fp: Optional[str] = None, restore_meta: Optional[Dict[str, Any]] = None) -> None:
        if not fp:
            fp = filedialog.askopenfilename(
                title="Select session config JSON",
                initialdir=str(self.config_dir),
                filetypes=[("JSON", "*.json"), ("All files", "*.*")]
            )
        if not fp:
            return
        try:
            loaded = read_json(Path(fp))
        except Exception as e:
            messagebox.showerror("Load Config", f"Failed to load JSON:\n{e}")
            return

        # Keep the loaded config as source of truth, but ensure top-level schema exists.
        if not isinstance(loaded, dict):
            messagebox.showerror("Load Config", "Invalid JSON (root must be an object).")
            return
        self.session = ensure_session_schema(loaded, actor="wizard_load")
        if isinstance(restore_meta, dict):
            try:
                meta = self.session.get("meta") if isinstance(self.session.get("meta"), dict) else {}
                meta["recovery_restore"] = {
                    "restored": True,
                    "snapshot_path": str(fp),
                    "restored_iso": now_iso(),
                    "bundle_created": bool(restore_meta.get("bundle_created")),
                    "bundle_path": str(restore_meta.get("bundle_path") or "").strip(),
                }
                self.session["meta"] = meta
                self._record_wizard_health_event("RECOVERY_RESTORE", dict(meta.get("recovery_restore") or {}))
            except Exception:
                pass

        # ---------------- project ----------------
        proj = self.session.get("project") or {}
        self.var_job_id.set(str(proj.get("job_id") or ""))
        self.var_project_name.set(str(proj.get("project_name") or ""))
        self.var_site_facility.set(str(proj.get("site_facility") or ""))
        self.var_operator.set(str(proj.get("operator") or ""))
        self.var_asset_unit_id.set(str(proj.get("asset_unit_id") or ""))

        # ---------------- session mode ----------------
        sm = self.session.get("session_mode") or {}
        self.var_record_data.set(bool(sm.get("record_data", True)))
        self.var_tokenize.set(bool(sm.get("tokenize", True)))
        self.var_diagnostic_only.set(bool(sm.get("diagnostic_only", False)))
        self.var_may_support_compliance.set(bool(sm.get("may_support_compliance", False)))
        self._apply_session_intent_policy(announce=False)
        try:
            self._validation_plan_load_vars_from_session()
        except Exception:
            pass

        # ---------------- job intake (QA routing) ----------------
        try:
            self._intake_load_vars_from_session()
        except Exception:
            pass

        # ---------------- source ----------------
        src = self.session.get("source") or {}
        self.var_source_category.set(str(src.get("source_category") or ""))
        self.var_source_application.set(str(src.get("application") or ""))
        self.var_service_class.set(str(src.get("service_class") or ""))
        self.var_output_type.set(str(src.get("output_type") or ""))
        self.var_manufacturer.set(str(src.get("manufacturer") or ""))
        self.var_model_number.set(str(src.get("model_number") or ""))
        self.var_serial_number.set(str(src.get("serial_number") or ""))
        self.var_asset_tag.set(str(src.get("asset_tag") or ""))
        self.var_engine_cyl_count.set("" if src.get("engine_cyl_count") is None else str(src.get("engine_cyl_count")))
        self.var_engine_cycle.set(str(src.get("engine_cycle") or "UNKNOWN").strip().upper() or "UNKNOWN")
        self.var_power_units.set(str(src.get("power_units") or "hp"))
        self.var_max_power.set("" if src.get("max_power") is None else str(src.get("max_power")))
        self.var_site_rated_power.set("" if src.get("site_rated_power") is None else str(src.get("site_rated_power")))
        self.var_estimated_power.set("" if src.get("estimated_power") is None else str(src.get("estimated_power")))
        self.var_load_basis.set(str(src.get("load_basis") or "SITE_RATED"))
        self.var_source_notes.set(str(src.get("notes") or ""))

        ff = src.get("fuel_flow") or {}
        self.var_fuel_flow_basis.set(str(ff.get("basis") or "UNSET"))
        self.var_fuel_flow_units.set(unit_token_to_display(str(ff.get("units") or "scfh")))
        self.var_fuel_flow_variation_pct.set("" if ff.get("variation_pct") is None else str(ff.get("variation_pct")))
        self.var_fuel_flow_ack.set(bool(ff.get("acknowledged", False)))

        # Exhaust flow determination
        ex = src.get("exhaust_flow") or {}
        method_code = str(ex.get("method") or "STOICH_FUEL")
        m_rev = {
            "STOICH_FUEL": "Stoichiometric via Fuel Input",
            "STACK_MEASURED": "Measured at Stack",
            "MANUFACTURER": "Manufacturer Inputs",
        }
        self.var_exh_method.set(m_rev.get(method_code, "Stoichiometric via Fuel Input"))

        sf = ex.get("stoich_fuel") or {}
        self.var_exh_stoich_fuel_flow.set("" if sf.get("fuel_flow_value") is None else str(sf.get("fuel_flow_value")))
        try:
            self.var_exh_stoich_defer.set(bool(sf.get("deferred", False)))
        except Exception:
            pass
        self.var_exh_stoich_units.set(unit_token_to_display(str(sf.get("fuel_flow_units") or "scfh")))
        self.var_exh_stoich_o2.set("" if sf.get("o2_dry_pct") is None else str(sf.get("o2_dry_pct")))

        sm2 = ex.get("stack_measured") or {}
        self.var_exh_stack_epa_method.set(str(sm2.get("epa_method") or "EPA_M2"))

        mf = ex.get("manufacturer") or {}
        basis_code = str(mf.get("basis") or "HEAT_INPUT")
        b_rev = {
            "HEAT_INPUT": "Heat Input (MMBtu/hr)",
            "HEAT_RATE": "Heat Rate (Btu/hp-hr)",
            "BSFC": "BSFC + LHV",
        }
        self.var_exh_mfr_basis.set(b_rev.get(basis_code, "Heat Input (MMBtu/hr)"))
        self.var_exh_mfr_o2.set("" if mf.get("o2_dry_pct") is None else str(mf.get("o2_dry_pct")))
        self.var_exh_mfr_heat_input.set("" if mf.get("heat_input_mmbtu_hr") is None else str(mf.get("heat_input_mmbtu_hr")))
        self.var_exh_mfr_rated_power.set("" if mf.get("rated_power_hp") is None else str(mf.get("rated_power_hp")))
        self.var_exh_mfr_load_frac.set("" if mf.get("load_fraction") is None else str(mf.get("load_fraction")))
        self.var_exh_mfr_heat_rate.set("" if mf.get("heat_rate_btu_hp_hr") is None else str(mf.get("heat_rate_btu_hp_hr")))
        self.var_exh_mfr_bsfc.set("" if mf.get("bsfc_lb_hp_hr") is None else str(mf.get("bsfc_lb_hp_hr")))
        self.var_exh_mfr_fuel_lhv.set("" if mf.get("fuel_lhv_btu_lb") is None else str(mf.get("fuel_lhv_btu_lb")))
        # Stack / duct geometry (EPA Method 1/2 support)
        st = src.get("stack") or {}
        self.var_stack_shape.set(str(st.get("shape") or "ROUND"))
        self.var_stack_diameter_in.set("" if st.get("diameter_in") is None else str(st.get("diameter_in")))
        self.var_stack_width_in.set("" if st.get("width_in") is None else str(st.get("width_in")))
        self.var_stack_height_in.set("" if st.get("height_in") is None else str(st.get("height_in")))
        self.var_stack_upstream_D.set("" if st.get("upstream_diameters") is None else str(st.get("upstream_diameters")))
        self.var_stack_downstream_D.set("" if st.get("downstream_diameters") is None else str(st.get("downstream_diameters")))
        self.var_stack_pitot_type.set(str(st.get("pitot_type") or "TYPE_S"))
        self.var_stack_pitot_cp.set("" if st.get("pitot_cp") is None else str(st.get("pitot_cp")))
        tpts = st.get("traverse_points_per_line")
        scheme = (st.get("traverse_scheme") or "").strip().upper()
        if scheme == "7E_3PT":
            self.var_stack_traverse_points_line.set("7E_3PT")
        else:
            self.var_stack_traverse_points_line.set("AUTO" if tpts in (None, "") else str(tpts))
        self.var_stack_wall_thickness_in.set("" if st.get("wall_thickness_in") is None else str(st.get("wall_thickness_in")))
        self.var_stack_port_count.set("" if st.get("port_count") is None else str(st.get("port_count")))
        angs = st.get("port_angles_deg") or []
        if isinstance(angs, (list, tuple)) and len(angs) >= 1:
            self.var_stack_port_angle1_deg.set(str(angs[0]))
        else:
            self.var_stack_port_angle1_deg.set("0")
        if isinstance(angs, (list, tuple)) and len(angs) >= 2:
            self.var_stack_port_angle2_deg.set(str(angs[1]))
        else:
            self.var_stack_port_angle2_deg.set("90")
        self.var_stack_port_diameter_in.set("" if st.get("port_diameter_in") is None else str(st.get("port_diameter_in")))
        self.var_stack_port_height_ft_agl.set("" if st.get("port_height_ft_agl") is None else str(st.get("port_height_ft_agl")))
        self.var_stack_height_ft_agl.set("" if st.get("stack_height_ft_agl") is None else str(st.get("stack_height_ft_agl")))
        self.var_stack_unstratified_7e.set(bool(st.get("unstratified_7e") or False))
        self.var_stack_hand_notes.set(str(st.get("hand_notes") or ""))
        try:
            txt = getattr(self, "_stack_hand_notes_text", None)
            if txt is not None:
                txt.delete("1.0", "end")
                txt.insert("1.0", self.var_stack_hand_notes.get())
        except Exception:
            pass

        # ---------------- fuel ----------------
        fuel = self.session.get("fuel") or {}
        self.var_fuel_category.set(str(fuel.get("fuel_category") or ""))
        self.var_capture_fuel_analysis.set(bool(fuel.get("capture_fuel_analysis", True)))
        fa = (fuel.get("analysis") or {})
        self.var_fuel_profile_id.set(str(fa.get("profile_id") or ""))
        self.var_fuel_analysis_confirm.set(bool(fa.get("captured", False)))
        self.var_fuel_analysis_notes.set(str(fa.get("notes") or ""))
        try:
            self._ensure_fuel_analysis_state()
        except Exception:
            pass

        # ---------------- QA/QC ----------------
        qa = self.session.get("qa_qc") or {}
        self.var_qaqc_method.set(str(qa.get("method_id", "PROFILE:DEFAULT")))
        self.var_qaqc_portable.set(bool(qa.get("portable_track", True)))
        self.var_qaqc_persist_cal_to_master_db.set(bool(qa.get("persist_cal_to_master_db", True)))
        self.var_diag_optin_cal_lin.set(bool(qa.get("diag_optin_cal_lin", False)))
        # Significant digits for numeric display
        try:
            sd = int(qa.get("significant_digits", DEFAULT_SIG_DIGITS))
        except Exception:
            sd = DEFAULT_SIG_DIGITS
        self.var_qaqc_sig_digits.set(str(sd))
        spike_cfg = normalize_spike_recovery_cfg(self.session.get("spike_recovery"), self.session.get("reference_audit"))
        self.var_spike_enabled.set(bool(spike_cfg.get("enabled")) and not bool(spike_cfg.get("mandatory")))
        self.var_spike_recovery_pct_min.set("" if spike_cfg.get("recovery_pct_min") is None else str(spike_cfg.get("recovery_pct_min")))
        self.var_spike_recovery_pct_max.set("" if spike_cfg.get("recovery_pct_max") is None else str(spike_cfg.get("recovery_pct_max")))
        self.var_spike_project_dqo_pct.set("" if spike_cfg.get("project_accuracy_dqo_pct") is None else str(spike_cfg.get("project_accuracy_dqo_pct")))
        self.var_spike_summary.set(str(spike_cfg.get("criterion_summary") or ""))
        self.var_spike_basis.set(str(spike_cfg.get("method_basis") or spike_cfg.get("notes") or ""))


        # ---------------- Pollutants (selection + active prescription) ----------------
        poll = self.session.get("pollutants") or {}
        if not isinstance(poll, dict):
            poll = {}
        self.session["pollutants"] = poll
        sel = set(poll.get("selected") or [])
        for code in self._pollutant_codes:
            try:
                self.var_pollutants[code].set(code in sel)
            except Exception:
                pass
        self._pollutants_ensure_prescriptions()
        self._pollutants_fix_active()
        self._pollutants_load_active_into_vars()
        try:
            self._pollutants_resolve_and_bind()
        except Exception:
            pass

        # ---------------- Site Conditions ----------------
        scn = self.session.get("site_conditions") or {}
        self.var_site_mode.set(str(scn.get("mode", "AUTO_WEATHER")))
        self.var_weather_fail.set(str(scn.get("on_weather_fail", "PROMPT")))
        self.var_z_model.set(_normalize_z_model(scn.get("z_model", "IDEAL")))
        self.var_fixed_z.set("" if scn.get("fixed_z") is None else str(scn.get("fixed_z")))
        std = scn.get("standard_conditions") or {}
        self.var_std_T.set(str(std.get("T_std_F", self._std_defaults["T_std_F"])))
        self.var_std_P.set(str(std.get("P_std_psia", self._std_defaults["P_std_psia"])))
        self.var_std_name.set(str(std.get("basis_name", self._std_defaults["basis_name"])))

        loc = scn.get("location") or {}
        self.var_site_lat.set("" if loc.get("lat") is None else str(loc.get("lat")))
        self.var_site_lon.set("" if loc.get("lon") is None else str(loc.get("lon")))
        self.var_site_elev_ft_msl.set("" if loc.get("elevation_ft_msl") is None else format_sig(loc.get("elevation_ft_msl")))

        wc = scn.get("weather_compile") or {}
        self.var_auto_weather_compile.set(bool(wc.get("enabled", False)))
        self.var_site_station_id.set("" if not wc.get("station_id") else str(wc.get("station_id")))
        lf = wc.get("last_fetch") or {}
        if lf:
            self.var_site_last_weather.set(f"T={lf.get('T_amb_F')}F  P={lf.get('P_bar_psia')}psia  RH={lf.get('RH_frac')}")
        else:
            self.var_site_last_weather.set("")

        me = scn.get("manual_entry") or {}
        self.var_manual_T.set("" if me.get("T_amb_F") is None else str(me.get("T_amb_F")))
        self.var_manual_P.set("" if me.get("P_bar_psia") is None else str(me.get("P_bar_psia")))
        self.var_manual_RH.set("" if me.get("RH_frac") is None else str(me.get("RH_frac")))

        ref_cfg = normalize_reference_audit_cfg((self.session.get("reference_audit") or ((self.session.get("daq_runner") or {}).get("reference_audit") or {})))
        self.session["reference_audit"] = dict(ref_cfg)
        self.var_ref_enabled.set(bool(ref_cfg.get("enabled")))
        self.var_ref_provider.set(str(ref_cfg.get("provider") or "MG2000_FTIR_PRN"))
        self.var_ref_role.set(str(ref_cfg.get("role") or "AUDIT"))
        self.var_ref_prn_path.set(str(ref_cfg.get("prn_path") or ""))
        self.var_ref_file_pattern.set(str(ref_cfg.get("file_pattern") or "*.prn"))
        self.var_ref_recursive.set(bool(ref_cfg.get("recursive")))
        try:
            self.var_ref_freshness_s.set(f"{float(ref_cfg.get('freshness_s') or 0.0):g}")
        except Exception:
            self.var_ref_freshness_s.set("120")
        self.var_ref_column_overrides.set(reference_mapping_dict_to_text(ref_cfg.get("column_overrides") or {}))
        self.var_ref_units_overrides.set(reference_mapping_dict_to_text(ref_cfg.get("units_overrides") or {}))

        # ---------------- Test Matrix ----------------
        self._ensure_test_matrix()

        self.nav_enabled = True
        self._refresh_nav()
        messagebox.showinfo("Load Config", "Loaded config and enabled navigation.")
        self.goto("PROJECT")


