    def export_current_tab_csv(self) -> None:
        """Export the currently-visible Wizard tab to CSV."""
        if mole_csv_export is None:
            messagebox.showerror('CSV Export', 'CSV export module missing (mole_csv_export_v1.py).')
            return
        out_dir = filedialog.askdirectory(title='Select export folder (Tab CSV)')
        if not out_dir:
            return
        try:
            res = mole_csv_export.export_wizard_state_csv(self.current_state or 'UNKNOWN', self.session or {}, out_dir)
            messagebox.showinfo('CSV Export', f'Exported {len(res.files)} file(s) to:\n{res.out_dir}')
        except Exception as e:
            messagebox.showerror('CSV Export', f'Export failed:\n{e}')

    def export_full_csv_pack(self) -> None:
        """Export a multi-CSV package (session snapshot + common tables + sqlite dumps)."""
        if mole_csv_export is None:
            messagebox.showerror('CSV Export', 'CSV export module missing (mole_csv_export_v1.py).')
            return
        out_dir = filedialog.askdirectory(title='Select export folder (Full CSV Pack)')
        if not out_dir:
            return
