# ------------------------- Method 1 diagram helpers -------------------------
try:
    import math

    def _m1_suggest_points_per_line(de_in: Optional[float]) -> int:
        """Suggest traverse points per line (EPA M1-ish heuristic) based on equivalent diameter."""
        try:
            if de_in is None:
                return 8
            d = float(de_in)
            if d <= 1.5:
                return 2
            if d <= 3.0:
                return 4
            if d <= 6.0:
                return 6
            if d <= 12.0:
                return 8
            if d <= 24.0:
                return 10
            return 12
        except Exception:
            return 8

    def _m1_fracs_full(n: int) -> List[float]:
        """
        Return full list of traverse point fractions-from-wall along the diameter/line.
        This mirrors the wizard preview logic: compute half via equal-area formula and mirror.
        """
        try:
            n = int(n)
        except Exception:
            return []
        if n < 4 or (n % 2) != 0:
            return []
        m = n // 2
        fr_half: List[float] = []
        for j in range(1, m + 1):
            try:
                fr = (1.0 - (1.0 - (j - 0.5) / m) ** 0.5) / 2.0
                fr_half.append(fr)
            except Exception:
                pass
        fr_full: List[float] = []
        for fr in fr_half:
            fr_full.append(fr)
        for fr in reversed(fr_half):
            fr_full.append(1.0 - fr)
        return fr_full

    def _stack_diagram_spec(self):
        """Collect current stack geometry + port fields for drawing/export."""
        shape = (self.var_stack_shape.get() or "ROUND").strip().upper()
        diam_in = float_or_none(getattr(self, "var_stack_diameter_in").get())
        w_in = float_or_none(getattr(self, "var_stack_width_in").get())
        h_in = float_or_none(getattr(self, "var_stack_height_in").get())

        if shape.startswith("ROUND"):
            de_in = diam_in
            area_in2 = (math.pi * (diam_in ** 2) / 4.0) if diam_in else None
        else:
            de_in = (2.0 * w_in * h_in / (w_in + h_in)) if (w_in and h_in and (w_in + h_in)) else None
            area_in2 = (w_in * h_in) if (w_in and h_in) else None

                # Traverse points per line
        tpts_raw = (self.var_stack_traverse_points_line.get() or "").strip().upper()
        scheme = "METHOD1"
        n = None
        if tpts_raw:
            if tpts_raw in ("7E_3PT", "7E-3PT", "RAKE3", "3PT_RAKE", "3PT"):
                scheme = "7E_3PT"
                n = 3
            elif tpts_raw not in ("AUTO",):
                n = int_or_none(tpts_raw, default=None)
                if n is not None:
                    scheme = "METHOD1_MANUAL"
        if n is None:
            n = _m1_suggest_points_per_line(de_in)
        if n is None or n <= 0:
            n = 8
# Port info
        port_count = int_or_none(getattr(self, "var_stack_port_count").get(), default=2)
        if port_count is None or port_count <= 0:
            port_count = 2
        angles = _stack_port_angles_from_vars(
            getattr(self, "var_stack_port_count").get(),
            getattr(self, "var_stack_port_angle1_deg").get(),
            getattr(self, "var_stack_port_angle2_deg").get(),
        )
        port_diam_in = float_or_none(getattr(self, "var_stack_port_diameter_in").get())
        port_h_ft = float_or_none(getattr(self, "var_stack_port_height_ft_agl").get())
        stack_h_ft = float_or_none(getattr(self, "var_stack_height_ft_agl").get())
        wall_t_in = float_or_none(getattr(self, "var_stack_wall_thickness_in").get())

        if scheme == "7E_3PT":
            fracs = [0.167, 0.500, 0.833]
        else:
            fracs = _m1_fracs_full(n)

        return {
            "shape": shape,
            "diam_in": diam_in,
            "w_in": w_in,
            "h_in": h_in,
            "de_in": de_in,
            "area_in2": area_in2,
            "n_points_line": n,
            "traverse_scheme": scheme,
            "fracs": fracs,
            "port_count": port_count,
            "port_angles_deg": angles,
            "port_diam_in": port_diam_in,
            "port_height_ft_agl": port_h_ft,
            "stack_height_ft_agl": stack_h_ft,
            "wall_thickness_in": wall_t_in,
        }

    def _diagram_build_commands(spec: dict, size: Tuple[int, int], style: str):
        """Return drawing commands for both Tk Canvas and PIL."""
        w_px, h_px = size
        style = (style or "ARCADE").strip().upper()

        if style == "PRINT":
            bg = "#ffffff"
            outline = "#000000"
            port_line = "#444444"
            pts = "#cc0000"
            txt = "#000000"
            accent = "#000000"
        else:
            bg = "#081018"
            outline = "#42ff7b"
            port_line = "#ff4fd8"
            pts = "#ffcc33"
            txt = "#e8f4ff"
            accent = "#8bd3ff"

        cmds: List[Tuple] = []

        # compute drawable region and shape pixels
        margin = 46
        cx = w_px / 2.0
        cy = h_px / 2.0 + 10  # small bias down to make room for header

        # determine pixel dims
        if spec.get("shape", "").startswith("ROUND") and spec.get("diam_in"):
            r = min(w_px, h_px - 40) / 2.0 - margin
            r = max(30, r)
            scale_in_to_px = (2.0 * r) / float(spec.get("diam_in") or 1.0)
            bbox = (cx - r, cy - r, cx + r, cy + r)
            shape_kind = "ROUND"
            dims_px = {"r": r, "bbox": bbox, "scale": scale_in_to_px}
        elif spec.get("w_in") and spec.get("h_in"):
            w_in = float(spec["w_in"])
            h_in = float(spec["h_in"])
            usable_w = max(10.0, (w_px - 2.0 * margin))
            usable_h = max(10.0, (h_px - 2.0 * margin) - 40.0)
            scale = min(usable_w / w_in, usable_h / h_in)
            rect_w = max(40.0, w_in * scale)
            rect_h = max(40.0, h_in * scale)
            bbox = (cx - rect_w / 2.0, cy - rect_h / 2.0, cx + rect_w / 2.0, cy + rect_h / 2.0)
            shape_kind = "RECT"
            dims_px = {"hw": rect_w / 2.0, "hh": rect_h / 2.0, "bbox": bbox, "scale": scale}
        else:
            # Not enough info to draw a shape yet
            return bg, cmds, {
                "bg": bg, "outline": outline, "port_line": port_line, "pts": pts, "txt": txt, "accent": accent
            }

        palette = {"bg": bg, "outline": outline, "port_line": port_line, "pts": pts, "txt": txt, "accent": accent}

        # boundary
        if shape_kind == "ROUND":
            cmds.append(("oval", dims_px["bbox"], outline, None, 3))
        else:
            cmds.append(("rect", dims_px["bbox"], outline, None, 3))

        # optional outer wall (visual aid)
        wt_in = spec.get("wall_thickness_in")
        try:
            wt_in = float(wt_in) if wt_in is not None else None
        except Exception:
            wt_in = None
        scale = dims_px.get("scale")
        if wt_in and scale:
            try:
                t_px = float(wt_in) * float(scale)
            except Exception:
                t_px = None
            if t_px and t_px > 0:
                b = dims_px["bbox"]
                outer_bbox = (b[0] - t_px, b[1] - t_px, b[2] + t_px, b[3] + t_px)
                wall_outline = "#888888" if style == "PRINT" else "#1b2b38"
                if shape_kind == "ROUND":
                    cmds.append(("oval", outer_bbox, wall_outline, None, 2))
                else:
                    cmds.append(("rect", outer_bbox, wall_outline, None, 2))

        # header block
        shape_lbl = "ROUND" if spec.get("shape", "").startswith("ROUND") else "RECT"
        dim_lbl = ""
        if shape_lbl == "ROUND":
            dim_lbl = f"ID Dia={spec.get('diam_in') or ''} in"
        else:
            dim_lbl = f"ID W x H={spec.get('w_in') or ''} x {spec.get('h_in') or ''} in"
        de_lbl = f"De={format_sig(spec.get('de_in'))} in" if isinstance(spec.get("de_in"), (int, float)) else "De=(n/a)"
        scheme = (spec.get("traverse_scheme") or "METHOD1").upper()
        scheme_lbl = ""
        if scheme == "7E_3PT":
            scheme_lbl = " (7E 8.2 3-pt rake)"
        n_lbl = f"{spec.get('n_points_line')} pts/line{scheme_lbl}"
        cmds.append(("text", (12, 10), f"STACK GEOMETRY (Method 1) - {shape_lbl}  {dim_lbl}  {de_lbl}  {n_lbl}", txt, "nw"))

        # port/height notes
        notes = []
        if spec.get("port_diam_in"):
            notes.append(f"Port Dia={format_sig(spec.get('port_diam_in'))} in")
        if spec.get("port_height_ft_agl"):
            notes.append(f"Port h={format_sig(spec.get('port_height_ft_agl'))} ft AGL")
        if spec.get("stack_height_ft_agl"):
            notes.append(f"Stack h={format_sig(spec.get('stack_height_ft_agl'))} ft AGL")
        if spec.get("wall_thickness_in"):
            notes.append(f"Wall t={format_sig(spec.get('wall_thickness_in'))} in")
        # optional OD calculation (visual aid)
        try:
            _wt = float(spec.get("wall_thickness_in")) if spec.get("wall_thickness_in") is not None else None
        except Exception:
            _wt = None
        if _wt and _wt > 0:
            try:
                if shape_lbl == "ROUND" and spec.get("diam_in"):
                    _od = float(spec.get("diam_in")) + 2.0 * _wt
                    notes.append(f"OD Dia={format_sig(_od)} in")
                elif shape_lbl != "ROUND" and spec.get("w_in") and spec.get("h_in"):
                    _odw = float(spec.get("w_in")) + 2.0 * _wt
                    _odh = float(spec.get("h_in")) + 2.0 * _wt
                    notes.append(f"OD W x H={format_sig(_odw)} x {format_sig(_odh)} in")
            except Exception:
                pass
        if notes:
            cmds.append(("text", (12, 30), " | ".join(notes), accent, "nw"))

        # ports + traverses
        angles = spec.get("port_angles_deg") or []
        fracs = spec.get("fracs") or []

        # safety: if no fracs computed, just show a center crosshair
        if not fracs:
            cmds.append(("line", (cx - 10, cy, cx + 10, cy), accent, 2))
            cmds.append(("line", (cx, cy - 10, cx, cy + 10), accent, 2))
            cmds.append(("text", (12, h_px - 24), "Enter stack dimensions + >=4 points/line to render traverse points.", txt, "nw"))
            return bg, cmds, palette

        # use only as many angles as port_count indicates
        port_count = spec.get("port_count") or len(angles) or 2
        angles = list(angles)[: int(port_count)]

        for k, ang in enumerate(angles, start=1):
            try:
                theta = math.radians(float(ang))
            except Exception:
                theta = math.radians(0.0)
            dx = math.cos(theta)
            dy = -math.sin(theta)  # canvas y goes downward

            # normalize
            norm = (dx * dx + dy * dy) ** 0.5
            if norm <= 0:
                continue
            dx /= norm
            dy /= norm

            # half length to boundary
            if shape_kind == "ROUND":
                half_len = dims_px["r"]
            else:
                hw = dims_px["hw"]
                hh = dims_px["hh"]
                tx = (hw / abs(dx)) if abs(dx) > 1e-9 else 1e12
                ty = (hh / abs(dy)) if abs(dy) > 1e-9 else 1e12
                half_len = min(tx, ty)

            x1, y1 = (cx - dx * half_len, cy - dy * half_len)
            x2, y2 = (cx + dx * half_len, cy + dy * half_len)

            cmds.append(("line", (x1, y1, x2, y2), port_line, 2))

            _r_hole = 0.0

            # draw port opening (visual aid) first so labels are not obscured
            if spec.get("port_diam_in") and dims_px.get("scale"):
                try:
                    _r_hole = max(3.0, (float(spec.get("port_diam_in")) / 2.0) * float(dims_px.get("scale")))
                    cmds.append(("oval", (x2 - _r_hole, y2 - _r_hole, x2 + _r_hole, y2 + _r_hole), accent, bg, 2))
                except Exception:
                    pass

            # label near port line end - offset tangentially to avoid clipping/overlap with port delineation
            try:
                tx, ty = (-dy, dx)  # tangent (90 deg rotated)

                # Include port-hole radius (if present) so the degree label never rides on top of the port marker.
                _r_hole_px = 0.0
                try:
                    _r_hole_px = float(_r_hole) if _r_hole is not None else 0.0
                except Exception:
                    _r_hole_px = 0.0

                # Radial + tangential offsets (pixels)
                pad_r = max(18.0, _r_hole_px + 10.0)
                tang = max(10.0, _r_hole_px + 6.0)
                label_r = half_len + pad_r

                lbl_x = cx + dx * label_r + tx * tang
                lbl_y = cy + dy * label_r + ty * tang

                # Anchor based on direction (keeps labels readable and reduces border clipping)
                if abs(dx) > abs(dy):
                    anchor = "w" if dx > 0 else "e"
                elif abs(dy) > abs(dx):
                    # IMPORTANT: vertical anchors are inverted to ensure labels render AWAY from the port marker.
                    anchor = "s" if dy < 0 else "n"
                else:
                    if dx > 0 and dy < 0:
                        anchor = "sw"
                    elif dx > 0 and dy > 0:
                        anchor = "nw"
                    elif dx < 0 and dy < 0:
                        anchor = "se"
                    else:
                        anchor = "ne"

                # Clamp within canvas border padding (do not use the geometry margin; labels may live in that margin).
                _m = 14
                lbl_x = max(_m, min(w_px - _m, lbl_x))
                lbl_y = max(_m, min(h_px - _m, lbl_y))

                cmds.append(("text", (lbl_x, lbl_y), f"P{k}@{format_sig(ang)} deg", accent, anchor))
            except Exception:
                pass

            # traverse points
            for fr in fracs:
                try:
                    fr = float(fr)
                except Exception:
                    continue
                t = (-half_len) + fr * (2.0 * half_len)
                px = cx + dx * t
                py = cy + dy * t
                r_pt = 4
                cmds.append(("oval", (px - r_pt, py - r_pt, px + r_pt, py + r_pt), pts, pts, 1))

        return bg, cmds, palette


    def _stack_side_spec(self) -> Dict[str, Any]:
        """Side-view spec extends top-down spec with upstream/downstream disturbance spacing (in diameters)."""
        try:
            base = self._stack_diagram_spec()
        except Exception:
            base = {}
        base = dict(base or {})

        def _f(x):
            try:
                if x is None:
                    return None
                x = str(x).strip()
                if not x:
                    return None
                return float(x)
            except Exception:
                return None

        up_var = getattr(self, "var_stack_upstream_D", None)
        dn_var = getattr(self, "var_stack_downstream_D", None)
        base["upstream_D"] = _f(up_var.get()) if up_var is not None else None
        base["downstream_D"] = _f(dn_var.get()) if dn_var is not None else None
        return base

    def _diagram_build_side_commands(spec: Dict[str, Any], size: Tuple[int, int], style: str):
        """Build drawing commands for a stack *side view* (grade -> stack top), with plane/port height + disturbances."""
        w_px, h_px = size
        style = (style or "ARCADE").upper()

        if style == "PRINT":
            bg = "#ffffff"
            panel = "#ffffff"
            outline = "#111111"
            grid = "#777777"
            port_line = "#111111"
            txt = "#111111"
            accent = "#0a5"
            warn = "#b00020"
        else:
            bg = "#0b1320"
            panel = "#0f1720"
            outline = "#1b2a3a"
            grid = "#243447"
            port_line = "#00ff84"
            txt = "#cfe8ff"
            accent = "#ffb000"
            warn = "#ff6a00"

        palette = {
            "bg": bg,
            "panel": panel,
            "outline": outline,
            "grid": grid,
            "port_line": port_line,
            "txt": txt,
            "accent": accent,
            "warn": warn,
        }

        def _f(v):
            try:
                if v is None:
                    return None
                return float(v)
            except Exception:
                return None

        stack_h_ft = _f(spec.get("stack_height_ft_agl"))
        port_h_ft = _f(spec.get("port_height_ft_agl"))
        de_in = _f(spec.get("de_in"))

        upstream_D = _f(spec.get("upstream_D"))
        downstream_D = _f(spec.get("downstream_D"))

        de_ft = (de_in / 12.0) if (de_in is not None and de_in > 0) else None
        up_ft = (upstream_D * de_ft) if (upstream_D is not None and de_ft is not None) else None
        dn_ft = (downstream_D * de_ft) if (downstream_D is not None and de_ft is not None) else None

        # Pick a sane scaling height even if the operator hasn't filled everything in yet.
        eff_stack_h = stack_h_ft if (stack_h_ft is not None and stack_h_ft > 0) else None
        if eff_stack_h is None:
            candidates = []
            if port_h_ft is not None and port_h_ft > 0:
                candidates.append(port_h_ft + 5.0)
                candidates.append(port_h_ft * 1.15)
                if dn_ft is not None:
                    candidates.append(port_h_ft + dn_ft + 5.0)
            if up_ft is not None and dn_ft is not None:
                candidates.append(up_ft + dn_ft + 10.0)
            eff_stack_h = max(candidates + [30.0])

        eff_port_h = port_h_ft if (port_h_ft is not None and port_h_ft >= 0) else (eff_stack_h * 0.60)
        eff_port_h = min(max(eff_port_h, 0.0), eff_stack_h)

        # Canvas geometry
        top_m = 18
        bot_m = 44
        left_m = 18
        right_m = 18

        ground_y = h_px - bot_m
        top_y = top_m
        usable_h = max(10, ground_y - top_y)
        px_per_ft = usable_h / eff_stack_h if eff_stack_h > 0 else 10.0

        def y_of(h_ft: float) -> float:
            return ground_y - (h_ft * px_per_ft)

        y_stack_top = y_of(eff_stack_h)
        y_plane = y_of(eff_port_h)

        stack_w = min(190.0, max(120.0, w_px * 0.40))
        # Center the stack in the usable bay (leave a gutter on right for labels)
        bay_left = left_m + 42.0
        bay_right = w_px - right_m
        x0 = (bay_left + bay_right) * 0.5 - stack_w * 0.5
        x1 = x0 + stack_w

        cmds = []

        # Ground line
        cmds.append(("line", (left_m, ground_y, w_px - right_m, ground_y), grid, 2))
        cmds.append(("text", (left_m, ground_y - 16), "GRADE", txt, ("Consolas", 10, "bold"), "nw"))

        # Stack body
        cmds.append(("rect", (x0, y_stack_top, x1, ground_y), outline, panel, 2))

        # Flow arrow (assume upward)
        ax = x0 - 24
        ay0 = ground_y - 10
        ay1 = y_stack_top + 16
        cmds.append(("line", (ax, ay0, ax, ay1), accent, 2))
        cmds.append(("line", (ax, ay1, ax - 6, ay1 + 10), accent, 2))
        cmds.append(("line", (ax, ay1, ax + 6, ay1 + 10), accent, 2))
        cmds.append(("text", (ax - 2, ay1 - 18), "FLOW", txt, ("Consolas", 9, "bold"), "ne"))

        # Stack height label
        if stack_h_ft is not None and stack_h_ft > 0:
            cmds.append(("text", (x0, y_stack_top - 16), f"Stack h = {format_sig(stack_h_ft)} ft AGL", txt, ("Consolas", 10, "normal"), "nw"))
        else:
            cmds.append(("text", (x0, y_stack_top - 16), "Stack h (AGL) not set", warn if style != "PRINT" else txt, ("Consolas", 10, "normal"), "nw"))

        # Measurement plane / port height
        cmds.append(("line", (x0, y_plane, x1, y_plane), port_line, 2))
        if port_h_ft is not None and port_h_ft >= 0:
            cmds.append(("text", (x0 + 6, y_plane - 14), f"Plane/Port @ {format_sig(port_h_ft)} ft AGL", txt, ("Consolas", 10, "bold"), "nw"))
        else:
            cmds.append(("text", (x0 + 6, y_plane - 14), "Plane/Port height (AGL) not set", warn if style != "PRINT" else txt, ("Consolas", 10, "bold"), "nw"))

        # Port marker (right side)
        cmds.append(("oval", (x1 - 6, y_plane - 6, x1 + 6, y_plane + 6), port_line, panel, 2))
        cmds.append(("line", (x1 + 6, y_plane, x1 + 28, y_plane), port_line, 2))

        # Disturbance markers (using upstream/downstream straight runs in diameters)
        if de_ft is not None and de_ft > 0:
            # upstream disturbance (below plane)
            if up_ft is not None and up_ft > 0:
                h_up = eff_port_h - up_ft
                up_note = ""
                if h_up < 0:
                    h_up = 0.0
                    up_note = " (below grade)"
                y_up = y_of(h_up)
                cmds.append(("line", (x0, y_up, x1, y_up), warn, 1))
                cmds.append(("text", (x1 + 10, y_up - 8), f"Upstream disturbance:\n{format_sig(upstream_D)}D = {format_sig(up_ft)} ft{up_note}", txt, ("Consolas", 9, "normal"), "w"))

            # downstream disturbance (above plane)
            if dn_ft is not None and dn_ft > 0:
                h_dn = eff_port_h + dn_ft
                dn_note = ""
                if h_dn > eff_stack_h:
                    h_dn = eff_stack_h
                    dn_note = " (above stack top)"
                y_dn = y_of(h_dn)
                cmds.append(("line", (x0, y_dn, x1, y_dn), warn, 1))
                cmds.append(("text", (x1 + 10, y_dn - 8), f"Downstream disturbance:\n{format_sig(downstream_D)}D = {format_sig(dn_ft)} ft{dn_note}", txt, ("Consolas", 9, "normal"), "w"))

            note_y = min(h_px - 22, ground_y + 10)
            note_x = left_m + 52
            cmds.append(("text", (note_x, note_y), f"De = {format_sig(de_in)} in  (1D = {format_sig(de_ft)} ft)", txt, ("Consolas", 9, "normal"), "nw"))
        else:
            note_y = min(h_px - 22, ground_y + 10)
            note_x = left_m + 52
            cmds.append(("text", (note_x, note_y), "De not available (set duct diameter/width/height)", warn if style != "PRINT" else txt, ("Consolas", 9, "normal"), "nw"))

        return bg, cmds, palette


    def _render_commands_to_canvas(canvas: tk.Canvas, bg: str, cmds: List[Tuple]):
        """Render simple vector commands onto a Tk canvas.

        Command formats supported:
         - ('oval', (x0,y0,x1,y1), outline, fill, width)
         - ('rect', (x0,y0,x1,y1), outline, fill, width)
         - ('line', (x0,y0,x1,y1,...), color, width)
         - ('text', (x,y), text, color, anchor)  # default font
         - ('text', (x,y), text, color, font, anchor)  # optional font
        """
        canvas.delete("all")
        try:
            canvas.configure(bg=bg)
        except Exception:
            pass

        for cmd in cmds:
            if not cmd:
                continue
            kind = cmd[0]
            if kind == "oval":
                try:
                    _, bbox, outline, fill, width = cmd
                except Exception:
                    continue
                canvas.create_oval(*bbox, outline=outline, fill=fill, width=width)
            elif kind == "rect":
                try:
                    _, bbox, outline, fill, width = cmd
                except Exception:
                    continue
                canvas.create_rectangle(*bbox, outline=outline, fill=fill, width=width)
            elif kind == "line":
                try:
                    _, pts, color, width = cmd
                except Exception:
                    continue
                canvas.create_line(*pts, fill=color, width=width)
            elif kind == "text":
                # Support both 5-tuple and 6-tuple text commands (optional font).
                try:
                    xy = cmd[1]
                    txt = cmd[2]
                    color = cmd[3]
                except Exception:
                    continue
                anchor = cmd[-1] if len(cmd) >= 5 else "nw"
                font = ("Consolas", 10)
                if len(cmd) >= 6:
                    try:
                        font = cmd[4] or font
                    except Exception:
                        pass
                try:
                    canvas.create_text(*xy, text=txt, fill=color, anchor=anchor, font=font)
                except Exception:
                    # If font tuple is invalid on this platform, fall back.
                    try:
                        canvas.create_text(*xy, text=txt, fill=color, anchor=anchor)
                    except Exception:
                        pass

    def _render_commands_to_pil(bg: str, cmds: List[Tuple], size: Tuple[int, int]):
        """Render the same command list to a PIL image (for PNG export)."""
        from PIL import Image, ImageDraw, ImageFont  # noqa

        img = Image.new("RGB", size, bg)
        draw = ImageDraw.Draw(img)

        try:
            font = ImageFont.load_default()
        except Exception:
            font = None

        for cmd in cmds:
            if not cmd:
                continue
            kind = cmd[0]
            if kind == "oval":
                try:
                    _, bbox, outline, fill, width = cmd
                except Exception:
                    continue
                draw.ellipse(bbox, outline=outline, fill=fill, width=int(width))
            elif kind == "rect":
                try:
                    _, bbox, outline, fill, width = cmd
                except Exception:
                    continue
                draw.rectangle(bbox, outline=outline, fill=fill, width=int(width))
            elif kind == "line":
                try:
                    _, pts, color, width = cmd
                except Exception:
                    continue
                draw.line(pts, fill=color, width=int(width))
            elif kind == "text":
                # Accept either:
                #   ('text', (x,y), text, color, anchor)
                #   ('text', (x,y), text, color, font, anchor)
                try:
                    xy = cmd[1]
                    txt = cmd[2]
                    color = cmd[3]
                except Exception:
                    continue
                draw.text(xy, txt, fill=color, font=font)
        return img

    def _redraw_stack_diagram(self, style: Optional[str] = None):
        """Redraw the stack/ports diagram on the Source Details tab (safe no-op if not present)."""
        canvas = getattr(self, "_stack_diag_canvas", None)
        if canvas is None:
            return
        try:
            spec = self._stack_diagram_spec()
        except Exception:
            return
        if style is None:
            try:
                style = getattr(self, "var_stack_diagram_style").get()
            except Exception:
                style = "ARCADE"
        try:
            w_px = max(200, int(canvas.winfo_width()))
            h_px = max(120, int(canvas.winfo_height()))
        except Exception:
            w_px, h_px = (560, 280)
        bg, cmds, _pal = _diagram_build_commands(spec, (w_px, h_px), style)
        _render_commands_to_canvas(canvas, bg, cmds)



    def _redraw_stack_side_diagram(self):
        c = getattr(self, "_stack_side_canvas", None)
        if c is None:
            return
        try:
            w = max(int(c.winfo_width()), 120)
            h = max(int(c.winfo_height()), 120)
            spec = self._stack_side_spec() if hasattr(self, "_stack_side_spec") else {}
            style = (spec.get("style") or "ARCADE")
            bg, cmds, palette = _diagram_build_side_commands(spec, (w, h), style)
            try:
                c.configure(bg=bg)
            except Exception:
                pass
            _render_commands_to_canvas(c, bg, cmds)
        except Exception:
            try:
                c.delete("all")
            except Exception:
                pass

    def _export_stack_side_diagram_png(self, style: str = "PRINT"):
        """Export side-view diagram to PNG (printable or arcade style)."""
        try:
            from PIL import Image, ImageDraw, ImageFont  # noqa: F401
        except Exception:
            messagebox.showerror("Diagram Export", "PNG export requires Pillow (PIL).")
            return

        spec = self._stack_side_spec() if hasattr(self, "_stack_side_spec") else {}
        export_size = (1200, 720)
        bg, cmds, palette = _diagram_build_side_commands(spec, export_size, style)
        img = _render_commands_to_pil(bg, cmds, export_size)

        default_name = f"mole_method1_side_view_{style.strip().lower()}.png"
        path = filedialog.asksaveasfilename(
            title="Save Method 1 Side View (PNG)",
            defaultextension=".png",
            initialfile=default_name,
            filetypes=[("PNG Image", "*.png")],
        )
        if not path:
            return
        try:
            img.save(path, format="PNG")
        except Exception as e:
            messagebox.showerror("Diagram Export", f"Failed to save diagram:\n{e}")
            return

        try:
            messagebox.showinfo("Diagram Export", f"Saved diagram:\n{path}")
        except Exception:
            pass

    def _export_stack_diagram_png(self, style: str = "PRINT"):
        """Export the Method 1 diagram as a PNG file."""
        from tkinter import filedialog, messagebox  # noqa

        try:
            spec = self._stack_diagram_spec()
        except Exception:
            spec = None
        if not spec:
            messagebox.showwarning("Diagram Export", "Stack diagram is not ready. Enter stack geometry first.")
            return

        export_size = (1400, 800)
        bg, cmds, _pal = _diagram_build_commands(spec, export_size, style)

        try:
            img = _render_commands_to_pil(bg, cmds, export_size)
        except Exception as e:
            messagebox.showwarning("Diagram Export", f"Could not render PNG (PIL missing). Error: {e}")
            return

        default_name = f"mole_method1_stack_diagram_{style.strip().lower()}.png"
        path = filedialog.asksaveasfilename(
            title="Save Method 1 Diagram (PNG)",
            defaultextension=".png",
            initialfile=default_name,
            filetypes=[("PNG Image", "*.png")],
        )
        if not path:
            return
        try:
            img.save(path, format="PNG")
        except Exception as e:
            messagebox.showerror("Diagram Export", f"Failed to save diagram:\n{e}")
            return

        try:
            messagebox.showinfo("Diagram Export", f"Saved diagram:\n{path}")
        except Exception:
            pass

    MoleDASWizard._stack_diagram_spec = _stack_diagram_spec
    MoleDASWizard._redraw_stack_diagram = _redraw_stack_diagram
    MoleDASWizard._export_stack_diagram_png = _export_stack_diagram_png

    MoleDASWizard._stack_side_spec = _stack_side_spec
    MoleDASWizard._redraw_stack_side_diagram = _redraw_stack_side_diagram
    MoleDASWizard._export_stack_side_diagram_png = _export_stack_side_diagram_png

except Exception:
    pass



