# ------------------------- catalog governance (v10.0.2) -------------------------

def _build_catalog_governance(self) -> None:
    """In-app Catalog Governance Reviewer (Pending Queue + Synonyms + Merge Tools)."""
    repo = None
    try:
        repo = self._catalog_repo()
    except Exception:
        repo = None

    outer = tk.Frame(self.center, bg=self.BG)
    outer.pack(fill="both", expand=True)

    header = tk.Frame(outer, bg=self.BG)
    header.pack(fill="x", padx=12, pady=(12, 6))

    tk.Label(
        header,
        text="CATALOG GOVERNANCE",
        fg=self.ACCENT,
        bg=self.BG,
        font=("Consolas", 16, "bold"),
    ).pack(side="left")

    # Reviewer identity (for audit log)
    default_actor = (
        (self.session.get("project") or {}).get("operator")
        or os.environ.get("USERNAME")
        or os.environ.get("USER")
        or "operator"
    )
    var_actor = tk.StringVar(value=str(default_actor))

    actor_frame = tk.Frame(header, bg=self.BG)
    actor_frame.pack(side="right")
    tk.Label(actor_frame, text="Reviewer:", fg=self.FG, bg=self.BG, font=("Consolas", 9)).pack(side="left")
    tk.Entry(actor_frame, textvariable=var_actor, width=22, bg="white", fg="black").pack(side="left", padx=(6, 0))

    # Status / counts
    counts_var = tk.StringVar(value="")
    tk.Label(
        outer,
        textvariable=counts_var,
        fg="#9fb0c0",
        bg=self.BG,
        justify="left",
        font=("Consolas", 9),
    ).pack(fill="x", padx=12)

    def _audit(action: str, subject_type: str = "", subject_id: Optional[int] = None, details: Optional[dict] = None) -> None:
        """Best-effort audit: DB table (if present) + JSONL in logs/."""
        actor = (var_actor.get() or "").strip() or "operator"
        payload = {
            "created_at": now_iso(),
            "actor": actor,
            "action": action,
            "subject_type": subject_type or None,
            "subject_id": subject_id,
            "details": details or {},
        }

        # 1) DB audit table (schema v3)
        try:
            if repo is not None and hasattr(repo, "audit_log"):
                repo.audit_log(actor=actor, action=action, subject_type=subject_type, subject_id=subject_id, details=details or {})
        except Exception:
            pass

        # 2) JSONL file in logs folder
        try:
            log_dir = getattr(self, "logs_dir", None)
            if log_dir is None:
                log_dir = Path(self.base_dir) / ".." / "mole_das_data" / "logs"
            log_dir = Path(log_dir)
            log_dir.mkdir(parents=True, exist_ok=True)
            p = log_dir / "catalog_governance_audit.jsonl"
            with p.open("a", encoding="utf-8") as f:
                f.write(json.dumps(payload, ensure_ascii=False) + "\n")
        except Exception:
            pass

    def _refresh_counts() -> None:
        try:
            if repo is None:
                counts_var.set("Master Catalog: not available")
                return
            c = repo.catalog_counts()
            dbp = getattr(self, "master_db_path", "")
            counts_var.set(
                f"DB: {dbp}\n"
                f"MFR: {c.get('manufacturers', 0)}  MODELS: {c.get('models', 0)}  VARIANTS: {c.get('variants', 0)}  "
                f"INST: {c.get('instances', 0)}  PENDING: {c.get('pending', 0)}  SYN: {c.get('synonyms', 0)}"
            )
        except Exception:
            counts_var.set("Master Catalog: error reading counts")

    if repo is None:
        _refresh_counts()
        tk.Label(
            outer,
            text="Master catalog repo not found. Ensure mole_master_db_repo_v1.py is present in /code and a master DB path is configured.",
            fg=self.FG,
            bg=self.BG,
            wraplength=860,
            justify="left",
        ).pack(fill="x", padx=12, pady=(12, 0))
        return

    _refresh_counts()

    nb = ttk.Notebook(outer)
    nb.pack(fill="both", expand=True, padx=12, pady=12)

    # ------------------------- TAB: Pending Queue -------------------------

    tab_pending = tk.Frame(nb, bg=self.BG)
    nb.add(tab_pending, text="Pending Queue")

    filter_row = tk.Frame(tab_pending, bg=self.BG)
    filter_row.pack(fill="x", pady=(0, 8))

    var_cat = tk.StringVar(value="(all)")
    var_search = tk.StringVar(value="")
    var_limit = tk.StringVar(value="250")

    def _pending_categories() -> list[str]:
        try:
            cur = repo.con.cursor()
            cur.execute(
                "SELECT DISTINCT source_category FROM catalog_pending ORDER BY source_category COLLATE NOCASE ASC"
            )
            cats = [str(r[0]) for r in cur.fetchall() if r and r[0]]
            return ["(all)"] + cats
        except Exception:
            return ["(all)"]

    tk.Label(filter_row, text="Category:", fg=self.FG, bg=self.BG).pack(side="left")
    cmb_cat = ttk.Combobox(filter_row, textvariable=var_cat, values=_pending_categories(), width=22, state="readonly")
    cmb_cat.pack(side="left", padx=(6, 12))

    tk.Label(filter_row, text="Search:", fg=self.FG, bg=self.BG).pack(side="left")
    tk.Entry(filter_row, textvariable=var_search, width=28, bg="white", fg="black").pack(side="left", padx=(6, 12))

    tk.Label(filter_row, text="Limit:", fg=self.FG, bg=self.BG).pack(side="left")
    tk.Entry(filter_row, textvariable=var_limit, width=7, bg="white", fg="black").pack(side="left", padx=(6, 12))

    btn_refresh_pending = tk.Button(filter_row, text="Refresh", bg=self.BTN_BG, fg=self.BTN_FG, relief="flat")
    btn_refresh_pending.pack(side="left", padx=(0, 8))

    btn_refresh_counts = tk.Button(filter_row, text="Counts", bg=self.BTN_BG2, fg=self.BTN_FG, relief="flat", command=_refresh_counts)
    btn_refresh_counts.pack(side="left")

    pan = tk.PanedWindow(tab_pending, orient="horizontal", bg=self.BG, sashrelief="flat")
    pan.pack(fill="both", expand=True)

    left = tk.Frame(pan, bg=self.BG)
    right = tk.Frame(pan, bg=self.BG)
    pan.add(left, stretch="always")
    pan.add(right, minsize=340)

    cols = ("pending_id", "source_category", "manufacturer", "model_number", "reason", "created_at")
    tree = ttk.Treeview(left, columns=cols, show="headings", height=18)
    for c in cols:
        tree.heading(c, text=c)
        # sensible widths
        w = 90
        if c in {"manufacturer", "model_number"}:
            w = 160
        if c == "reason":
            w = 210
        if c == "created_at":
            w = 160
        tree.column(c, width=w, anchor="w")

    vsb = ttk.Scrollbar(left, orient="vertical", command=tree.yview)
    tree.configure(yscrollcommand=vsb.set)
    tree.pack(side="left", fill="both", expand=True)
    vsb.pack(side="right", fill="y")

    selected_pending: Optional[dict] = None

    # Details (right pane)
    tk.Label(right, text="Selection", fg=self.ACCENT, bg=self.BG, font=("Consolas", 12, "bold")).pack(anchor="w")

    detail_txt = tk.Text(right, height=10, bg="#0b0f14", fg="#cfe2ff", insertbackground="#cfe2ff", wrap="word")
    detail_txt.pack(fill="x", pady=(6, 8))

    # Merge/Resolve controls
    tk.Label(right, text="Resolve to Existing Model (Merge)", fg=self.ACCENT, bg=self.BG, font=("Consolas", 11, "bold")).pack(anchor="w", pady=(8, 4))

    var_can_mfr = tk.StringVar(value="")
    var_can_model = tk.StringVar(value="")
    var_syn_mfr = tk.BooleanVar(value=True)
    var_syn_model = tk.BooleanVar(value=True)
    var_reject_reason = tk.StringVar(value="")

    mfr_row = tk.Frame(right, bg=self.BG)
    mfr_row.pack(fill="x", pady=2)
    tk.Label(mfr_row, text="Canon MFR:", fg=self.FG, bg=self.BG, width=11, anchor="w").pack(side="left")
    cmb_can_mfr = ttk.Combobox(mfr_row, textvariable=var_can_mfr, values=[], width=26)
    cmb_can_mfr.pack(side="left", fill="x", expand=True)

    model_row = tk.Frame(right, bg=self.BG)
    model_row.pack(fill="x", pady=2)
    tk.Label(model_row, text="Canon Model:", fg=self.FG, bg=self.BG, width=11, anchor="w").pack(side="left")
    cmb_can_model = ttk.Combobox(model_row, textvariable=var_can_model, values=[], width=26)
    cmb_can_model.pack(side="left", fill="x", expand=True)

    syn_row = tk.Frame(right, bg=self.BG)
    syn_row.pack(fill="x", pady=(6, 2))
    tk.Checkbutton(syn_row, text="Add MFR synonym", variable=var_syn_mfr, bg=self.BG, fg=self.FG, selectcolor=self.BG).pack(side="left")
    tk.Checkbutton(syn_row, text="Add model synonym", variable=var_syn_model, bg=self.BG, fg=self.FG, selectcolor=self.BG).pack(side="left", padx=(12, 0))

    btn_row = tk.Frame(right, bg=self.BG)
    btn_row.pack(fill="x", pady=(6, 2))

    btn_approve = tk.Button(btn_row, text="Approve (New Canon)", bg=self.BTN_BG, fg=self.BTN_FG, relief="flat")
    btn_merge = tk.Button(btn_row, text="Merge -> Canon", bg=self.BTN_BG2, fg=self.BTN_FG, relief="flat")
    btn_approve.pack(side="left", fill="x", expand=True)
    btn_merge.pack(side="left", fill="x", expand=True, padx=(8, 0))

    rej_row = tk.Frame(right, bg=self.BG)
    rej_row.pack(fill="x", pady=(10, 2))
    tk.Label(rej_row, text="Reject reason:", fg=self.FG, bg=self.BG, anchor="w").pack(anchor="w")
    tk.Entry(rej_row, textvariable=var_reject_reason, bg="white", fg="black").pack(fill="x", pady=(4, 4))
    btn_reject = tk.Button(rej_row, text="Reject Pending", bg="#7a2222", fg="white", relief="flat")
    btn_reject.pack(fill="x")

    # Mapping from model display string -> model_id
    model_display_to_id: dict[str, int] = {}

    def _parse_model_id(display: str) -> Optional[int]:
        try:
            return int(model_display_to_id.get(display) or 0) or None
        except Exception:
            return None

    def _load_models_for_selected_mfr() -> None:
        model_display_to_id.clear()
        var_can_model.set("")
        vals: list[str] = []
        if not selected_pending:
            cmb_can_model["values"] = vals
            return
        cat = str(selected_pending.get("source_category") or "Other")
        mfr_name = (var_can_mfr.get() or "").strip()
        if not mfr_name:
            cmb_can_model["values"] = vals
            return
        try:
            mfr_id = repo._manufacturer_id_by_name(mfr_name)
        except Exception:
            mfr_id = None
        if not mfr_id:
            cmb_can_model["values"] = vals
            return

        try:
            rows = repo.list_models_full(source_category=cat, manufacturer_id=int(mfr_id), limit=250)
        except Exception:
            rows = []
        for r in rows:
            disp = f"[{r.get('model_id')}] {r.get('model_number')}  (use:{r.get('usage_count')})"
            vals.append(disp)
            try:
                model_display_to_id[disp] = int(r.get('model_id'))
            except Exception:
                pass

        cmb_can_model["values"] = vals
        if vals:
            var_can_model.set(vals[0])

    def _update_detail_view(pend: Optional[dict]) -> None:
        detail_txt.configure(state="normal")
        detail_txt.delete("1.0", "end")
        if not pend:
            detail_txt.insert("end", "Select a pending row to review.\n")
        else:
            detail_txt.insert(
                "end",
                f"Pending ID: {pend.get('pending_id')}\n"
                f"Category: {pend.get('source_category')}\n"
                f"Manufacturer: {pend.get('manufacturer')}\n"
                f"Model: {pend.get('model_number')}\n"
                f"Reason: {pend.get('reason') or ''}\n"
                f"Created: {pend.get('created_at')}\n\n"
            )
            # Variant preview
            detail_txt.insert(
                "end",
                "Variant fields:\n"
                f"  engine_cycle: {pend.get('engine_cycle')}\n"
                f"  engine_cyl_count: {pend.get('engine_cyl_count')}\n"
                f"  duty: {pend.get('duty_value')} {pend.get('duty_unit')}\n"
            )
        detail_txt.configure(state="disabled")

    def _refresh_pending() -> None:
        nonlocal selected_pending
        try:
            # update category list too
            cmb_cat["values"] = _pending_categories()
            if var_cat.get() not in cmb_cat["values"]:
                var_cat.set("(all)")

            cat = var_cat.get()
            if cat == "(all)":
                cat = ""
            try:
                lim = int((var_limit.get() or "250").strip())
            except Exception:
                lim = 250

            rows = repo.list_pending(limit=lim, source_category=cat, text=var_search.get())
        except Exception as e:
            rows = []
            messagebox.showerror("Pending Queue", f"Failed to load pending queue:\n{e}")

        tree.delete(*tree.get_children())
        for r in rows:
            pid = r.get("pending_id")
            vals = (
                r.get("pending_id"),
                r.get("source_category"),
                r.get("manufacturer"),
                r.get("model_number"),
                r.get("reason"),
                r.get("created_at"),
            )
            try:
                tree.insert("", "end", iid=str(pid), values=vals)
            except Exception:
                tree.insert("", "end", values=vals)

        selected_pending = None
        _update_detail_view(None)
        var_can_mfr.set("")
        var_can_model.set("")
        cmb_can_mfr["values"] = []
        cmb_can_model["values"] = []
        _refresh_counts()

    def _on_tree_select(_evt=None) -> None:
        nonlocal selected_pending
        sel = tree.selection()
        if not sel:
            return
        pid = None
        try:
            pid = int(sel[0])
        except Exception:
            try:
                pid = int(tree.item(sel[0]).get("values")[0])
            except Exception:
                pid = None
        if not pid:
            return
        try:
            selected_pending = repo.get_pending(int(pid))
        except Exception:
            selected_pending = None
        _update_detail_view(selected_pending)

        # populate canonical manufacturer suggestions
        vals = []
        if selected_pending:
            try:
                vals = repo.suggest_manufacturers(prefix=str(selected_pending.get("manufacturer") or ""), limit=25)
            except Exception:
                vals = []
        cmb_can_mfr["values"] = vals
        if vals:
            var_can_mfr.set(vals[0])
        else:
            var_can_mfr.set("")

        _load_models_for_selected_mfr()

    tree.bind("<<TreeviewSelect>>", _on_tree_select)
    cmb_can_mfr.bind("<<ComboboxSelected>>", lambda _e: _load_models_for_selected_mfr())

    def _do_approve() -> None:
        if not selected_pending:
            return
        pid = int(selected_pending.get("pending_id"))
        try:
            res = repo.approve_pending(pid)
        except Exception as e:
            messagebox.showerror("Approve", f"Approve failed:\n{e}")
            return
        _audit("PENDING_APPROVE", "pending", pid, {"result": res, "pending": selected_pending})
        messagebox.showinfo("Approve", f"Approved pending #{pid} -> model_id={res.get('model_id')}")
        _refresh_pending()

    def _do_merge() -> None:
        if not selected_pending:
            return
        pid = int(selected_pending.get("pending_id"))
        mid = _parse_model_id(var_can_model.get())
        if not mid:
            messagebox.showwarning("Merge", "Select a canonical model first.")
            return
        try:
            res = repo.resolve_pending_to_model(
                pending_id=pid,
                canonical_model_id=int(mid),
                add_manufacturer_synonym=bool(var_syn_mfr.get()),
                add_model_synonym=bool(var_syn_model.get()),
            )
        except Exception as e:
            messagebox.showerror("Merge", f"Merge failed:\n{e}")
            return
        _audit("PENDING_MERGE", "pending", pid, {"canonical_model_id": int(mid), "result": res, "pending": selected_pending})
        messagebox.showinfo("Merge", f"Merged pending #{pid} -> model_id={mid}")
        _refresh_pending()

    def _do_reject() -> None:
        if not selected_pending:
            return
        pid = int(selected_pending.get("pending_id"))
        reason = (var_reject_reason.get() or "").strip()
        try:
            res = repo.reject_pending(pid)
        except Exception as e:
            messagebox.showerror("Reject", f"Reject failed:\n{e}")
            return
        _audit("PENDING_REJECT", "pending", pid, {"reason": reason, "result": res, "pending": selected_pending})
        messagebox.showinfo("Reject", f"Rejected pending #{pid}.")
        var_reject_reason.set("")
        _refresh_pending()

    btn_refresh_pending.configure(command=_refresh_pending)
    btn_approve.configure(command=_do_approve)
    btn_merge.configure(command=_do_merge)
    btn_reject.configure(command=_do_reject)

