    def _load_models_for_mfr(mfr_name: str, cat: str = "") -> None:
        model_display_to_id2.clear()
        vals: list[str] = []
        try:
            mfr_id = repo._manufacturer_id_by_name(mfr_name)
        except Exception:
            mfr_id = None
        if not mfr_id:
            cmb_new_model["values"] = vals
            return
        try:
            rows = repo.list_models_full(source_category=(cat or None), manufacturer_id=int(mfr_id), limit=500)
        except Exception:
            rows = []
        for r in rows:
            disp = f"[{r.get('model_id')}] {r.get('source_category')} | {r.get('model_number')} (use:{r.get('usage_count')})"
            vals.append(disp)
            try:
                model_display_to_id2[disp] = int(r.get('model_id'))
            except Exception:
                pass
        cmb_new_model["values"] = vals
        if vals:
            var_new_canon_model.set(vals[0])

