def _qaqc_db_connect(self):
    """Return a sqlite3 connection to the master DB (best-effort)."""
    try:
        import sqlite3
        dbp = getattr(self, "master_db_path", None)
        if not dbp:
            return None
        return sqlite3.connect(str(dbp))
    except Exception:
        return None


def _qaqc_distinct_values(self, field: str, limit: int = 200) -> list:
    conn = _qaqc_db_connect(self)
    if conn is None:
        return []
    try:
        cur = conn.cursor()
        cur.execute(f"SELECT DISTINCT {field} FROM qaqc_cal_event WHERE {field} IS NOT NULL AND TRIM({field})<>'' ORDER BY {field} LIMIT alpha", (int(limit),))
        vals = []
        for (v,) in cur.fetchall() or []:
            if v is None:
                continue
            vals.append(str(v))
        return vals
    except Exception:
        return []
    finally:
        try:
            conn.close()
        except Exception:
            pass


