    flow_readout_id = None  # will be assigned by _draw_schematic()
    sample_icon_root = self.base_dir.parent / "figures" / "sample_system_assets"
    sample_viz_state["icon_cache"] = {}

    def _get_sample_icon(name: str, max_px: int) -> Optional[tk.PhotoImage]:
        key = (str(name or "").strip().lower(), max(24, int(max_px or 0)))
        cache = sample_viz_state.get("icon_cache") or {}
        try:
            if key in cache:
                return cache[key]
        except Exception:
            pass
        path = sample_icon_root / f"{key[0]}.png"
        if not path.exists():
            return None
        try:
            icon = tk.PhotoImage(file=str(path))
            w = max(1, int(icon.width()))
            h = max(1, int(icon.height()))
            factor = max(1, int(math.ceil(max(w, h) / float(key[1]))))
            if factor > 1:
                icon = icon.subsample(factor, factor)
            cache[key] = icon
            sample_viz_state["icon_cache"] = cache
            return icon
        except Exception:
            return None

    def _mix_hex(c1: str, c2: str, t: float) -> str:
        try:
            t = max(0.0, min(1.0, float(t)))
            c1 = str(c1 or "#000000").lstrip("#")
            c2 = str(c2 or "#000000").lstrip("#")
            if len(c1) != 6 or len(c2) != 6:
                return "#" + (c2 if len(c2) == 6 else c1 if len(c1) == 6 else "000000")
            r1, g1, b1 = int(c1[0:2], 16), int(c1[2:4], 16), int(c1[4:6], 16)
            r2, g2, b2 = int(c2[0:2], 16), int(c2[2:4], 16), int(c2[4:6], 16)
            r = int(r1 + (r2 - r1) * t)
            g = int(g1 + (g2 - g1) * t)
            b = int(b1 + (b2 - b1) * t)
            return f"#{r:02x}{g:02x}{b:02x}"
        except Exception:
            return str(c2 or c1 or "#000000")

    def _status_palette(status: str, phase: float = 0.0) -> dict[str, str]:
        token = str(status or "").strip().upper()
        pulse = 0.5 + 0.5 * math.sin(float(phase))
        if token == "OK":
            glow = _mix_hex("#123318", "#66ff66", 0.45 + 0.30 * pulse)
            return {"outline": _mix_hex("#20482a", "#8aff8a", 0.35 + 0.30 * pulse), "fill": "#0c1410", "glow": glow, "text": "#dfffe6"}
        if token == "WARN":
            glow = _mix_hex("#3d2a08", "#ffcc33", 0.45 + 0.25 * pulse)
            return {"outline": _mix_hex("#5b410d", "#ffd866", 0.35 + 0.25 * pulse), "fill": "#151108", "glow": glow, "text": "#fff2c4"}
        if token == "ALARM":
            glow = _mix_hex("#3a0913", "#ff3355", 0.45 + 0.25 * pulse)
            return {"outline": _mix_hex("#5d1121", "#ff6681", 0.35 + 0.25 * pulse), "fill": "#17090c", "glow": glow, "text": "#ffd7df"}
        return {"outline": "#2a3d55", "fill": "#0a0f16", "glow": "#11202c", "text": "#c7d0d9"}

    def _draw_glow_rect(x0: float, y0: float, x1: float, y1: float, *, fill: str, outline: str, glow: str, width: int = 2) -> int:
        try:
            canvas.create_rectangle(x0 - 5, y0 - 5, x1 + 5, y1 + 5, outline=_mix_hex("#060b10", glow, 0.35), width=6)
            canvas.create_rectangle(x0 - 2, y0 - 2, x1 + 2, y1 + 2, outline=_mix_hex("#060b10", glow, 0.55), width=3)
        except Exception:
            pass
        return int(canvas.create_rectangle(x0, y0, x1, y1, outline=outline, width=width, fill=fill))

    def _draw_glow_circle(cx: float, cy: float, r: float, *, fill: str, outline: str, glow: str, width: int = 2) -> int:
        try:
            canvas.create_oval(cx - r - 4, cy - r - 4, cx + r + 4, cy + r + 4, outline=_mix_hex("#060b10", glow, 0.35), width=5)
            canvas.create_oval(cx - r - 2, cy - r - 2, cx + r + 2, cy + r + 2, outline=_mix_hex("#060b10", glow, 0.55), width=3)
        except Exception:
            pass
        return int(canvas.create_oval(cx - r, cy - r, cx + r, cy + r, outline=outline, width=width, fill=fill))

    def _draw_glow_line(points: list[tuple[float, float]], color: str, *, width: int = 3, dash: Optional[tuple[int, int]] = None, arrow: Optional[str] = None) -> None:
        flat: list[float] = []
        for px, py in points:
            flat.extend((px, py))
        kwargs: dict[str, Any] = {
            "smooth": True,
            "capstyle": "round",
            "joinstyle": "round",
        }
        if dash:
            kwargs["dash"] = dash
        if arrow:
            kwargs["arrow"] = arrow
        try:
            canvas.create_line(*flat, fill=_mix_hex("#060b10", color, 0.28), width=width + 5, **kwargs)
            canvas.create_line(*flat, fill=_mix_hex("#060b10", color, 0.50), width=width + 2, **kwargs)
        except Exception:
            pass
        canvas.create_line(*flat, fill=color, width=width, **kwargs)

    def _draw_knockout_icon(cx: float, cy: float, color: str, phase: float, enabled: bool) -> None:
        glow = _mix_hex("#0a2540", color, 0.72)
        _draw_glow_circle(cx, cy, 36 + (2.0 * math.sin(phase * 1.4) if enabled else 0.0), fill="#081522", outline=glow, glow=glow, width=2)
        img = _get_sample_icon("water_knockout", 86)
        if img is not None:
            canvas.create_image(cx, cy - 2, image=img)
        else:
            body = _mix_hex("#060b10", glow, 0.55)
            canvas.create_polygon(cx, cy - 16, cx - 12, cy + 8, cx, cy + 20, cx + 12, cy + 8, outline=glow, fill="", width=2, smooth=True)
            canvas.create_line(cx, cy - 20, cx, cy - 30, fill=body, width=2)
            canvas.create_line(cx - 18, cy - 2, cx - 10, cy - 2, fill=body, width=2, arrow="first")
            canvas.create_line(cx + 10, cy - 2, cx + 18, cy - 2, fill=body, width=2, arrow="last")
            canvas.create_line(cx, cy + 20, cx, cy + 30, fill=body, width=2)
        if enabled:
            for idx in range(3):
                frac = ((phase * 0.22) + (idx * 0.21)) % 1.0
                drop_y = cy + 26 + frac * 24
                drop_x = cx + ((idx - 1) * 8 if idx else 0)
                r = 3.0 if idx == 1 else 2.5
                _draw_glow_circle(drop_x, drop_y, r, fill=glow, outline=glow, glow=glow, width=1)

    def _draw_filter_icon(cx: float, cy: float, color: str, phase: float) -> None:
        glow = _mix_hex("#214a11", color, 0.90)
        _draw_glow_circle(cx, cy, 38 + 1.8 * math.sin(phase), fill="#0f180d", outline=glow, glow=glow, width=3)
        try:
            canvas.create_oval(cx - 46, cy - 46, cx + 46, cy + 46, outline=_mix_hex("#060b10", glow, 0.68), width=2)
        except Exception:
            pass
        img = _get_sample_icon("particulate_filter", 86)
        if img is not None:
            canvas.create_image(cx, cy, image=img)
        canvas.create_polygon(
            cx - 16, cy - 10,
            cx + 16, cy - 18,
            cx + 16, cy + 18,
            cx - 16, cy + 10,
            outline=glow,
            fill="",
            width=2,
        )
        for off in (-10, -2, 6, 14):
            canvas.create_line(cx - 9, cy + off - 7, cx + 7, cy + off - 11, fill=glow, width=2)
        for idx in range(4):
            dot_x = cx - 42 + idx * 7 + math.sin(phase + idx) * 1.6
            dot_y = cy - 14 + idx * 8
            _draw_glow_circle(dot_x, dot_y, 1.7, fill=glow, outline=glow, glow=glow, width=1)

    def _draw_valve_icon(cx: float, cy: float, color: str) -> None:
        glow = _mix_hex("#1b1b1b", color, 0.70)
        _draw_glow_circle(cx, cy, 30, fill="#141516", outline=glow, glow=glow, width=2)
        img = _get_sample_icon("valve", 82)
        if img is not None:
            canvas.create_image(cx, cy, image=img)
        else:
            _draw_glow_circle(cx, cy, 14, fill="#0b1720", outline=glow, glow=glow, width=2)
            canvas.create_line(cx - 24, cy, cx - 12, cy, fill=glow, width=3)
            canvas.create_line(cx + 12, cy, cx + 24, cy, fill=glow, width=3)
            canvas.create_line(cx, cy - 12, cx, cy - 26, fill=glow, width=3)

    def _draw_pump_icon(cx: float, cy: float, color: str, phase: float) -> None:
        glow = _mix_hex("#18320f", color, 0.82)
        _draw_glow_circle(cx, cy, 38 + 1.5 * math.sin(phase * 1.1), fill="#10170f", outline=glow, glow=glow, width=2)
        img = _get_sample_icon("sample_pump", 96)
        if img is not None:
            canvas.create_image(cx, cy, image=img)
        else:
            wheel = _mix_hex("#060b10", glow, 0.60)
            _draw_glow_circle(cx, cy, 16, fill="#0b1720", outline=glow, glow=glow, width=2)
            _draw_glow_circle(cx, cy, 5, fill=wheel, outline=glow, glow=glow, width=2)
            for ang in (phase, phase + 2.1, phase + 4.2):
                x2 = cx + math.cos(ang) * 11
                y2 = cy + math.sin(ang) * 11
                canvas.create_line(cx, cy, x2, y2, fill=glow, width=2)
        wheel_cy = cy + 16
        wheel_r = 8
        spin = (phase * 1.8) if bool(sample_viz_state.get("anim_enabled")) else 0.0
        _draw_glow_circle(cx, wheel_cy, wheel_r + 1.5, fill="#0b1720", outline=glow, glow=glow, width=1)
        _draw_glow_circle(cx, wheel_cy, 2.5, fill=glow, outline=glow, glow=glow, width=1)
        for ang in (spin, spin + math.pi / 2.0, spin + math.pi, spin + (3.0 * math.pi / 2.0)):
            x2 = cx + math.cos(ang) * wheel_r
            y2 = wheel_cy + math.sin(ang) * wheel_r
            canvas.create_line(cx, wheel_cy, x2, y2, fill=glow, width=1.5)

    def _draw_flowmeter_icon(cx: float, cy: float, color: str, max_px: int = 76) -> None:
        glow = _mix_hex("#2b2b2b", color, 0.58)
        _draw_glow_circle(cx, cy, max_px * 0.34, fill="#121416", outline=glow, glow=glow, width=2)
        img = _get_sample_icon("flowmeter", max_px)
        if img is not None:
            canvas.create_image(cx, cy, image=img)
        else:
            _draw_glow_rect(cx - 18, cy - 12, cx + 18, cy + 12, fill="#121416", outline=glow, glow=glow, width=2)

    def _draw_chip_icon(cx: float, cy: float, color: str, phase: float = 0.0, enabled: bool = False) -> None:
        pulse = (0.5 + 0.5 * math.sin(phase * 1.35)) if enabled else 0.0
        outline = _mix_hex(color, "#ffd06a", 0.12 + (0.28 * pulse))
        glow = _mix_hex("#060b10", outline, 0.55 + (0.18 * pulse))
        fill = _mix_hex("#11161d", "#2a1706", 0.08 + (0.22 * pulse))
        core = _mix_hex("#3d2308", "#ffc65d", 0.30 + (0.24 * pulse))
        _draw_glow_rect(cx - 12, cy - 12, cx + 12, cy + 12, fill=fill, outline=outline, glow=glow, width=2)
        canvas.create_rectangle(cx - 6, cy - 6, cx + 6, cy + 6, outline=core, width=2)
        for off in (-10, -4, 4, 10):
            canvas.create_line(cx - 16, cy + off, cx - 12, cy + off, fill=outline, width=2)
            canvas.create_line(cx + 12, cy + off, cx + 16, cy + off, fill=outline, width=2)
            canvas.create_line(cx + off, cy - 16, cx + off, cy - 12, fill=outline, width=2)
            canvas.create_line(cx + off, cy + 12, cx + off, cy + 16, fill=outline, width=2)

    def _draw_monitor_icon(cx: float, cy: float, color: str, phase: float = 0.0, enabled: bool = False) -> None:
        pulse = (0.5 + 0.5 * math.sin(phase * 1.10)) if enabled else 0.0
        crt = _mix_hex("#2f5a2f", "#8cff8c", 0.55 + (0.18 * pulse))
        shell = _mix_hex("#101824", color, 0.32 + (0.18 * pulse))
        glow = _mix_hex("#060b10", color, 0.55 + (0.18 * pulse))
        fill = _mix_hex("#091018", "#10202b", 0.12 + (0.16 * pulse))
        _draw_glow_rect(cx - 38, cy - 26, cx + 38, cy + 16, fill=fill, outline=shell, glow=glow, width=2)
        canvas.create_rectangle(cx - 28, cy - 16, cx + 28, cy + 2, outline=crt, width=2, fill="#06140a")
        canvas.create_line(cx - 24, cy - 7, cx + 24, cy - 7, fill=_mix_hex("#0a1b0e", crt, 0.55), width=1)
        canvas.create_line(cx - 10, cy + 16, cx + 10, cy + 16, fill=glow, width=3)
        canvas.create_line(cx, cy + 12, cx, cy + 18, fill=glow, width=2)
        canvas.create_polygon(
            cx - 30, cy + 24,
            cx + 30, cy + 24,
            cx + 24, cy + 34,
            cx - 24, cy + 34,
            outline=shell,
            fill="#0a121a",
            width=2,
        )
        canvas.create_line(cx - 18, cy + 28, cx + 18, cy + 28, fill=crt, width=1)

    def _draw_label_box(cx: float, cy: float, text: str, *, width: int = 104, height: int = 36, outline: str = "#c7d0d9", fill: str = "#10161d", fg: str = "#dfe7ef") -> None:
        _draw_glow_rect(cx - width / 2, cy - height / 2, cx + width / 2, cy + height / 2, fill=fill, outline=outline, glow=_mix_hex("#060b10", outline, 0.45), width=1)
        canvas.create_text(cx, cy, text=text, fill=fg, font=("Consolas", 8, "bold"), justify="center")

    def _draw_text_plate(
        x: float,
        y: float,
        text: str,
        *,
        anchor: str = "center",
        font: tuple = ("Consolas", 8, "bold"),
        fill: str = "#dfe7ef",
        bg: str = "#0f161d",
        outline: str = "#2a3d55",
        pad_x: int = 6,
        pad_y: int = 3,
    ) -> Optional[int]:
        tid = canvas.create_text(x, y, text=text, anchor=anchor, fill=fill, font=font, justify="center")
        try:
            bbox = canvas.bbox(tid)
            if bbox:
                rid = canvas.create_rectangle(
                    bbox[0] - pad_x,
                    bbox[1] - pad_y,
                    bbox[2] + pad_x,
                    bbox[3] + pad_y,
                    fill=bg,
                    outline=outline,
                    width=1,
                )
                canvas.tag_lower(rid, tid)
        except Exception:
            pass
        return int(tid)

    def _draw_canister(cx: float, cy: float, label_lines: list[str], *, fill: str, outline: str) -> None:
        lines = [str(line or "") for line in (label_lines or []) if str(line or "").strip()]
        max_chars = max((len(line) for line in lines), default=8)
        w = max(76, min(118, 22 + max_chars * 6))
        h = max(102, 48 + len(lines) * 20)
        _draw_glow_rect(cx - w / 2, cy - h / 2 + 8, cx + w / 2, cy + h / 2 - 6, fill=fill, outline=outline, glow=outline, width=2)
        canvas.create_oval(cx - w / 2, cy - h / 2, cx + w / 2, cy - h / 2 + 16, fill=_mix_hex(fill, "#ffffff", 0.15), outline=outline, width=2)
        canvas.create_oval(cx - w / 2, cy + h / 2 - 16, cx + w / 2, cy + h / 2, fill=fill, outline=outline, width=2)
        base_y = cy - ((max(1, len(lines)) - 1) * 10)
        text_fill = "#223117" if fill.lower() != "#142018" else "#dfffe6"
        for idx, line in enumerate(lines):
            canvas.create_text(
                cx,
                base_y + idx * 20,
                text=line,
                fill=text_fill,
                font=("Consolas", 10 if idx == 0 else 9, "bold" if idx == 0 else "normal"),
                justify="center",
            )

    def _draw_chevrons(x: float, y: float, color: str, phase: float) -> None:
        offset = (phase * 7.0) % 22.0
        for idx in range(3):
            cx = x + idx * 22 - offset
            pts = [cx - 10, y, cx, y - 10, cx + 10, y, cx, y + 10]
            canvas.create_polygon(*pts, fill="#f4f6f8", outline="#202020", width=1)

    def _polyline_point(points: list[tuple[float, float]], frac: float) -> tuple[float, float]:
        if not points:
            return (0.0, 0.0)
        if len(points) == 1:
            return points[0]
        frac = frac % 1.0
        lengths: list[float] = []
        total = 0.0
        for idx in range(len(points) - 1):
            x0, y0 = points[idx]
            x1, y1 = points[idx + 1]
            seg = math.hypot(x1 - x0, y1 - y0)
            lengths.append(seg)
            total += seg
        if total <= 0:
            return points[-1]
        target = frac * total
        acc = 0.0
        for idx, seg in enumerate(lengths):
            if acc + seg >= target:
                x0, y0 = points[idx]
                x1, y1 = points[idx + 1]
                local = 0.0 if seg <= 0 else (target - acc) / seg
                return (x0 + (x1 - x0) * local, y0 + (y1 - y0) * local)
            acc += seg
        return points[-1]

    def _draw_flow_particles(points: list[tuple[float, float]], color: str, phase: float, *, count: int, radius: float = 3.0) -> None:
        for idx in range(max(0, int(count))):
            frac = ((phase * 0.085) + (idx / max(1, count))) % 1.0
            px, py = _polyline_point(points, frac)
            _draw_glow_circle(px, py, radius, fill=color, outline=color, glow=color, width=1)

    def _sample_slot_snapshot(cell_idx: int, slot_idx: int) -> dict[str, str]:
        try:
            ui_slots = (gas_ui[cell_idx].get("slots") or []) if cell_idx < len(gas_ui) else []
            ui = ui_slots[slot_idx] if slot_idx < len(ui_slots) and isinstance(ui_slots[slot_idx], dict) else {}
            channel_id = str((ui.get("var_channel") or tk.StringVar()).get() or "").strip()
            if channel_id == "(unset)":
                channel_id = ""
            gas_label = str((ui.get("var_gas") or tk.StringVar()).get() or "").strip()
        except Exception:
            channel_id = ""
            gas_label = ""
        label = (gas_label or channel_id or "--").replace("_", " ").strip()
        if len(label) > 9:
            label = label[:8] + "+"
        state = "UNMAPPED"
        try:
            if channel_id:
                state = str((sample_viz_state.get("channel_comm") or {}).get(channel_id) or "UNKNOWN").upper()
        except Exception:
            state = "UNKNOWN"
        return {
            "channel_id": channel_id,
            "label": label.upper(),
            "state": state,
        }

    def _sync_anim_button() -> None:
        enabled = bool(sample_viz_state.get("anim_enabled"))
        ss["animate_live"] = enabled
        try:
            btn_animate.configure(
                bg=(self.ACCENT if enabled else self.BTN_BG2),
                fg=("black" if enabled else self.BTN_FG),
                relief=("sunken" if enabled else "flat"),
            )
        except Exception:
            pass
        var_anim_status.set("Animation: LIVE" if enabled else "Animation: OFF")

    def _toggle_animate() -> None:
        sample_viz_state["anim_enabled"] = not bool(sample_viz_state.get("anim_enabled"))
        _sync_anim_button()
        try:
            _draw_schematic()
        except Exception:
            pass

    btn_animate.configure(command=_toggle_animate)
    _sync_anim_button()

    def _block(x: int, y: int, w: int, h: int, label: str, key: str, *, status: str = "UNKNOWN", font: tuple = ("Consolas", 9, "bold")) -> None:
        pal = _status_palette(status, float(sample_viz_state.get("phase") or 0.0))
        rid = _draw_glow_rect(x, y, x + w, y + h, fill=pal["fill"], outline=pal["outline"], glow=pal["glow"], width=2)
        tid = canvas.create_text(x + w / 2, y + h / 2, text=label, fill=pal["text"], font=font, justify="center")
        blocks[key] = rid
        texts[key] = tid

    def _draw_schematic() -> None:
        nonlocal flow_readout_id
        try:
            canvas.delete("all")
        except Exception:
            return

        blocks.clear()
        texts.clear()

        try:
            cw = int(canvas.winfo_width() or 1480)
            ch = int(canvas.winfo_height() or 680)
        except Exception:
            cw, ch = 1480, 680

        phase = float(sample_viz_state.get("phase") or 0.0)
        pulse = 0.5 + 0.5 * math.sin(phase)
        flow_status = str(sample_viz_state.get("flow_status") or "UNKNOWN").upper()
        flow_value = sample_viz_state.get("flow_value")
        flow_active = flow_value is not None
        channel_comm = sample_viz_state.get("channel_comm") or {}
        any_fail = any(str(v or "").upper() == "FAIL" for v in channel_comm.values())
        any_ok = any(str(v or "").upper() == "OK" for v in channel_comm.values())
        gas_status = "ALARM" if any_fail else ("OK" if any_ok else "UNKNOWN")
        source_status = flow_status if flow_active else ("OK" if sample_viz_state.get("engine_age_s") is not None else "UNKNOWN")
        daq_status = "OK" if sample_viz_state.get("daq_age_s") is not None else "UNKNOWN"
        enabled = bool(sample_viz_state.get("anim_enabled"))
        process_live = enabled and flow_active

        # subtle grid
        try:
            for gx in range(0, cw, 28):
                canvas.create_line(gx, 0, gx, ch, fill="#0d1620", width=(2 if gx % 140 == 0 else 1))
            for gy in range(0, ch, 28):
                canvas.create_line(0, gy, cw, gy, fill="#0d1620", width=(2 if gy % 140 == 0 else 1))
        except Exception:
            pass

        source_x = max(28, int(cw * 0.028))
        source_w = max(82, int(cw * 0.068))
        source_h = min(max(176, int(ch * 0.48)), max(190, ch - 150))
        main_y = max(238, int(ch * 0.54))
        upper_y = max(140, main_y - 126)
        source_y = max(84, main_y - int(source_h * 0.66))
        source_cx = source_x + source_w / 2
        drop_x = max(source_x + source_w + 96, int(cw * 0.17))
        knock_x = int(cw * 0.215)
        blk_w = max(132, int(cw * 0.102))
        blk_h = 54
        filter_x = int(cw * 0.34)
        pump_x = int(cw * 0.60)
        filter_cx = filter_x + (blk_w / 2.0)
        pump_cx = pump_x + (blk_w / 2.0)
        valve_x = int((filter_cx + pump_cx) / 2.0)
        gas_w = max(178, int(cw * 0.142))
        gas_h = 60
        gas_x = int(cw * 0.76)
        runner_x = int(gas_x + gas_w / 2)
        runner_y = upper_y - 8
        inline_flow_x = int(cw * 0.25)
        upper_meter_x = inline_flow_x
        upper_meter_y = upper_y - 84
        upper_ref_x = int(cw * 0.47)
        upper_cal_x = int(cw * 0.56)
        can_y = max(74, upper_y - 92)
        lower_flow_box_x = int(((pump_x + blk_w) + gas_x) / 2)
        lower_flow_box_y = main_y - 84
        spike_t_x = inline_flow_x + 36
        daq_label_y = runner_y + 56
        primary_pulse = pulse if enabled else 0.0
        sample_color = _mix_hex("#4d1017", "#ff5d5d", 0.62 + 0.18 * primary_pulse)
        process_color = _mix_hex("#591018", "#ff4747", 0.60 + 0.18 * primary_pulse)
        cal_color = _mix_hex("#14311d", "#4cff87", 0.55 + 0.18 * pulse)
        bus_color = _mix_hex("#2e1449", "#a86cff", 0.62 + 0.16 * pulse)
        data_color = _mix_hex("#4a0f18", "#ff3b60", 0.62 + 0.16 * pulse)
        flow_color = _status_palette(flow_status, phase)["outline"]
        source_pal = _status_palette(source_status, phase)
        sample_line_w = 2.0 + (1.1 * primary_pulse)
        process_line_w = 3.0 + (1.4 * primary_pulse)

        lower_pipe = [
            (drop_x, main_y),
            (knock_x - 16, main_y),
            (knock_x + blk_w / 2, main_y),
            (filter_x + blk_w / 2, main_y),
            (valve_x, main_y),
            (pump_x + blk_w / 2, main_y),
            (gas_x + gas_w / 2, main_y),
        ]
        source_pipe = [
            (source_x + source_w + 8, upper_y),
            (inline_flow_x - 34, upper_y),
            (spike_t_x, upper_y),
        ]
        spike_pipe = [
            (upper_ref_x, can_y + 48),
            (upper_ref_x, upper_y),
            (spike_t_x, upper_y),
        ]
        cal_pipe = [
            (upper_cal_x, can_y + 48),
            (upper_cal_x, main_y - 16),
            (valve_x, main_y - 16),
        ]
        gas_data_line = [
            (runner_x, main_y - gas_h / 2),
            (runner_x, daq_label_y + 14),
        ]

        # Source / exhaust
        _draw_glow_rect(source_x, source_y, source_x + source_w, source_y + source_h, fill="#3d3d3d", outline=source_pal["outline"], glow=source_pal["glow"], width=2)
        canvas.create_oval(source_x, source_y - 6, source_x + source_w, source_y + 10, fill="#505050", outline="#262626", width=1)
        canvas.create_text(source_cx, source_y + source_h / 2, text="SOURCE", fill="#f3f5f7", font=("Consolas", 10, "bold"))
        for idx in range(5):
            rad = 15 + idx * 6 + pulse * 2
            dx = math.sin(phase * 0.7 + idx * 0.6) * (4 + idx * 1.7)
            dy = idx * 16
            _draw_glow_circle(source_cx + dx, source_y - 22 - dy, rad, fill=_mix_hex("#2a2a2a", "#d8d8d8", 0.22), outline="#777777", glow=_mix_hex("#4a4a4a", "#e6e6e6", 0.20), width=1)
        _draw_text_plate(source_x + source_w + 20, upper_y - 34, "EXHAUST", anchor="w", font=("Consolas", 8, "bold"), fill="#f0f3f6", bg="#0d141b", outline="#3d4e61")
        _draw_glow_line([(source_x + source_w, upper_y), (drop_x - 54, upper_y)], sample_color, width=sample_line_w)
        _draw_chevrons(source_x + source_w + 18, upper_y, "#ffffff", phase if enabled else 0.0)

        # Upper spike-recovery lane
        _draw_glow_line(source_pipe, sample_color, width=sample_line_w)
        _draw_flowmeter_icon(inline_flow_x, upper_y, "#dfe7ef", 74)
        _draw_text_plate(inline_flow_x + 78, upper_y - 28, "SPIKE RECOVERY", anchor="w", font=("Consolas", 8, "bold"), fill="#f0f3f6", bg="#0d141b", outline="#465565")
        _draw_label_box(upper_meter_x, upper_meter_y, "FLOWMETER", width=112, height=36, outline="#dfe7ef", fill="#11161d", fg="#f0f3f6")
        _draw_glow_line([(upper_meter_x, upper_meter_y + 18), (upper_meter_x, upper_y - 24)], "#dfe7ef", width=1, arrow="last")

        # Sample drop into treatment path
        _draw_glow_line([(drop_x, upper_y), (drop_x, main_y)], sample_color, width=sample_line_w)

        # Main treatment path
        _draw_glow_line(lower_pipe, process_color if flow_active else _mix_hex("#223040", process_color, 0.35 + (0.10 * primary_pulse)), width=process_line_w, arrow="last")
        if process_live:
            _draw_flow_particles(lower_pipe, _mix_hex("#6e141c", "#ff8b8b", 0.76), phase, count=8, radius=3.0)

        # Conditioning / handling equipment
        _block(int(knock_x), int(main_y - blk_h / 2), blk_w, blk_h, "WATER KNOCKOUT", "knockout", status=flow_status, font=("Consolas", 8, "bold"))
        _block(int(filter_x), int(main_y - blk_h / 2), blk_w, blk_h, "PARTICULATE FILTER", "filter", status=flow_status, font=("Consolas", 8, "bold"))
        _block(int(pump_x), int(main_y - blk_h / 2), blk_w, blk_h, "SAMPLE PUMP", "pump", status=flow_status, font=("Consolas", 8, "bold"))
        _block(int(gas_x), int(main_y - gas_h / 2), gas_w, gas_h, "GAS CELLS", "gas_cells", status=gas_status)
        _draw_knockout_icon(knock_x + blk_w / 2, main_y + 78, "#1da2ff", phase, enabled)
        _draw_filter_icon(filter_x + blk_w / 2, main_y + 78, _mix_hex("#1d310f", "#72ff37", 0.60), phase)
        _draw_valve_icon(valve_x, main_y, _mix_hex("#1e1e1e", "#f3f3f3", 0.35 + 0.15 * pulse))
        _draw_pump_icon(pump_x + blk_w / 2, main_y + 78, _mix_hex("#19340e", "#6aff3e", 0.62), phase)
        _draw_chip_icon(gas_x + 28, main_y, _mix_hex("#582800", "#ffb04a", 0.70), phase, enabled)
        valve_label_y = main_y + 86
        _draw_label_box(valve_x, valve_label_y, "3-WAY BIAS\nVALVE", width=126, height=42, outline="#dfe7ef", fill="#11161d", fg="#f0f3f6")
        _draw_glow_line([(valve_x, valve_label_y - 21), (valve_x, main_y + 24)], "#dfe7ef", width=1, arrow="last")
        try:
            canvas.itemconfigure(texts.get("gas_cells"), font=("Consolas", 9, "bold"))
            gas_title_left = gas_x + 50
            gas_title_right = gas_x + gas_w - 54
            canvas.coords(texts.get("gas_cells"), (gas_title_left + gas_title_right) / 2.0, main_y)
        except Exception:
            pass
        _draw_text_plate(gas_x + gas_w - 18, main_y, "processor", anchor="e", font=("Consolas", 7), fill="#d8c7b0", bg="#0d141b", outline="#5a4b3a", pad_x=3, pad_y=2)

        # Calibration / reference canisters
        _draw_canister(upper_ref_x, can_y, ["RATA GAS", "(REFERENCE)"], fill="#c4d6a0", outline="#718448")
        _draw_canister(upper_cal_x, can_y, ["CALIBRATION", "GAS"], fill="#c4d6a0", outline="#718448")
        _draw_glow_line(spike_pipe, "#c8d074", width=2)
        _draw_glow_line(cal_pipe, cal_color, width=2, arrow="last")
        if process_live:
            _draw_flow_particles(cal_pipe, _mix_hex("#2b5d34", "#7bff92", 0.75), phase * 1.05, count=4, radius=2.4)

        # Secondary flowmeter above pump/gas-cell lane
        _draw_label_box(lower_flow_box_x, lower_flow_box_y, "FLOWMETER", width=112, height=36, outline="#dfe7ef", fill="#11161d", fg="#f0f3f6")
        _draw_glow_line([(lower_flow_box_x, lower_flow_box_y + 18), (lower_flow_box_x, main_y - 18)], "#dfe7ef", width=1, arrow="last")
        _draw_flowmeter_icon(lower_flow_box_x, main_y, "#dfe7ef", 70)

        # DAQ runner and data path
        _draw_monitor_icon(runner_x, runner_y, _status_palette(daq_status, phase)["outline"], phase, enabled)
        _draw_text_plate(runner_x, daq_label_y, "DAQ RUNNER", font=("Consolas", 8, "bold"), fill="#f0f3f6", bg="#0d141b", outline="#4d3a44", pad_x=8, pad_y=4)
        _draw_glow_line(gas_data_line, data_color, width=2, dash=(6, 4), arrow="last")
        if enabled and sample_viz_state.get("daq_age_s") is not None:
            _draw_flow_particles(gas_data_line, "#ff6c84", phase * 1.2, count=4, radius=2.3)

        # Cell manifold / ports
        cells_y = main_y + 124
        manifold_y = cells_y - 22
        card_w = max(66, int(cw * 0.044))
        card_h = 118
        card_gap = 18
        start_x = int(gas_x + gas_w / 2 - ((card_w * 4) + (card_gap * 3)) / 2)
        end_x = start_x + (card_w * 4) + (card_gap * 3)
        _draw_glow_line([(gas_x + gas_w / 2, main_y + gas_h / 2), (gas_x + gas_w / 2, manifold_y)], bus_color, width=2)
        _draw_glow_line([(start_x + card_w / 2, manifold_y), (end_x - card_w / 2, manifold_y)], bus_color, width=2)
        if enabled and any_ok:
            _draw_flow_particles([(start_x + card_w / 2, manifold_y), (end_x - card_w / 2, manifold_y)], "#b995ff", phase * 0.95, count=4, radius=2.2)

        for ci in range(4):
            card_x = start_x + ci * (card_w + card_gap)
            card_cx = card_x + card_w / 2
            slot_a = _sample_slot_snapshot(ci, 0)
            slot_b = _sample_slot_snapshot(ci, 1)
            card_state = "ALARM" if "FAIL" in (slot_a["state"], slot_b["state"]) else ("OK" if "OK" in (slot_a["state"], slot_b["state"]) else "UNKNOWN")
            card_pal = _status_palette(card_state, phase)
            _draw_glow_line([(card_cx, manifold_y), (card_cx, cells_y)], bus_color, width=2)
            _draw_glow_rect(card_x, cells_y, card_x + card_w, cells_y + card_h, fill="#0a0f16", outline=card_pal["outline"], glow=card_pal["glow"], width=2)
            canvas.create_text(card_cx, cells_y + 12, text=f"CELL {ci + 1}", fill=card_pal["text"], font=("Consolas", 8, "bold"))
            for slot_idx, slot in enumerate((slot_a, slot_b)):
                cy = cells_y + 40 + slot_idx * 50
                state = slot["state"]
                if state == "OK":
                    port_pal = _status_palette("OK", phase)
                elif state == "FAIL":
                    port_pal = _status_palette("ALARM", phase)
                elif state == "UNMAPPED":
                    port_pal = _status_palette("UNKNOWN", phase)
                else:
                    port_pal = _status_palette("WARN", phase) if slot["channel_id"] else _status_palette("UNKNOWN", phase)
                _draw_glow_circle(card_cx, cy, 11, fill=port_pal["fill"], outline=port_pal["outline"], glow=port_pal["glow"], width=2)
                canvas.create_text(card_cx, cy, text=f"P{slot_idx + 1}", fill=port_pal["text"], font=("Consolas", 7, "bold"))
                canvas.create_text(card_cx, cy + 19, text=slot["label"], fill=self.FG if slot["channel_id"] else self.MUTED, font=("Consolas", 6, "bold"), justify="center")

        vent_line_y = cells_y + 52
        vent_line_start_x = end_x + 8
        vent_label_x = min(cw - 78, end_x + 58)
        vent_line_end_x = min(cw - 24, vent_label_x + 64)
        _draw_glow_line([(vent_line_start_x, vent_line_y), (vent_line_end_x, vent_line_y)], "#555d66", width=2, arrow="last")
        _draw_text_plate(vent_label_x, cells_y + 30, "VENT", font=("Consolas", 8, "bold"), fill="#f0f3f6", bg="#0d141b", outline="#3d4e61", pad_x=5, pad_y=2)
        _draw_text_plate(start_x + (end_x - start_x) / 2, cells_y + card_h + 18, "Mapped P1 / P2 ports light green when channel comm is verified and red when comm is down.", font=("Consolas", 8), fill=self.MUTED, bg="#0d141b", outline="#233447", pad_x=8, pad_y=4)

        flow_readout_id = _draw_text_plate(
            lower_flow_box_x,
            lower_flow_box_y - 58,
            str(sample_viz_state.get("flow_label") or "FLOW: --"),
            anchor="center",
            font=("Consolas", 11, "bold"),
            fill=flow_color,
            bg="#0d141b",
            outline="#2b4459",
            pad_x=6,
            pad_y=4,
        )

    _draw_schematic()

    def _on_canvas_resize(_evt: object) -> None:
        # Redraw to keep centered when the window resizes.
        try:
            _draw_schematic()
        except Exception:
            pass

    try:
        canvas.bind('<Configure>', _on_canvas_resize)
    except Exception:
        pass

    def _animate_sample_system() -> None:
        try:
            if getattr(self, "current_state", "") != "SAMPLE_SYS":
                return
        except Exception:
            return
        try:
            sample_viz_state["phase"] = float(sample_viz_state.get("phase") or 0.0) + (0.24 if sample_viz_state.get("anim_enabled") else 0.10)
            _draw_schematic()
        except Exception:
            pass
        try:
            self.after(160, _animate_sample_system)
        except Exception:
            return

    try:
        self.after(160, _animate_sample_system)
    except Exception:
        pass

    # ----------------------------- Gas cells mapping (4 cells x 2 ports) -----------------------------
    cells_grid = tk.Frame(cells_box, bg=self.BG)
