    def _preview_on_mousewheel(event) -> None:
        try:
            delta = int(-1 * (event.delta / 120)) if getattr(event, "delta", 0) else 0
            if delta:
                if int(getattr(event, "state", 0)) & 0x0001:
                    preview_canvas.xview_scroll(delta, "units")
                else:
                    preview_canvas.yview_scroll(delta, "units")
        except Exception:
            pass

    def _preview_bind_wheel(_event=None) -> None:
        try:
            preview_canvas.bind_all("<MouseWheel>", _preview_on_mousewheel)
            preview_canvas.bind_all("<Button-4>", lambda e: preview_canvas.yview_scroll(-3, "units"))
            preview_canvas.bind_all("<Button-5>", lambda e: preview_canvas.yview_scroll(3, "units"))
        except Exception:
            pass

    def _preview_unbind_wheel(_event=None) -> None:
        try:
            preview_canvas.unbind_all("<MouseWheel>")
            preview_canvas.unbind_all("<Button-4>")
            preview_canvas.unbind_all("<Button-5>")
        except Exception:
            pass
        try:
            _sample_bind_wheel()
        except Exception:
            pass

    preview_canvas.bind("<Enter>", _preview_bind_wheel)
    preview_canvas.bind("<Leave>", _preview_unbind_wheel)

    def _render_sample_preview_image() -> None:
        img = sample_viz_state.get("print_preview_image")
        if img is None:
            return
        try:
            from PIL import ImageTk  # type: ignore
            display_img = img.copy()
            viewport_w = max(320, int(preview_canvas.winfo_width() or 0) - 18)
            viewport_h = max(180, int(preview_canvas.winfo_height() or 0) - 18)
            iw = int(getattr(display_img, "size", (0, 0))[0] or 0)
            ih = int(getattr(display_img, "size", (0, 0))[1] or 0)
            if iw > 0 and ih > 0:
                scale = min(float(viewport_w) / float(iw), float(viewport_h) / float(ih), 1.0)
                render_w = max(1, int(iw * scale))
                render_h = max(1, int(ih * scale))
                if render_w != iw or render_h != ih:
                    try:
                        display_img = display_img.resize((render_w, render_h))
                    except Exception:
                        display_img.thumbnail((viewport_w, max(viewport_h, ih)))
                else:
                    render_w, render_h = iw, ih
            else:
                render_w, render_h = viewport_w, viewport_h
            photo = ImageTk.PhotoImage(display_img)
            sample_viz_state["print_preview_photo"] = photo
            sample_viz_state["print_preview_display_size"] = (render_w, render_h)
            preview_canvas.delete("preview_image")
            preview_canvas.delete(preview_empty_id)
            offset_x = 8 + max(0, int((viewport_w - render_w) / 2))
            offset_y = 8 + max(0, int((viewport_h - render_h) / 2))
            scroll_w = max(viewport_w + 16, render_w + 16)
            scroll_h = max(viewport_h + 16, render_h + 16)
            preview_canvas.create_image(offset_x, offset_y, image=photo, anchor="nw", tags=("preview_image",))
            preview_canvas.configure(scrollregion=(0, 0, scroll_w, scroll_h))
            preview_canvas.xview_moveto(0.0)
            preview_canvas.yview_moveto(0.0)
        except Exception:
            pass

    def _on_preview_canvas_resize(_event=None) -> None:
        try:
            if sample_viz_state.get("print_preview_image") is not None:
                _render_sample_preview_image()
        except Exception:
            pass

    preview_canvas.bind("<Configure>", _on_preview_canvas_resize)

